		'Unshaven technique available in suitable cases' => 'تقنية بلا حلاقة متاحة في الحالات المناسبة',
		'Will E-max Lumineers stain like natural teeth?' => 'هل تتصبّغ قشور E-max مثل الأسنان الطبيعية؟',
		'Will it look different from my existing beard?' => 'هل سيبدو مختلفاً عن لحيتي الحالية؟',
		'Will the transplanted beard hair keep growing?' => 'هل يستمرّ شعر اللحية المزروع في النمو؟',
		'Can E-max Lumineers fix gaps and crooked teeth?' => 'هل تصلح قشور E-max الفراغات والأسنان المعوجّة؟',
		'Can a hybrid prosthesis be repaired if damaged?' => 'هل يمكن إصلاح التركيبة الهجينة إن تضرّرت؟',
		'Increased salivation for a few nights is normal' => 'زيادة اللعاب لبضع ليالٍ أمر طبيعي',
		'Local anesthesia (optional — often unnecessary)' => 'تخدير موضعي (اختياري — وغالباً غير لازم)',
		'No flying if you can avoid it in the first week' => 'تجنّب السفر جواً في الأسبوع الأول إن أمكن',
		'Report any high spot rather than living with it' => 'أبلغ عن أي نقطة مرتفعة بدل أن تتعايش معها',
		'Told plainly if a transplant is not appropriate' => 'يُقال لك بوضوح إن كانت الزراعة غير مناسبة',
		'What is the success rate of sinus lift surgery?' => 'ما نسبة نجاح جراحة رفع الجيب؟',
		'Design agreed with you before anything is shaved' => 'التصميم يُتَّفق عليه معك قبل أي حلاقة',
		'Direction varied across cheek, jaw and moustache' => 'الاتّجاه يتنوّع بين الخدّ والفكّ والشارب',
		'Told plainly when a transplant is not the answer' => 'يُقال لك بوضوح متى لا تكون الزراعة هي الحلّ',
		'Usually straightforward once the graft has taken' => 'عادةً بلا تعقيد بعد أن يثبت الطُعم',
		'Why Single Dental Implants Are the Gold Standard' => 'لماذا تُعدّ زراعة السنّ الواحدة المعيار الذهبي',
		'Do not blow your nose — open your mouth to sneeze' => 'لا تُمخِّط أنفك — وافتح فمك عند العطس',
		'Hairline drawn with you before anything is shaved' => 'خط الشعر يُرسم معك قبل أي حلاقة',
		'How long does a hybrid zirconium prosthesis last?' => 'كم تدوم التركيبة الهجينة من الزيركون؟',
		'Is hybrid zirconium better than hybrid porcelain?' => 'هل الهجين من الزيركون أفضل من الهجين الخزفي؟',
		'Transplanted brows keep growing and need trimming' => 'الحواجب المزروعة تستمرّ في النمو وتحتاج إلى تقصير',
		'Why Bone Grafting Is Critical for Implant Success' => 'لماذا يُعدّ ترقيع العظم حاسماً لنجاح الزراعة',
		'Why Zygomatic Implants Transform Impossible Cases' => 'لماذا تُنقذ الغرسات الوجنية الحالات المستحيلة',
		'A single day, local anaesthetic, awake throughout.' => 'يوم واحد، بتخدير موضعي، وتبقى مستيقظاً طوال الوقت.',
		'Avoid chewing on that side until sensation returns' => 'لا تمضغ من تلك الجهة حتى يعود الإحساس',
		'Journal of Oral Implantology · Long-term follow-up' => 'Journal of Oral Implantology · متابعة طويلة الأمد',
		'Maló et al., 2019 · Longitudinal study 10–18 years' => 'Maló وزملاؤه، 2019 · دراسة طولية على 10–18 سنة',
		'Persistent facial pain deserves a separate opinion' => 'الألم المستمرّ في الوجه يستحقّ رأياً منفصلاً',
		'Regrowth begins. First trimming becomes necessary.' => 'يبدأ النمو من جديد. ويصبح التقصير الأول ضرورياً.',
		'Shock loss: the transplanted hairs shed. Expected.' => 'التساقط الصدمي: يتساقط الشعر المزروع. وهذا متوقَّع ومؤقّت.',
		'Single-hair grafts through the moustache and edges' => 'طُعوم بشعرة واحدة في الشارب وعلى الحواف',
		'Systematic review · Conventional implant protocols' => 'مراجعة منهجية · بروتوكولات الزراعة التقليدية',
		'What is the success rate vs conventional implants?' => 'ما نسبة النجاح مقارنةً بالزراعة التقليدية؟',
		'Can the graft and implant be done at the same time?' => 'هل يمكن إجراء الترقيع والزراعة في الوقت نفسه؟',
		'Guess et al. (2018) · Journal of Esthetic Dentistry' => 'Guess وزملاؤه (2018) · Journal of Esthetic Dentistry',
		'How many grafts can be taken in one manual session?' => 'كم طُعماً يمكن اقتطافه في جلسة يدوية واحدة؟',
		'Is a custom guard more comfortable than OTC guards?' => 'هل الواقي المفصَّل أريح من الوقايات الجاهزة؟',
		'Not charged for separately without being told first' => 'لا يُحاسَب عليه على حدة دون إخبارك أولاً',
		'Sailer et al. (2015) · Clinical Oral Investigations' => 'Sailer وزملاؤه (2015) · Clinical Oral Investigations',
		'Is there a metal-free option for titanium allergies?' => 'هل يوجد خيار خالٍ من المعادن لمن لديه حساسية من التيتانيوم؟',
		'Time out of body kept as short as the session allows' => 'تقليل مدّة بقاء الطُعوم خارج الجسم قدر ما تسمح به الجلسة',
		'Why Hybrid Prosthesis Offers the Best of Both Worlds' => 'لماذا تجمع التركيبة الهجينة أفضل ما في الخيارين',
		'Will I have sinus problems after zygomatic implants?' => 'هل ستصيبني مشاكل في الجيوب بعد الغرسات الوجنية؟',
		'All-on-4 Dental Implants Full Arch · Fixed · Same Day' => 'زراعة All-on-4: فك كامل · ثابت · في نفس اليوم',
		'Are Turkish implant warranties valid internationally?' => 'هل ضمانات الغرسات التركية سارية دولياً؟',
		'Can the implant be placed the same day as extraction?' => 'هل يمكن وضع الغرسة في يوم الخلع نفسه؟',
		'Donor area assessed before a graft number is promised' => 'تقييم المنطقة المانحة قبل الوعد بأي عدد من الطُعوم',
		'Journal of Periodontology · Alveolar ridge resorption' => 'Journal of Periodontology · امتصاص الحافة السنخية',
		'Shape drawn with you and photographed before starting' => 'الشكل يُرسم معك ويُصوَّر قبل البدء',
		'Stopped at any point if you would rather not continue' => 'تتوقّف في أي لحظة إن فضّلت ألّا تكمل',
		'What is the difference between an inlay and an onlay?' => 'ما الفرق بين الإنلاي والأونلاي؟',
		'Can I eat normally with a hybrid zirconium prosthesis?' => 'هل يمكنني أن آكل بشكل طبيعي بالتركيبة الهجينة من الزيركون؟',
		'Declining it changes nothing else about your treatment' => 'رفضه لا يغيّر شيئاً آخر في علاجك',
		'Density built where it reads, at the part and hairline' => 'الكثافة تُبنى حيث تُرى: عند الفرق وخط الشعر الأمامي',
		'Replace One Missing Tooth with a Single Dental Implant' => 'عوّض سنّاً واحدة مفقودة بغرسة سنّية',
		'Sessions scheduled around your first wash appointment.' => 'الجلسات مبرمَجة حول موعد أول غسل لك.',
		'Systematic review · Full arch prosthetic complications' => 'مراجعة منهجية · المضاعفات التعويضية في الفك الكامل',
		'Take it out if you wake with sharp pain, and report it' => 'انزعه إن استيقظت بألم حادّ، وأبلغ عن ذلك',
		'Clinical Oral Implants Research · Grafted site outcomes' => 'Clinical Oral Implants Research · نتائج المواضع المرقَّعة',
		'Journal of Cosmetic Dermatology · Sapphire FUE outcomes' => 'Journal of Cosmetic Dermatology · نتائج تقنية سفير',
		'Single-hair grafts at the hairline, denser units behind' => 'طُعوم بشعرة واحدة عند خط الشعر، ووحدات أكثف خلفها',
		'Immediate vs delayed placement clinical protocol studies' => 'دراسات سريرية تقارن بروتوكولَي الزراعة الفورية والمؤجَّلة',
		'No smoking: it is the single biggest risk to integration' => 'ممنوع التدخين: فهو أكبر خطر يهدّد الاندماج',
		'Can a hybrid zirconium prosthesis be repaired if damaged?' => 'هل يمكن إصلاح التركيبة الهجينة من الزيركون إن تضرّرت؟',
		'Final shape and density. Trimming continues indefinitely.' => 'الشكل والكثافة النهائيان. أمّا التقصير فيستمرّ بلا نهاية.',
		'Scarring alopecias ruled out before surgery is considered' => 'استبعاد الثعلبات الندبية قبل التفكير في الجراحة',
		'Can implants be placed at the same time as the sinus lift?' => 'هل يمكن وضع الغرسات في الوقت نفسه مع رفع الجيب؟',
		'Journal of Oral Implantology · Long-term follow-up studies' => 'Journal of Oral Implantology · دراسات متابعة طويلة الأمد',
		'Journal of Prosthetic Dentistry · Biocompatibility studies' => 'Journal of Prosthetic Dentistry · دراسات التوافق الحيوي',
		'Two to four hours for most cases, under local anaesthetic.' => 'من ساعتين إلى أربع في معظم الحالات، تحت تخدير موضعي.',
		'Works over acne and burn scarring as well as patchy growth' => 'ينفع على ندوب حبّ الشباب والحروق كما ينفع على النبات المتفرّق',
		'Can I have it done with a scalp procedure at the same time?' => 'هل يمكن إجراؤها مع زراعة فروة الرأس في الوقت نفسه؟',
		'Implant placement scheduled from the scan, not the calendar' => 'موعد وضع الغرسات تحدّده الأشعة، لا الرزنامة',
		'Why this is not the male procedure with a different patient' => 'لماذا ليست هذه عملية الرجال مع مريضة مختلفة',
		'Growth follows the standard timeline; assessed at 12 months.' => 'يسير النمو وفق الجدول الزمني المعتاد؛ ويُقيَّم عند 12 شهراً.',
		'International Journal of Trichology · Blade comparison study' => 'International Journal of Trichology · دراسة مقارنة الشفرات',
		'Offered as an addition, never as a replacement for aftercare' => 'يُقدَّم كإضافة، لا كبديل عن العناية بعد العملية أبداً',
		'Density planned for how it will look grown out, not on day one' => 'الكثافة مخطَّطة لما ستبدو عليه بعد النمو، لا في اليوم الأول',
		'Journal of Prosthetic Dentistry · Patient satisfaction studies' => 'Journal of Prosthetic Dentistry · دراسات رضا المرضى',
		'Shock loss occurs as usual — the protocol does not prevent it.' => 'يحدث التساقط الصدمي المؤقّت كالمعتاد — والبروتوكول لا يمنعه.',
		'The technique is the same. Almost everything around it is not.' => 'التقنية هي نفسها. أمّا كل ما حولها تقريباً فليس كذلك.',
		'Immediate Dental Implants Extraction + Implant · One Appointment' => 'الزراعة الفورية للأسنان: خلع + غرسة · موعد واحد',
		'Shock loss: transplanted hairs shed. Expected, and not a failure.' => 'التساقط الصدمي: يتساقط الشعر المزروع. وهذا متوقَّع ومؤقّت، وليس فشلاً.',
		'Crusts separate. The brow looks close to normal to anyone but you.' => 'تنفصل القشور. ويبدو الحاجب قريباً من الطبيعي لكل أحد إلا لك أنت.',
		'Small crusts on the brow. Mild swelling around the eyes is common.' => 'قشور صغيرة على الحاجب. وتورّم خفيف حول العينين أمر شائع.',
		'Thickening and texture match. Assessment photographs at 12 months.' => 'يزداد السماكة وتتوافق الملمس مع الشعر المحيط. وصور التقييم عند 12 شهراً.',
		'Can a transplant fix a receding hairline from braids or extensions?' => 'هل تُصلح الزراعة خط شعر تراجع بسبب الضفائر أو الوصلات؟',
		'Crusts separate after the washing protocol. Donor area closes over.' => 'تنفصل القشور مع اتّباع بروتوكول الغسل. وتنغلق المنطقة المانحة.',
		'Sensitivity that worsens rather than settles: tell your coordinator' => 'حساسية تزداد بدل أن تهدأ: أخبر منسّقك',
		'Female cases are assessed later than male cases, often at 18 months.' => 'تُقيَّم حالات النساء في وقت أبعد من حالات الرجال، غالباً عند 18 شهراً.',
		'New growth begins, initially fine and lighter than surrounding hair.' => 'يبدأ النمو الجديد، رفيعاً في البداية وأفتح لوناً من الشعر المحيط.',
		'Growth begins. Texture is initially finer than surrounding beard hair.' => 'يبدأ النمو. والملمس في البداية أرقّ من شعر اللحية المحيط.',
		'Mild swelling and redness. With no-shave, hair covers the area immediately.' => 'تورّم خفيف واحمرار. ومع تقنية بلا حلاقة، يغطّي الشعر المنطقة فوراً.',
		'Shock loss: transplanted hairs shed. This is expected — the follicle stays.' => 'التساقط الصدمي: يتساقط الشعر المزروع. وهذا متوقَّع ومؤقّت — أمّا الجُريب فيبقى.',
		'Crusts separate with the washing protocol. Redness fades over days to weeks.' => 'تنفصل القشور مع بروتوكول الغسل. ويخفّ الاحمرار خلال أيام إلى أسابيع.',
		'Swelling of the forehead is common and settles. Sleep with the head elevated.' => 'تورّم الجبهة شائع ويزول. نَم ورأسك مرفوع.',
		'The assessment stage matters more here than anywhere else in hair restoration.' => 'مرحلة التقييم هنا أهمّ منها في أي مجال آخر من استعادة الشعر.',
		'Redness and small crusts across the beard area. Mild facial swelling is common.' => 'احمرار وقشور صغيرة على منطقة اللحية كلّها. وتورّم خفيف في الوجه أمر شائع.',
		'Full texture and density. Trimming and shaving normally resumed long before this.' => 'الملمس والكثافة النهائيان. أمّا التقصير والحلاقة فيكونان قد استُؤنفا قبل ذلك بكثير.',
		'From consultation to fitting — the entire process takes just 2–3 days in Istanbul.' => 'من الاستشارة إلى التجربة — لا يستغرق المسار كلّه سوى 2 إلى 3 أيام في إسطنبول.',
		'Longer hair hides most of this, which is one practical advantage of the female case.' => 'الشعر الطويل يخفي معظم ذلك، وهذه ميزة عملية في حالة النساء.',
		'The brows look their strangest around day three and normal again inside a fortnight.' => 'يبلغ الحاجبان أغرب مظهر لهما نحو اليوم الثالث، ويعودان طبيعيين خلال أسبوعين.',
		'Nothing here is unusual and none of it is a complication. It is what healing looks like.' => 'لا شيء ممّا هنا غير معتاد، ولا شيء منه مضاعفة. هذا ببساطة شكل الالتئام.',
		'Facial skin heals fast and visibly. Plan for the crusting to be obvious for about a week.' => 'جلد الوجه يلتئم بسرعة وبشكل ظاهر. فاحسب أسبوعاً تقريباً تكون فيه القشور واضحة.',
		'Short sessions in the days after your procedure, usually while you are still in Istanbul.' => 'جلسات قصيرة في الأيام التالية لعمليتك، عادةً وأنت ما زلت في إسطنبول.',
		'A complete clinical and practical comparison across all relevant tooth replacement protocols.' => 'مقارنة سريرية وعملية كاملة بين جميع بروتوكولات تعويض السن ذات الصلة.',
		'Numbness lasts two to three hours. Eat once you can feel your lip again, or you will bite it.' => 'يستمرّ الخدر ساعتين إلى ثلاث. لا تأكل حتى تعود إليك الإحساس بشفتك، وإلا عضضتها.',
		'Shock loss affects both transplanted and some surrounding native hairs. Native hair recovers.' => 'يصيب التساقط الصدمي الشعر المزروع وبعض الشعر الأصلي المحيط. أمّا الشعر الأصلي فيعود.',
		'Popular dental tourism hub for North American patients. Border-city clinics dominate the market.' => 'وجهة رائجة لسياحة الأسنان لمرضى أمريكا الشمالية. وتهيمن عيادات المدن الحدودية على السوق.',
		'High clinical and lab fees. Limited NHS coverage for implants. Long waiting lists at major centres.' => 'أتعاب عيادات ومختبرات مرتفعة. تغطية محدودة جداً للغرسات من هيئة الصحة البريطانية. وقوائم انتظار طويلة في المراكز الكبرى.',
		'A guard wears out. Once it has worn through anywhere it is no longer protecting the tooth underneath.' => 'الواقي يتآكل. وحين يُثقب في أي موضع، لم يعد يحمي السنّ التي تحته.',
		'Hairs are placed one at a time, curvature turned so each one lies the way it should against the skin.' => 'تُزرع الشعرات واحدةً واحدة، ويُدار انحناء كل شعرة لتستلقي على الجلد كما ينبغي.',
		'From 3D planning to bone graft maturation and implant placement — typically 6–9 months total timeline.' => 'من التخطيط ثلاثي الأبعاد إلى نضج الطُعم ووضع الغرسات — عادةً 6 إلى 9 أشهر إجمالاً.',
		'It feels bulky for the first three or four nights and most people salivate more at first. Both settle.' => 'تُحسّ به ضخماً في الليالي الثلاث أو الأربع الأولى، ويزيد اللعاب عند معظم الناس في البداية. وكلاهما يزول.',
		'Low treatment costs and experienced surgeons. Clinic quality varies — accreditation research essential.' => 'تكاليف علاج منخفضة وجرّاحون ذوو خبرة. لكن جودة العيادات متفاوتة — والتحقّق من الاعتمادات ضروري.',
		'Sutures come out or dissolve. The sinus membrane is healing and the graft is stabilising underneath it.' => 'تُنزع الغرز أو تذوب. ويلتئم غشاء الجيب بينما يستقرّ الطُعم تحته.',
		'Western Europe higher; Eastern Europe (Poland, Hungary) more competitive but still 2–3× Turkey pricing.' => 'أوروبا الغربية أغلى؛ وأوروبا الشرقية (بولندا والمجر) أكثر تنافسية لكنها لا تزال بضعفَي أو ثلاثة أضعاف أسعار تركيا.',
		'Wide cost range depending on materials, state, and practice location. Insurance rarely covers implants.' => 'تفاوت واسع في التكلفة حسب المواد والولاية وموقع العيادة. ونادراً ما يغطّي التأمين الغرسات.',
		'Popular hub for North American patients. Quality of immediate protocol experience varies across clinics.' => 'وجهة مفضّلة لمرضى أمريكا الشمالية. وتتفاوت الخبرة في البروتوكول الفوري تفاوتاً كبيراً بين العيادات.',
		'From consultation to final bonding — the entire process typically requires one 3–5 day visit to Istanbul.' => 'من الاستشارة إلى اللصق النهائي — يتطلّب المسار كلّه عادةً زيارة واحدة من 3 إلى 5 أيام في إسطنبول.',
		'Once the scan shows adequate height and density, implants are placed as a separate, much smaller procedure.' => 'بعد أن تُظهر الأشعة ارتفاعاً وكثافة كافيين، تُوضع الغرسات في عملية منفصلة أخفّ بكثير.',
		'You return to Istanbul for the permanent prosthesis, fitted after the tissue has settled to its final shape.' => 'تعود إلى إسطنبول للتعويض الدائم، ويُركَّب بعد أن تستقرّ الأنسجة على شكلها النهائي.',
		'High private dentistry costs. Some health fund contribution may apply to crown or extraction components only.' => 'تكاليف مرتفعة في طب الأسنان الخاص. وقد تساهم صناديق التأمين الصحي في تكلفة التلبيسة أو الخلع فقط.',
		'It should seat without force and come off without a struggle. Pressure on one tooth means it needs adjusting.' => 'يجب أن يستقرّ في مكانه دون قوة ويُنزع دون عناء. والضغط على سنّ واحدة يعني أنه يحتاج ضبطاً.',
		'Private market only. NHS does not cover implants. Immediate protocol available at specialist implant centres.' => 'القطاع الخاص فقط. ولا تغطي هيئة الصحة الوطنية البريطانية زراعة الأسنان. والبروتوكول الفوري متاح في مراكز الزراعة المتخصّصة.',
		'Wide state-by-state variation. Immediate protocol increasingly standard at specialist oral surgery practices.' => 'تفاوت كبير من ولاية إلى أخرى. والبروتوكول الفوري صار معياراً متزايداً في عيادات جراحة الفم المتخصّصة.',
		'From implant placement to final hybrid restoration — typically requires two visits to Istanbul over 5–6 months.' => 'من وضع الغرسات إلى التعويض الهجين النهائي — عادةً زيارتان إلى إسطنبول على مدى 5 إلى 6 أشهر.',
		'Per inlay/onlay — porcelain or zirconia, CAD/CAM precision milling, two-visit procedure, and warranty included.' => 'لكل حشوة إنلاي أو أونلاي — خزف أو زيركون، وخرط دقيق بتقنية CAD/CAM، وإجراء على زيارتين، والضمان مشمول.',
		'Competitive pricing and growing expertise. Clinic accreditation and brand verification essential before booking.' => 'أسعار تنافسية وخبرة متنامية. من الضروري التحقّق من اعتماد العيادة ومن ماركة الغرسات قبل الحجز.',
		'From consultation to final crown — the entire process typically requires two visits to Istanbul over 4–6 months.' => 'من الاستشارة إلى التلبيسة النهائية — يتطلّب المسار كلّه عادةً زيارتين إلى إسطنبول على مدى 4 إلى 6 أشهر.',
		'Swelling peaks around the second day. You leave with a fixed provisional bridge, so you are never without teeth.' => 'يبلغ التورّم ذروته نحو اليوم الثاني. وتغادر بجسر مؤقت ثابت، فلا تبقى بلا أسنان في أي لحظة.',
		'Density is only half of it. Most of the difficulty is in direction, and most bad results are bad for that reason.' => 'الكثافة نصف المسألة فقط. فمعظم الصعوبة في الاتّجاه، ولهذا السبب تحديداً تكون معظم النتائج السيّئة سيّئة.',
		'Single hairs go to the borders, denser units into the body of the beard where they will not be read individually.' => 'الشعرات المفردة تذهب إلى الحواف، والوحدات الأكثف إلى جسم اللحية حيث لا تُرى واحدةً واحدة.',
		'Understanding the clinical and practical differences helps you choose the approach best suited to your situation.' => 'فهم الفروق السريرية والعملية يساعدك على اختيار الحلّ الأنسب لحالتك.',
		'Per veneer — includes consultation, digital design, minimal prep, E-max fabrication, bonding, and 10-year warranty.' => 'لكل قشرة — تشمل الاستشارة، والتصميم الرقمي، والتحضير الأدنى، وتصنيع E-max، واللصق، وضمان 10 سنوات.',
		'From your CBCT scan in Istanbul to your final crown — every stage explained with complete transparency by VeaHealth.' => 'من أشعة CBCT في إسطنبول إلى تلبيستك النهائية — كل مرحلة تشرحها VeaHealth بشفافية كاملة.',
		'A brow is a few hundred grafts against a scalp case of several thousand. It is not a smaller version of the same job.' => 'الحاجب بضع مئات من الطُعوم مقابل عدّة آلاف في حالة فروة الرأس. وهو ليس نسخة مصغَّرة من العمل نفسه.',
		'From consultation to final prosthesis — the entire journey typically requires two visits to Istanbul over 5–6 months.' => 'من الاستشارة إلى التعويض النهائي — يتطلّب المسار كلّه عادةً زيارتين إلى إسطنبول على مدى 5 إلى 6 أشهر.',
		'From your first consultation in Istanbul to your final smile — every step mapped out with precision and transparency.' => 'من استشارتك الأولى في إسطنبول إلى ابتسامتك النهائية — كل خطوة مرسومة بدقّة وشفافية.',
		'Often yes, if your donor supply allows for both. It is planned at assessment so the donor area is not over-harvested.' => 'غالباً نعم، إن كان مخزونك المانح يكفي للاثنين. ويُخطَّط لذلك أثناء التقييم كي لا تُستنزف المنطقة المانحة.',
		'Whatever was done is written into your treatment record, so any clinician you see at home knows exactly what you had.' => 'يُدوَّن كل ما أُجري في ملفّ علاجك، حتى يعرف أي طبيب تراجعه في بلدك بالضبط ما الذي تلقّيته.',
		'The restoration is bonded and fully functional immediately. Any sensitivity to temperature settles over the first week.' => 'التعويض ملصوق وعامل تماماً منذ اللحظة الأولى. وأي حساسية للحرارة تهدأ خلال الأسبوع الأول.',
		'Yes, at any point, and it will not affect the rest of your treatment. Standard aftercare is what your result depends on.' => 'نعم، في أي لحظة، ولن يؤثّر ذلك على بقية علاجك. فنتيجتك تتوقّف على العناية المعتادة بعد العملية.',
		'From digital scan to final cementation — the entire process typically requires 2 clinic visits over 3–5 days in Istanbul.' => 'من المسح الرقمي إلى التثبيت النهائي — يتطلّب المسار كلّه عادةً زيارتين إلى العيادة على مدى 3 إلى 5 أيام في إسطنبول.',
		'Implant survival rate over 10 to 18 years of continuous clinical follow-up — confirming All-on-4 as a long-term solution.' => 'معدّل بقاء الغرسات على مدى 10 إلى 18 سنة من المتابعة السريرية المتواصلة — وهو ما يؤكّد أن All-on-4 حلّ طويل الأمد.',
		'Short supervised sessions at the clinic, scheduled around your washing appointments so you are not making extra journeys.' => 'جلسات قصيرة تحت إشراف في العيادة، مبرمَجة حول مواعيد الغسل حتى لا تتنقّل مرات إضافية.',
		'The implants fuse to the bone. This is the part that cannot be hurried and the reason the final bridge is not fitted yet.' => 'تلتحم الغرسات بالعظم. وهذه هي المرحلة التي لا يمكن استعجالها، وهي سبب تأجيل تركيب الجسر النهائي.',
		'All-inclusive custom night guard package — consultation, digital impressions, lab fabrication, fitting, and case included.' => 'باقة شاملة لواقٍ ليلي مفصَّل — الاستشارة، والطبعات الرقمية، والتصنيع في المختبر، والتجربة، والعلبة.',
		'From the hours after surgery through to your definitive crown — what to expect at each stage of immediate implant healing.' => 'من الساعات التي تلي الجراحة إلى تلبيستك النهائية — ما الذي تتوقّعه في كل مرحلة من التئام الغرسة الفورية.',
		'If the bite feels even slightly high, it needs adjusting. It will not wear in on its own and leaving it stresses the tooth.' => 'إذا أحسست بأن الإطباق مرتفع ولو قليلاً، فهو يحتاج ضبطاً. فلن يتآكل من تلقاء نفسه، وتركه على حاله يُجهد السن.',
		'All-inclusive zygomatic package — 2-4 zygomatic implants, surgery, temporary teeth, final prosthesis, and lifetime warranty.' => 'باقة وجنية شاملة — 2 إلى 4 غرسات وجنية، والجراحة، والأسنان المؤقتة، والتعويض النهائي، وضمان مدى الحياة.',
		'Standard two-visit protocol — first visit for preparation and impression, second visit one week later for permanent bonding.' => 'بروتوكول معتاد على زيارتين — الأولى للتحضير وأخذ الطبعة، والثانية بعد أسبوع للّصق النهائي.',
		'Bone graft becomes bone capable of holding an implant. The wait is the whole point of the procedure and it cannot be shortened.' => 'يتحوّل الطُعم إلى عظم قادر على حمل غرسة. وهذا الانتظار هو الغاية من العملية كلّها، ولا يمكن اختصاره.',
		'All-inclusive zirconium crown package — tooth preparation, digital impression, lab fabrication, final cementation, and warranty.' => 'باقة شاملة لتلبيسة الزيركون — تحضير السن، والطبعة الرقمية، والتصنيع في المختبر، والتثبيت النهائي، والضمان.',
		'Prosthesis survival rate over the same period — the full-arch bridge remained stable and functional in nearly all cases studied.' => 'معدّل بقاء التعويض خلال المدّة نفسها — إذ ظلّ جسر الفك الكامل ثابتاً وعاملاً في جميع الحالات المدروسة تقريباً.',
		'All-inclusive All-on-6 package per arch — 6 implants, surgery, temporary teeth, final zirconia prosthesis, and lifetime warranty.' => 'باقة All-on-6 شاملة لكل فك — 6 غرسات، والجراحة، والأسنان المؤقتة، وتعويض الزيركون النهائي، وضمان مدى الحياة.',
		'Transparent pricing. Straumann & Nobel Biocare brands. CAD/CAM technology. English-speaking team. International warranty included.' => 'أسعار شفّافة. ماركتا Straumann وNobel Biocare. تقنية CAD/CAM. فريق يتحدّث الإنجليزية. ضمان دولي مشمول.',
		'VeaHealth locks in your price before travel. All costs include CBCT, surgery, bone graft, collagen membrane, and post-op monitoring.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر أشعة CBCT، والجراحة، والطُعم العظمي، والغشاء الكولاجيني، والمتابعة بعد الجراحة.',
		'Grafts are taken from the lower back of the head under local anaesthetic, sorted by hair count, and kept in chilled holding solution.' => 'تُؤخذ الطُعوم من أسفل مؤخّرة الرأس تحت تخدير موضعي، وتُفرز حسب عدد الشعرات، وتُحفظ في محلول مبرَّد.',
		'All-inclusive 1cc bone graft package — consultation, 3D scan, surgery, premium graft material, PRF membrane, and follow-up monitoring.' => 'باقة شاملة لترقيع 1 سم³ — الاستشارة، والأشعة ثلاثية الأبعاد، والجراحة، ومادة ترقيع من الفئة الأولى، وغشاء PRF، والمتابعة.',
		'All-inclusive full arch restoration package — consultation, surgery, temporary teeth, final prosthesis, and lifetime implant warranty.' => 'باقة شاملة لتعويض فكّ كامل — الاستشارة، والجراحة، والأسنان المؤقتة، والتعويض النهائي، وضمان مدى الحياة على الغرسات.',
		'All-inclusive single implant package — implant placement, healing abutment, final crown, and lifetime warranty on the titanium fixture.' => 'باقة شاملة لغرسة واحدة — وضع الغرسة، ودعامة الالتئام، والتلبيسة النهائية، وضمان مدى الحياة على جزء التيتانيوم.',
		'All-inclusive sinus lift per side — lateral window technique, premium bone graft, collagen membrane, CBCT scan, and post-op monitoring.' => 'باقة شاملة لكل جهة — تقنية النافذة الجانبية، ومادة ترقيع من الفئة الأولى، وغشاء كولاجيني، وأشعة CBCT، ومتابعة بعد الجراحة.',
		'E-max Lumineers require minimal recovery and simple maintenance. Most patients resume normal activities immediately with zero downtime.' => 'لا تكاد قشور E-max تتطلّب فترة تعافٍ، وعنايتها بسيطة. ويعود معظم المرضى إلى نشاطهم فوراً دون أي توقّف.',
		'All-inclusive hybrid prosthesis package per arch — implants, surgery, temporary teeth, final porcelain-acrylic restoration, and warranty.' => 'باقة شاملة للتركيبة الهجينة لكل فك — الغرسات، والجراحة، والأسنان المؤقتة، والتعويض النهائي من الخزف والأكريل، والضمان.',
		'One long day, or two shorter ones for a large area. You are awake throughout and you can talk, listen to something, and eat at the break.' => 'يوم واحد طويل، أو يومان أقصر إن كانت المساحة كبيرة. وتبقى مستيقظاً طوال الوقت: تستطيع أن تتكلّم، وأن تستمع إلى شيء، وأن تأكل في الاستراحة.',
		'Sapphire FUE recovery is fast and predictable. Most patients return to work within 5–7 days, with full hair growth achieved by 12 months.' => 'التعافي بعد تقنية سفير سريع ومتوقَّع. ويعود معظم المرضى إلى العمل خلال 5 إلى 7 أيام، ويكتمل نمو الشعر بعد 12 شهراً.',
		'Sutures dissolve or are removed. Comfort improves quickly, but the implants underneath are not yet integrated and the diet protects them.' => 'تذوب الغرز أو تُنزع. وتتحسّن راحتك بسرعة، لكن الغرسات في الأسفل لم تندمج بعد، والنظام الغذائي الطري هو ما يحميها.',
		'VeaHealth locks in your price before travel. All costs include implants, surgery, temporary teeth, final hybrid prosthesis, and warranty.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر الغرسات، والجراحة، والأسنان المؤقتة، والتركيبة الهجينة النهائية، والضمان.',
		'Morning jaw ache and headache usually reduce over the first few weeks. The guard protects the teeth; it does not stop the grinding itself.' => 'يقلّ عادةً وجع الفك والصداع الصباحي خلال الأسابيع الأولى. فالواقي يحمي الأسنان، لكنه لا يوقف الصرير نفسه.',
		'Single implant survival over 10 years — both approaches deliver comparable long-term results within their respective clinical indications.' => 'بقاء الغرسات المفردة بعد 10 سنوات — فالنهجان يعطيان نتائج متقاربة على المدى الطويل، كلّ في استطبابه.',
		'Straumann & Nobel Biocare guaranteed. Socket graft included. CAD/CAM zirconia crown. VeaHealth full coordination & international warranty.' => 'غرسات Straumann وNobel Biocare مضمونة. ترقيع السِنخ مشمول. تلبيسة زيركون بتقنية CAD/CAM. تنسيق كامل من VeaHealth وضمان دولي.',
		'Hairs at the head of the brow sweep upward, the mid-brow runs outward, the tail angles down. Each region is incised separately to follow it.' => 'شعر رأس الحاجب يتّجه إلى الأعلى، ووسطه يمتدّ إلى الخارج، وذيله ينحدر إلى الأسفل. ولكل منطقة شقوقها الخاصة لتتبع هذا الاتّجاه.',
		'There is no rotational friction, so no heat generated at the punch tip. Thermal injury to the surrounding tissue is not part of the picture.' => 'لا يوجد احتكاك دوراني، فلا تتولّد حرارة عند طرف الأداة. وبذلك تخرج الإصابة الحرارية للنسيج المحيط من الحساب أصلاً.',
		'VeaHealth locks in your price before travel. All costs include consultation, minimal prep, E-max fabrication, bonding, and 10-year warranty.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر الاستشارة، والتحضير الأدنى، وتصنيع E-max، واللصق، وضمان 10 سنوات.',
		'Brow hairs lie almost against the skin. Sites are opened at roughly 10 to 15 degrees; anything steeper and the hair stands away from the face.' => 'شعر الحاجب يكاد يستلقي على الجلد. وتُفتح المواضع بزاوية 10 إلى 15 درجة تقريباً؛ وأي زاوية أحدّ من ذلك تجعل الشعرة تبتعد عن الوجه.',
		'All-inclusive hybrid zirconium package per arch — implants, surgery, temporary teeth, final zirconia-acrylic restoration, and extended warranty.' => 'باقة شاملة للتركيبة الهجينة من الزيركون لكل فك — الغرسات، والجراحة، والأسنان المؤقتة، والتعويض النهائي من الزيركون والأكريل، وضمان ممتدّ.',
		'Finer hair is chosen deliberately — usually from above the ear or the nape, where calibre is closest to brow hair rather than the coarser crown.' => 'يُختار الشعر الأرقّ عمداً — عادةً من فوق الأذن أو من القفا، حيث يقترب سُمكه من شعر الحاجب، بدل شعر التاج الأخشن.',
		'Graft survival rate with Sapphire FUE technique — 10–15% higher than traditional steel FUE due to reduced trauma and precision channel creation.' => 'معدّل بقاء الطُعوم بتقنية سفير — أعلى بنسبة 10 إلى 15٪ من تقنية FUE الفولاذية التقليدية بفضل قلّة الرضّ ودقّة فتح القنوات.',
		'VeaHealth locks in your price before travel. All costs include consultation, digital impressions, lab fabrication, fitting, and protective case.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر الاستشارة، والطبعات الرقمية، والتصنيع في المختبر، والتجربة، والعلبة الواقية.',
		'Yes, once your surgeon clears it — usually a few weeks after the procedure. Shaving too early risks dislodging grafts that have not yet secured.' => 'نعم، حين يأذن لك جرّاحك — عادةً بعد أسابيع قليلة من العملية. أمّا الحلاقة المبكّرة فقد تُزحزح طُعوماً لم تثبت بعد.',
		'All-inclusive Sapphire FUE package — consultation, hairline design, extraction, implantation, PRP treatment, medications, and 12-month follow-up.' => 'باقة سفير شاملة — الاستشارة، ورسم خط الشعر، والاقتطاف، والزراعة، وجلسة بلازما PRP، والأدوية، ومتابعة 12 شهراً.',
		'VeaHealth locks in your price before travel. All costs include 3D scan, surgery, premium graft material, PRF, membrane, and follow-up monitoring.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر الأشعة ثلاثية الأبعاد، والجراحة، ومادة ترقيع من الفئة الأولى، وPRF، والغشاء، والمتابعة.',
		'A bonded ceramic restoration is maintained exactly like a natural tooth. It is the margin that fails first, and that is what the check-ups look at.' => 'التعويض الخزفي الملصوق يُعتنى به تماماً كسنّ طبيعية. والحافة هي أول ما يفشل، وهي ما تراقبه الفحوصات الدورية.',
		'Brow hairs grow individually. A two-hair graft anywhere in a brow shows as a tuft, and once it has grown in there is no discreet way to correct it.' => 'شعر الحاجب ينبت مفرداً. والطُعم بشعرتين في أي موضع من الحاجب يظهر خُصلةً، وبعد أن ينمو لا توجد طريقة خفيّة لتصحيحه.',
		'VeaHealth locks in your price before travel. All costs include implants, surgery, temporary teeth, final hybrid zirconium prosthesis, and warranty.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر الغرسات، والجراحة، والأسنان المؤقتة، والتركيبة الهجينة النهائية من الزيركون، والضمان.',
		'Extraction is spread across the safe donor zone rather than concentrated, so the back of the head thins evenly instead of showing a harvested patch.' => 'يُوزَّع الاقتطاف على كامل المنطقة المانحة الآمنة بدل أن يتركّز، فتخفّ مؤخّرة الرأس بانتظام بدل أن تظهر فيها رقعة مقتطَفة.',
		'From consultation to full growth — the complete journey typically requires one 2-day visit to Istanbul followed by 12 months of natural hair growth.' => 'من الاستشارة إلى اكتمال النمو — يتطلّب المسار عادةً زيارة واحدة إلى إسطنبول ليومين، يتبعها 12 شهراً من النمو الطبيعي.',
		'VeaHealth locks in your price before travel. All costs include preparation, lab fabrication, temporary restoration, permanent bonding, and warranty.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر التحضير، والتصنيع في المختبر، والتعويض المؤقت، واللصق النهائي، والضمان.',
		'Honestly stated: fewer grafts per day than motorised FUE. A large area may need two days rather than one, and your quote will say so before you book.' => 'لنقلها بصراحة: طُعوم أقل في اليوم مقارنةً بتقنية FUE الآلية. وقد تحتاج المساحة الكبيرة يومين بدل يوم واحد، وسيقول لك عرض السعر ذلك قبل أن تحجز.',
		'It depends on the clinic and the package. Ask for it to be itemised in your written quote before you travel so there is no charge you did not expect.' => 'يتوقّف ذلك على العيادة وعلى الباقة. اطلب أن يُذكَر بنداً مستقلاً في عرض السعر المكتوب قبل سفرك، حتى لا تفاجئك أي تكلفة.',
		'Hair is taken from the lower occipital scalp, where calibre and texture come closest to beard hair. It keeps growing scalp-fast, so it needs trimming.' => 'يُؤخذ الشعر من أسفل المنطقة القذالية حيث يقترب سُمكه وملمسه أكثر ما يكون من شعر اللحية. وهو يظلّ ينمو بسرعة شعر الرأس، فيحتاج إلى تقصير.',
		'Manual extraction is not automatically better than motorised. It is better at some things, and those things are worth understanding before you choose.' => 'الاقتطاف اليدوي ليس أفضل تلقائياً من الآلي. بل هو أفضل في أمور بعينها، وتلك الأمور تستحقّ أن تُفهم قبل أن تختار.',
		'Brow shapes date. The design is drawn to your bone structure rather than to whatever shape is current, because this is not a shape you can grow out of.' => 'أشكال الحواجب تتقادم. ولذلك يُرسم التصميم على بنية عظام وجهك لا على الشكل الرائج، لأن هذا شكل لا يمكنك التخلّص منه بتركه ينمو.',
		'Implants fuse with jawbone over 4–6 months. You wear temporary teeth and return home. VeaHealth monitors healing remotely with regular photo check-ins.' => 'تلتحم الغرسات بعظم فكّك خلال 4 إلى 6 أشهر. وتعود إلى بيتك بالأسنان المؤقتة. وتتابع VeaHealth الالتئام عن بُعد بصور منتظمة.',
		'The moustache border, the cheek line and the jaw edge take single-hair grafts. Multi-hair units there produce tufting, which is not fixable afterwards.' => 'حدّ الشارب، وخط الخدّ، وحافة الفكّ تأخذ طُعوماً بشعرة واحدة. أمّا الوحدات متعدّدة الشعرات فتُنتج هناك خُصلاً، ولا يمكن إصلاح ذلك بعدها.',
		'VeaHealth locks in your price before travel. All costs include surgery, implants, temporary teeth, final prosthesis, and lifetime warranty on fixtures.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر الجراحة، والغرسات، والأسنان المؤقتة، والتعويض النهائي، وضمان مدى الحياة على الغرسات.',
		'E-max Lumineers combine the strength of lithium disilicate ceramic with ultra-thin design — offering unmatched aesthetics with minimal tooth alteration.' => 'تجمع قشور E-max بين قوة خزف ثنائي سيليكات الليثيوم والتصميم فائق الرقّة — فتعطي جمالاً لا نظير له مع أقلّ تدخّل ممكن في السن.',
		'The recovery below is the recovery from your transplant. The protocol is intended to make the first few days of it more comfortable — not to shorten it.' => 'التعافي المذكور أدناه هو تعافيك من الزراعة. والغرض من البروتوكول أن يجعل أيامه الأولى أكثر راحة — لا أن يختصره.',
		'VeaHealth locks in your price before travel. All costs include consultation, surgery, PRP treatment, medications, aftercare kit, and 12-month follow-up.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر الاستشارة، والعملية، وجلسة البلازما PRP، والأدوية، وحقيبة العناية، ومتابعة 12 شهراً.',
		'A single dental implant is the only tooth replacement that preserves bone, protects adjacent teeth, and delivers lifetime functionality with proper care.' => 'زراعة السنّ الواحدة هي التعويض الوحيد الذي يحافظ على العظم، ويحمي الأسنان المجاورة، ويؤدّي وظيفته مدى الحياة مع عناية سليمة.',
		'Most patients fly the day after the procedure, following the first wash at the clinic. Your coordinator will schedule the flight around that appointment.' => 'يسافر معظم المرضى جواً في اليوم التالي للعملية، بعد أول غسل في العيادة. وينسّق منسّقك موعد رحلتك حول ذلك الموعد.',
		'Photographs, history and blood work. If the thinning has a medical cause, treating that comes first — and if it resolves the loss, no surgery is offered.' => 'صور، وتاريخ مرضي، وتحاليل دم. فإن كان لخفّة الشعر سبب طبي، فعلاجه يأتي أولاً — وإن حلّ ذلك المشكلة، فلا تُعرَض أي جراحة.',
		'VeaHealth locks in your price before travel. All costs include 6 implants, surgery, temporary teeth, final prosthesis, and lifetime warranty on fixtures.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر 6 غرسات، والجراحة، والأسنان المؤقتة، والتعويض النهائي، وضمان مدى الحياة على الغرسات.',
		'All-on-6 recovery is gradual but predictable. Most patients resume normal activities within 7–10 days and achieve full chewing function within 4–6 months.' => 'التعافي بعد All-on-6 تدريجي لكنه متوقَّع. ويعود معظم المرضى إلى نشاطهم المعتاد خلال 7 إلى 10 أيام، وإلى المضغ الكامل خلال 4 إلى 6 أشهر.',
		'Swelling and some bruising below the eye are expected after a lateral window lift. Bleeding from the nose on that side can happen and is not an emergency.' => 'من المتوقّع حدوث تورّم وبعض الكدمات تحت العين بعد الرفع عبر النافذة الجانبية. وقد ينزف الأنف من تلك الجهة، وهذا ليس حالة طارئة.',
		'Implant survival rate for All-on-6 at 10 years — slightly higher than All-on-4 due to enhanced load distribution and reduced stress on individual fixtures.' => 'معدّل بقاء الغرسات في All-on-6 بعد 10 سنوات — أعلى قليلاً من All-on-4 بفضل التوزيع الأفضل للقوى وقلّة الإجهاد على كل غرسة.',
		'Single implant recovery is predictable and straightforward. Most patients return to normal activities within 3–5 days and experience minimal complications.' => 'التعافي بعد زراعة سنّ واحدة بسيط ومتوقَّع. ويعود معظم المرضى إلى نشاطهم المعتاد خلال 3 إلى 5 أيام، بمضاعفات نادرة.',
		'VeaHealth locks in your price before travel. No hidden fees, no surprise charges. All costs include materials, labor, warranty, and VeaHealth coordination.' => 'تثبّت VeaHealth سعرك قبل السفر. لا رسوم خفية ولا مفاجآت. ويشمل السعر المواد والعمل والضمان وتنسيق VeaHealth.',
		'Your surgeon decides whether the protocol is appropriate for you at all. Some people are better served by rest and the standard aftercare, and are told so.' => 'يقرّر جرّاحك أصلاً هل يناسبك هذا البروتوكول أم لا. فبعض الناس يخدمهم الراحة والعناية المعتادة أكثر، ويُقال لهم ذلك.',
		'All-inclusive DHI package — consultation, Choi Implanter Pen technique, extraction, direct implantation, PRP treatment, medications, and 12-month follow-up.' => 'باقة DHI شاملة — الاستشارة، وتقنية قلم تشوي، والاقتطاف، والزراعة المباشرة، وجلسة بلازما PRP، والأدوية، ومتابعة 12 شهراً.',
		'First-year failure rate, primarily in patients with uncontrolled systemic conditions or heavy smoking — confirming that risk factor management is essential.' => 'معدّل الفشل في السنة الأولى، وأغلبه لدى مرضى بأمراض عامة غير مضبوطة أو مدخّنين بكثرة — وهو ما يؤكّد أن ضبط عوامل الخطر أمر أساسي.',
		'Full mouth implant recovery is gradual but predictable. Most patients resume normal activities within 7–10 days and full chewing function within 3–6 months.' => 'التعافي بعد زراعة الفك الكامل تدريجي لكنه متوقَّع. ويعود معظم المرضى إلى نشاطهم المعتاد خلال 7 إلى 10 أيام، وإلى المضغ الكامل خلال 3 إلى 6 أشهر.',
		'Though initially costlier than fillings, inlays and onlays eliminate the need for repeated replacements — making them more economical over a 15-year period.' => 'رغم أنها أغلى من الحشوة في البداية، تُغني حشوات الإنلاي والأونلاي عن التبديل المتكرّر — فتصير أوفر على مدى خمس عشرة سنة.',
		'From consultation to healed graft — the complete process typically requires one visit for surgery followed by 4–6 months of healing before implant placement.' => 'من الاستشارة إلى التئام الطُعم — يتطلّب المسار كلّه عادةً زيارة واحدة للجراحة، ثم 4 إلى 6 أشهر من الالتئام قبل وضع الغرسة.',
		'Smaller incision size compared to steel blades — resulting in faster healing, less scarring, and ability to place grafts closer together for natural density.' => 'شقوق أصغر مقارنةً بشفرات الفولاذ — فينتج التئام أسرع، وندوب أقل، وإمكانية وضع الطُعوم أقرب إلى بعضها لكثافة طبيعية.',
		'Under sedation, 4–6 implants are placed per arch. Failing teeth are extracted. Temporary acrylic teeth are attached same-day so you never go without a smile.' => 'تحت التركين، تُوضع 4 إلى 6 غرسات في كل فك، وتُخلع الأسنان الميؤوس منها. وتُثبَّت أسنان أكريلية مؤقتة في اليوم نفسه، فلا تبقى بلا ابتسامة في أي لحظة.',
		'Hair lost to years of tight braids, weaves or extensions often will not return on its own once the follicle has gone. Those temples and edges transplant well.' => 'الشعر الذي يُفقد بعد سنوات من الضفائر المشدودة أو الوصلات لا يعود غالباً من تلقاء نفسه بعد أن يزول الجُريب. وهذه الصدغان والحواف تستجيب للزراعة جيداً.',
		'Inlays and onlays require less tooth removal than crowns. They restore damaged areas while preserving healthy enamel — a more conservative long-term approach.' => 'تتطلّب حشوات الإنلاي والأونلاي إزالة قدر أقل من السن مقارنةً بالتلبيسة. فهي تُصلح المناطق المتضرّرة مع الحفاظ على المينا السليمة — وهو نهج أكثر تحفّظاً على المدى الطويل.',
		'Most beard cases are 1,000 to 3,000 grafts and are done in a day. Your own number comes from your donor area and the area being filled, not from a price list.' => 'معظم حالات اللحية تحتاج من 1,000 إلى 3,000 طُعم وتُنجَز في يوم واحد. أمّا عددك أنت فيأتي من منطقتك المانحة ومن المساحة المراد ملؤها، لا من قائمة أسعار.',
		'Porcelain and zirconia perfectly mimic tooth enamel — matching color, translucency, and sheen. They don’t stain or discolor over time like composite fillings.' => 'يحاكي الخزف والزيركون مينا الأسنان محاكاةً تامة — لوناً وشفافيةً ولمعاناً. ولا يتصبّغان ولا يبهتان مع الوقت كما تفعل الحشوات المركّبة.',
		'Bone graft recovery is gradual and predictable. Most patients return to normal activities within 7–10 days, with full graft integration achieved in 4–6 months.' => 'التعافي بعد ترقيع العظم تدريجي ومتوقَّع. ويعود معظم المرضى إلى نشاطهم المعتاد خلال 7 إلى 10 أيام، ويكتمل اندماج الطُعم خلال 4 إلى 6 أشهر.',
		'Implant survival rate over 10 years in healthy non-smoking patients — confirming single implants as the most predictable tooth replacement in modern dentistry.' => 'معدّل بقاء الغرسة على مدى 10 سنوات لدى مرضى أصحّاء غير مدخّنين — وهو ما يؤكّد أن زراعة السنّ الواحدة أكثر تعويضات الأسنان قابليةً للتنبّؤ في طبّ الأسنان الحديث.',
		'VeaHealth locks in your price before travel. All costs include implant placement, healing abutment, final crown, and lifetime warranty on the titanium fixture.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر وضع الغرسة، ودعامة الالتئام، والتلبيسة النهائية، وضمان مدى الحياة على جزء التيتانيوم.',
		'Permanence of transplanted hair — follicles from the DHT-resistant donor zone retain their genetic resistance after transplantation, growing naturally for life.' => 'دوام الشعر المزروع — إذ تحتفظ الجُريبات المأخوذة من المنطقة المانحة المقاومة لهرمون DHT بمقاومتها الوراثية بعد الزراعة، فتنمو نمواً طبيعياً مدى الحياة.',
		'Prosthetic complication rate over 10 years — 40% lower than All-on-4 due to reduced cantilever length and better biomechanical support from additional implants.' => 'معدّل المضاعفات التعويضية على مدى 10 سنوات — أقل بنسبة 40٪ من All-on-4 بفضل قصر الامتداد الحرّ والدعم الميكانيكي الأفضل من الغرسات الإضافية.',
		'Under local anaesthetic, either from a small shaved window concealed under longer hair or from a conventionally shaved donor area, depending on what was agreed.' => 'تحت تخدير موضعي، إمّا من نافذة صغيرة محلوقة مخفيّة تحت الشعر الطويل، وإمّا من منطقة مانحة محلوقة بالطريقة المعتادة، حسب ما اتُّفق عليه.',
		'You are shown how to wash, what to sleep on, and what the first fortnight looks like — then given the same in writing and a number to reach your coordinator on.' => 'يُشرح لك كيف تغسل، وعلى أي شيء تنام، وكيف تبدو الأسابيع الأولى — ثم يُسلَّم لك الشرح نفسه مكتوباً، مع رقم تتواصل به مع منسّقك.',
		'Total treatment compressed from 9–14 months to 5–7 months — saving 3–7 months for eligible patients, with one fewer surgical appointment and anaesthesia session.' => 'تُختصر مدّة العلاج الكاملة من 9–14 شهراً إلى 5–7 أشهر — أي توفير 3 إلى 7 أشهر للمرضى المؤهَّلين، مع موعد جراحي واحد أقل وجلسة تخدير أقل.',
		'VeaHealth locks in your price before travel. All costs include zygomatic implants, surgery, temporary teeth, final prosthesis, and lifetime warranty on fixtures.' => 'تثبّت VeaHealth سعرك قبل السفر. ويشمل السعر الغرسات الوجنية، والجراحة، والأسنان المؤقتة، والتعويض النهائي، وضمان مدى الحياة على الغرسات.',
		'You remain in Istanbul for 5–7 days for daily wound checks. Swelling peaks at 48 hours. Your surgeon monitors healing and removes sutures before you return home.' => 'تبقى في إسطنبول من 5 إلى 7 أيام لفحص الجرح يومياً. ويبلغ التورّم ذروته بعد 48 ساعة. ويتابع جرّاحك الالتئام وينزع الغرز قبل عودتك.',
		'Annual bone loss rate after tooth extraction without grafting — underscoring why immediate socket preservation is critical for maintaining future implant options.' => 'معدّل الفقد العظمي السنوي بعد الخلع دون ترقيع — وهو ما يوضّح لماذا يُعدّ الحفاظ الفوري على السِنخ أمراً حاسماً لإبقاء خيارات الزراعة مفتوحة لاحقاً.',
		'Annual technical complication rate (chipping, fracture) for monolithic zirconia crowns — significantly lower than porcelain-fused-to-metal crowns (3.8% annually).' => 'المعدّل السنوي للمضاعفات التقنية (تشظٍّ أو كسر) في تلبيسات الزيركون أُحادية الكتلة — أقل بوضوح من التلبيسات الخزفية المعدنية (3.8٪ سنوياً).',
		'Sinus lift in Istanbul costs £850–1,200 vs £2,800–4,500 in the UK. Same materials, same techniques, same success rates — coordinated start to finish by VeaHealth.' => 'يكلّف رفع الجيب في إسطنبول 850–1,200 £ مقابل 2,800–4,500 £ في بريطانيا. نفس المواد، ونفس التقنيات، ونفس نِسب النجاح — بتنسيق كامل من VeaHealth من البداية إلى النهاية.',
		'There is no linear scar. Each extraction leaves a round point under a millimetre across, which heals as a small pale dot and is not visible at normal hair length.' => 'لا توجد ندبة خطّية. فكل اقتطاف يترك نقطة دائرية أقل من ملّيمتر، تلتئم على شكل نقطة فاتحة صغيرة لا تُرى عند طول الشعر المعتاد.',
		'Traction alopecia often responds well, provided the tension has stopped and the follicles are not permanently scarred. Trichoscopy shows which of the two you have.' => 'غالباً ما تستجيب ثعلبة الشدّ استجابةً جيدة، شرط أن يكون الشدّ قد توقّف وألّا تكون الجُريبات قد تندّبت نهائياً. ويُظهر تنظير الشعر أيّ الحالتين لديك.',
		'Zirconia combines the strength of metal with the aesthetics of porcelain — offering a biocompatible, metal-free solution that blends seamlessly with natural teeth.' => 'يجمع الزيركون بين قوة المعدن وجمال الخزف — فيقدّم حلاًّ متوافقاً حيوياً وخالياً من المعادن ينسجم تماماً مع الأسنان الطبيعية.',
		'Zirconium crowns have minimal downtime. Most patients resume normal eating within 24 hours and experience zero complications when proper oral hygiene is maintained.' => 'لا تكاد تلبيسة الزيركون تفرض توقّفاً. فمعظم المرضى يعودون إلى الأكل المعتاد خلال 24 ساعة ولا تصيبهم أي مضاعفات ما دامت نظافة الفم سليمة.',
		'Implant success rate in grafted sites that have fully healed — matching or exceeding success rates in native bone when adequate healing time (4–6 months) is allowed.' => 'نسبة نجاح الغرسات في المواضع المرقَّعة بعد التئامها الكامل — مساوية لنسبة النجاح في العظم الأصلي أو أعلى منها، متى أُعطي الالتئام وقته الكافي (4 إلى 6 أشهر).',
		'Lifetime prevalence of peri-implantitis — the most common complication — underscoring why daily oral hygiene and regular professional maintenance are non-negotiable.' => 'نسبة الإصابة بالتهاب ما حول الغرسة على مدى العمر — وهو أكثر المضاعفات شيوعاً — وهذا يوضّح لماذا لا مجال للتهاون في النظافة اليومية والمتابعة الاحترافية المنتظمة.',
		'Sites are opened between the hairs already there — the constraint that defines female cases. Existing follicles must not be damaged in the process of adding to them.' => 'تُفتح المواضع بين الشعرات الموجودة أصلاً — وهذا هو القيد الذي يميّز حالات النساء. فلا يجوز الإضرار بالجُريبات القائمة أثناء إضافة غيرها إليها.',
		'Clinical studies show inlays and onlays last 10–15+ years on average — significantly longer than composite fillings, which typically need replacement every 5–7 years.' => 'تُظهر الدراسات السريرية أن حشوات الإنلاي والأونلاي تدوم 10 إلى 15 سنة فأكثر في المتوسط — أطول بكثير من الحشوات المركّبة التي تحتاج عادةً إلى تبديل كل 5 إلى 7 سنوات.',
		'Prosthetic complication rate (crown fracture, screw loosening) over 10 years — manageable issues that are easily repaired without compromising the underlying implants.' => 'معدّل المضاعفات التعويضية (كسر تلبيسة، ارتخاء برغي) على مدى 10 سنوات — وهي مشكلات يسهل إصلاحها دون المساس بالغرسات نفسها.',
		'The brow is drawn on and adjusted with you until you are happy with it in a mirror. It is photographed at that point, and that photograph is what the surgeon works to.' => 'يُرسم الحاجب ويُعدَّل معك حتى يرضيك في المرآة. ثم يُصوَّر عند تلك اللحظة، وتلك الصورة هي ما يعمل عليه الجرّاح.',
		'Most patients return to work within 3–5 days. Swelling peaks at 48–72 hours and resolves within a week. The graft itself heals over 4–6 months before implant placement.' => 'يعود معظم المرضى إلى العمل خلال 3 إلى 5 أيام. ويبلغ التورّم ذروته بين 48 و72 ساعة ويزول خلال أسبوع. أمّا الطُعم نفسه فيلتئم على مدى 4 إلى 6 أشهر قبل وضع الغرسة.',
		'The provisional crown in the fresh socket guides soft tissue healing into a natural gum profile, producing significantly better papilla preservation vs delayed protocol.' => 'توجّه التلبيسة المؤقتة الموضوعة في السِنخ الطازج التئام الأنسجة الرخوة نحو شكل لثوي طبيعي، وتحافظ على الحليمات اللثوية بصورة أفضل بكثير من البروتوكول المؤجَّل.',
		'Implants placed in grafted sinus bone achieve 95–98% survival rates at 10 years — statistically identical to implants in native bone, when proper healing time is allowed.' => 'تحقّق الغرسات الموضوعة في عظم الجيب المرقَّع معدّلات بقاء بين 95 و98٪ بعد 10 سنوات — وهي مطابقة إحصائياً للغرسات في العظم الأصلي، متى أُعطي الالتئام وقته الكافي.',
		'Reduction in total treatment time compared to conventional two-stage implant protocol — from 9–14 months to 5–7 months in eligible patients receiving immediate placement.' => 'انخفاض في المدّة الكلية للعلاج مقارنةً ببروتوكول الزراعة التقليدي ذي المرحلتين — من 9–14 شهراً إلى 5–7 أشهر لدى المرضى المؤهَّلين للزراعة الفورية.',
		'Survival rate of zirconia crowns at 10 years in multiple systematic reviews — matching or exceeding metal-ceramic crowns with superior aesthetics and zero metal exposure.' => 'معدّل بقاء تلبيسات الزيركون بعد 10 سنوات بحسب عدّة مراجعات منهجية — مساوٍ للتلبيسات الخزفية المعدنية أو أفضل منه، مع مظهر أجمل وبلا أي معدن مكشوف.',
		'Bone grafting rebuilds lost jawbone volume, creating the stable foundation needed for long-term implant success. Without adequate bone, implants cannot integrate properly.' => 'يعيد ترقيع العظم بناء ما فُقد من حجم عظم الفك، فيخلق الأساس المستقرّ الذي يحتاجه نجاح الغرسة على المدى الطويل. فبلا عظم كافٍ لا تندمج الغرسة كما ينبغي.',
		'Female results are typically assessed at twelve to eighteen months, slightly later than male cases, because density builds among existing hair rather than into bare scalp.' => 'تُقيَّم نتائج النساء عادةً بين اثني عشر وثمانية عشر شهراً، أي بعد حالات الرجال بقليل، لأن الكثافة تُبنى بين شعر موجود لا في فروة رأس عارية.',
		'Survival rate of E-max veneers at 10 years in multiple clinical studies — matching or exceeding traditional veneers despite requiring significantly less tooth preparation.' => 'معدّل بقاء قشور E-max بعد 10 سنوات في عدّة دراسات سريرية — مساوٍ للقشور التقليدية أو أفضل منه، رغم أنها تتطلّب تحضيراً أقل بكثير للسن.',
		'This is one of the most common reasons for the procedure. Years of plucking can stop follicles regrowing altogether, and grafting is the reliable way to rebuild the shape.' => 'هذا من أكثر أسباب إجراء العملية شيوعاً. فسنوات من النتف قد توقف نمو الجُريبات نهائياً، والزراعة هي الطريقة الموثوقة لإعادة بناء الشكل.',
		'Sites are opened at facial angles — close to flat, following the direction each part of the beard grows. Direction changes across the face and the incisions change with it.' => 'تُفتح المواضع بزوايا الوجه — شبه مسطَّحة، تتبع الاتّجاه الذي ينبت به كل جزء من اللحية. والاتّجاه يتغيّر عبر الوجه، وتتغيّر معه الشقوق.',
		'Graft incorporation success rate with modern techniques and materials — confirming that bone grafting is a predictable procedure when proper surgical protocols are followed.' => 'معدّل نجاح اندماج الطُعم بالتقنيات والمواد الحديثة — وهو ما يؤكّد أن ترقيع العظم إجراء متوقَّع النتائج متى اتُّبعت البروتوكولات الجراحية الصحيحة.',
		'Modern zirconia replicates the light-transmitting properties of natural enamel. Custom shading and contouring create a lifelike appearance indistinguishable from real teeth.' => 'يحاكي الزيركون الحديث الطريقة التي ينفذ بها الضوء عبر مينا الأسنان الطبيعية. ومع ضبط اللون والنحت حسب المقاس، تُصبح النتيجة لا تُميَّز عن الأسنان الحقيقية.',
		'A large share of female cases are not thinning at all but a naturally high hairline that someone wants brought forward. That is a straightforward, very predictable procedure.' => 'جزء كبير من حالات النساء ليس تخفّفاً في الشعر أصلاً، بل خط شعر أمامي مرتفع بطبيعته تريد صاحبته تقديمه. وهذا إجراء بسيط ونتائجه متوقَّعة إلى حدّ بعيد.',
		'The common case is not an absent beard but an uneven one — a thin patch on one cheek, a gap under the corner of the mouth. Those are the cases that fill in most convincingly.' => 'الحالة الشائعة ليست غياب اللحية بل عدم انتظامها — بقعة خفيفة في خدّ، وفراغ تحت زاوية الفم. وهذه هي الحالات التي تُملأ بأكثر صورة مقنعة.',
		'Annual failure rate for E-max veneers — primarily due to improper bonding or extreme parafunctional habits (grinding). Fracture rate is remarkably low given ultra-thin design.' => 'المعدّل السنوي لفشل قشور E-max — وسببه غالباً لصق غير سليم أو عادات لا وظيفية شديدة (صرير الأسنان). ونسبة الكسر منخفضة بشكل لافت بالنظر إلى رقّتها البالغة.',
		'Combining extraction and implant into one appointment eliminates the second surgical procedure — reducing total anaesthesia exposure, healing periods, and time away from home.' => 'جَمْع الخلع والزراعة في موعد واحد يلغي العملية الجراحية الثانية — فيقلّ التعرّض الكلي للتخدير، وتقلّ فترات الالتئام، ويقلّ الوقت بعيداً عن البيت.',
		'Female loss usually thins the whole crown rather than clearing a defined area. There is existing hair among which grafts must be placed without damaging what is already there.' => 'التساقط عند النساء يُخفّف عادةً التاج كلّه بدل أن يُفرِغ منطقة محدّدة. فيبقى شعر موجود يجب وضع الطُعوم بينه دون الإضرار بما هو قائم.',
		'Inlays and onlays are precision-crafted in a lab, offering superior fit, strength, and aesthetics compared to direct composite fillings — ideal for moderate to large cavities.' => 'تُصنَع حشوات الإنلاي والأونلاي في المختبر بدقّة، فتتفوّق على الحشوات المركّبة المباشرة في الانطباق والقوة والمظهر — وهي مثالية للتجاويف المتوسّطة والكبيرة.',
		'Where the brow was lost to burns, tattooing or scarring, blood supply is poorer and a proportion of grafts will not take. A second session is sometimes planned from the start.' => 'حيث فُقد الحاجب بسبب حرق أو وشم أو ندبة، تكون التروية الدموية أضعف ولن ينجح جزء من الطُعوم. ولذلك تُخطَّط جلسة ثانية أحياناً منذ البداية.',
		'Documented lifespan in well-maintained zygomatic cases since the technique’s introduction in 1998. The zygomatic bone’s exceptional density provides stable long-term anchorage.' => 'عمر موثَّق في الحالات الوجنية المعتنى بها جيداً منذ ظهور التقنية سنة 1998. فكثافة عظم الوجنة الاستثنائية تمنح تثبيتاً مستقرّاً على المدى الطويل.',
		'Incidence of sinusitis following zygomatic placement — typically mild and self-limiting, managed with antibiotics and decongestants. Serious sinus complications are rare (<2%).' => 'نسبة حدوث التهاب الجيوب بعد وضع الغرسات الوجنية — وهو غالباً خفيف ويزول من تلقاء نفسه، ويُعالَج بالمضادات الحيوية ومزيلات الاحتقان. أمّا مضاعفات الجيوب الخطيرة فنادرة (أقل من 2٪).',
		'Unlike chair-side fillings, inlays and onlays are fabricated in a dental lab using digital impressions for a precision fit that eliminates gaps and minimizes future decay risk.' => 'بخلاف الحشوة التي تُوضع على كرسي العيادة، تُصنَع حشوات الإنلاي والأونلاي في مختبر أسنان انطلاقاً من طبعة رقمية، فيكون الانطباق دقيقاً بلا فجوات، ويقلّ خطر عودة التسوّس.',
		'Acne scarring, surgical scars and burns leave permanent gaps. Grafts placed into scar tissue take less reliably than into healthy skin, which is said up front rather than after.' => 'تترك ندوب حبّ الشباب والندوب الجراحية والحروق فراغات دائمة. والطُعوم الموضوعة في نسيج ندبي تنجح بنسبة أقل ممّا في الجلد السليم، وهذا يُقال مسبقاً لا لاحقاً.',
		'Fewer appointments and stages typically reduce total cost vs two-stage protocol — especially significant through VeaHealth’s Istanbul pricing at 60–70% below UK/US market rates.' => 'قلّة المواعيد والمراحل تخفّض التكلفة الإجمالية عادةً مقارنةً بالبروتوكول ذي المرحلتين — ويزداد الفرق وضوحاً مع أسعار VeaHealth في إسطنبول، وهي أقل بنسبة 60–70٪ من أسعار السوق في بريطانيا وأمريكا.',
		'Custom night guards protect against teeth grinding (bruxism) and TMJ disorders — preventing thousands in future dental damage while improving sleep quality and reducing jaw pain.' => 'يحمي الواقي الليلي المفصَّل من صرير الأسنان ومن اضطرابات مفصل الفك — فيوفّر آلافاً من تكاليف الأضرار السنّية المقبلة، ويحسّن جودة النوم، ويقلّل آلام الفك.',
		'Grafts can be taken from a small hidden window under longer hair, so nothing visible is cut. It is slower and takes fewer grafts in a session, and it is not right for every case.' => 'يمكن اقتطاف الطُعوم من نافذة صغيرة مخفيّة تحت الشعر الطويل، فلا يُقصّ شيء ظاهر. لكنه أبطأ ويعطي طُعوماً أقل في الجلسة، وهو لا يناسب كل الحالات.',
		'Implant survival rate for zygomatic implants at 10+ years across multiple systematic reviews — confirming they’re a predictable, mainstream solution for severe maxillary atrophy.' => 'معدّل بقاء الغرسات الوجنية بعد أكثر من 10 سنوات بحسب عدّة مراجعات منهجية — وهو ما يؤكّد أنها حلّ متوقَّع النتائج ومعتمَد في حالات الضمور الشديد للفك العلوي.',
		'Porcelain and zirconia inlays/onlays are stronger than composite fillings, resisting fracture and wear. They can withstand heavy chewing forces for 10–15+ years with proper care.' => 'حشوات الإنلاي والأونلاي من الخزف والزيركون أقوى من الحشوات المركّبة، فتقاوم الكسر والتآكل. وتتحمّل قوى مضغ عالية لمدّة 10 إلى 15 سنة فأكثر مع عناية سليمة.',
		'Soft tissue and gingival contour outcomes. Immediate provisionalization achieves significantly better papilla preservation and natural gum emergence profile vs delayed placement.' => 'النتائج على الأنسجة الرخوة وشكل اللثة. يحافظ التعويض المؤقت الفوري على الحليمات اللثوية بصورة أفضل بكثير ويعطي شكل خروج لثوياً أكثر طبيعية مقارنةً بالزراعة المؤجَّلة.',
		'Beard hair exits the skin at roughly 15 to 20 degrees — nearly flat. Grafts set at scalp angles stand up, catch the light differently, and read as transplanted from across a room.' => 'يخرج شعر اللحية من الجلد بزاوية 15 إلى 20 درجة تقريباً — أي شبه مسطَّح. أمّا الطُعوم الموضوعة بزوايا فروة الرأس فتقف منتصبة، وتعكس الضوء بشكل مختلف، وتُقرأ على أنها مزروعة من الطرف الآخر للغرفة.',
		'Implant survival rate for All-on-4/6 at 10 years across multiple systematic reviews — matching or exceeding individual implant protocols with significantly faster treatment times.' => 'معدّل بقاء الغرسات في All-on-4/6 بعد 10 سنوات، بحسب عدّة مراجعات منهجية — مساوٍ لبروتوكولات الغرسات المفردة أو أفضل منه، وبمدّة علاج أقصر بكثير.',
		'The acrylic gum base is custom-shaded to match your natural tissue color and can be sculpted to recreate realistic gum architecture — far more natural-looking than pink porcelain.' => 'تُلوَّن قاعدة اللثة الأكريلية حسب المقاس لتطابق لون أنسجتك، ويمكن نحتها لإعادة تشكيل بنية لثوية واقعية — وهي أقرب إلى الطبيعة بكثير من الخزف الوردي.',
		'VeaHealth uses xenograft (bovine), allograft (human donor), or synthetic bone materials — all proven for maxillary sinus augmentation with >95% success rates in long-term studies.' => 'تستعمل VeaHealth طُعوماً من مصدر بقري، أو من متبرّع بشري، أو بدائل عظم صناعية — وكلّها مُثبَتة في تعزيز الجيب الفكّي بنِسب نجاح تفوق 95٪ في الدراسات طويلة الأمد.',
		'Hybrid prostheses cost 20–30% less than full zirconia while delivering comparable aesthetics. For patients on a budget who still want superior appearance, this is the ideal choice.' => 'تكلّف التركيبة الهجينة أقل بنسبة 20 إلى 30٪ من الزيركون الكامل مع مظهر مقارب. وهي الخيار الأمثل لمن يريد مظهراً راقياً بميزانية أقل.',
		'Your inlay or onlay is digitally designed and milled from a solid block of porcelain or zirconia in VeaHealth’s partner lab. Color is precisely matched to your natural tooth shade.' => 'تُصمَّم حشوتك رقمياً ثم تُخرَّط من كتلة صلبة من الخزف أو الزيركون في مختبر VeaHealth الشريك. ويُضبط اللون بدقّة على لون سنّك الطبيعي.',
		'Full arch implants replace all missing or failing teeth with a permanent, fixed solution. No more dentures, no adhesives, no slipping — just confident eating, speaking, and smiling.' => 'تعوّض زراعة الفك الكامل كل الأسنان المفقودة أو الميؤوس منها بحلّ ثابت ودائم. لا طقم بعد اليوم، ولا لواصق، ولا انزلاق — بل أكل وكلام وابتسامة بثقة.',
		'If a zirconia tooth chips (rare), the acrylic base allows for easier chair-side repairs compared to monolithic zirconia. Simple maintenance extends the lifespan of your restoration.' => 'إذا تشظّت سنّ زيركون — وهو نادر — تسمح القاعدة الأكريلية بإصلاح أسهل على كرسي العيادة مقارنةً بالزيركون أُحادي الكتلة. وصيانة بسيطة تطيل عمر تعويضك.',
		'Local anaesthetic to the donor area — the injections are the uncomfortable part and they take a couple of minutes. Extraction then proceeds follicle by follicle with the hand punch.' => 'تخدير موضعي للمنطقة المانحة — والحقن هو الجزء المزعج ولا يستغرق سوى دقيقتين. ثم يمضي الاقتطاف جُريباً بعد جُريب بالأداة اليدوية.',
		'Several hundred sites are opened individually, each at the angle and direction that part of the brow grows. This is the slowest part of the day and the part that decides the result.' => 'تُفتح عدّة مئات من المواضع واحداً واحداً، كلٌّ بالزاوية والاتّجاه اللذين ينبت بهما ذلك الجزء من الحاجب. وهذه أبطأ لحظات اليوم، وهي التي تقرّر النتيجة.',
		'Documented implant lifespan in well-maintained All-on-4 cases — confirming that with proper hygiene and regular professional care, full arch implants are truly a lifetime investment.' => 'عمر موثَّق للغرسات في حالات All-on-4 المعتنى بها جيداً — وهو ما يؤكّد أن زراعة الفك الكامل، مع نظافة سليمة ومتابعة احترافية منتظمة، استثمار يدوم العمر كلّه.',
		'Biocompatibility rating — zirconia shows no cytotoxic effects, no allergic potential, and excellent tissue integration. Gingival health is maintained or improved in long-term studies.' => 'تقييم التوافق الحيوي — لا يُظهر الزيركون أي سمّية خلوية، ولا قدرة على إثارة الحساسية، ويندمج مع الأنسجة اندماجاً ممتازاً. وتبقى صحة اللثة كما هي أو تتحسّن في الدراسات طويلة الأمد.',
		'The donor is scalp hair and it behaves like scalp hair — it will need trimming every few weeks, for good. Anyone who does not tell you that beforehand has not told you the main thing.' => 'الشعر المانح شعر رأس ويتصرّف كشعر رأس — فسيحتاج إلى تقصير كل بضعة أسابيع، إلى الأبد. ومن لا يخبرك بذلك مسبقاً لم يخبرك بأهم شيء.',
		'The hairline is drawn on your forehead and you look at it in a mirror before anyone agrees to it. Donor density is measured, not estimated, and that measurement sets the graft number.' => 'يُرسم خط الشعر على جبهتك وتنظر إليه في المرآة قبل أن يوافق عليه أحد. وتُقاس كثافة المنطقة المانحة قياساً لا تقديراً، وهذا القياس هو ما يحدّد عدد الطُعوم.',
		'You return to Istanbul for 3–5 days. The temporary bridge is removed and digital impressions are taken. Your final zirconia prosthesis is fabricated, tested, and permanently attached.' => 'تعود إلى إسطنبول لمدّة 3 إلى 5 أيام. يُنزع الجسر المؤقت وتُؤخذ طبعات رقمية. ثم يُصنَع تعويض الزيركون النهائي ويُجرَّب ويُثبَّت بشكل دائم.',
		'Your dentist evaluates your teeth for signs of grinding damage — worn enamel, micro-cracks, and jaw alignment. Digital photos document baseline condition. Treatment plan is confirmed.' => 'يبحث طبيبك عن علامات ضرر الصرير — مينا متآكلة، وشقوق دقيقة، ووضع الفكّين. وتُوثَّق الحالة الأولية بصور رقمية. ثم تُعتمَد خطة العلاج.',
		'Documented implant lifespan in well-maintained All-on-6 cases — confirming that with proper hygiene, biannual cleanings, and regular monitoring, the implants can truly last a lifetime.' => 'عمر موثَّق للغرسات في حالات All-on-6 المعتنى بها جيداً — وهو ما يؤكّد أن الغرسات، مع نظافة سليمة وتنظيف مرتين سنوياً ومتابعة منتظمة، قد تدوم العمر كلّه فعلاً.',
		'When primary stability is confirmed, a provisional crown is placed the same day — no gap in the smile during osseointegration, maintaining aesthetics and confidence throughout healing.' => 'عند تأكّد الثبات الابتدائي، تُركَّب تلبيسة مؤقتة في اليوم نفسه — فلا فراغ في الابتسامة أثناء الاندماج العظمي، ويبقى المظهر والثقة على حالهما طوال فترة الالتئام.',
		'You return to try on your custom guard. Your dentist checks fit, comfort, and bite alignment. Minor adjustments are made if needed. You receive care instructions and a protective case.' => 'تعود لتجربة واقيك المفصَّل. ويتحقّق طبيبك من الانطباق والراحة وضبط الإطباق، ويُجري تعديلات طفيفة عند الحاجة. وتتسلّم تعليمات العناية وعلبة واقية.',
		'All-on-6 uses two additional implants compared to All-on-4, providing enhanced load distribution, better long-term stability, and improved outcomes for patients with moderate bone loss.' => 'يستعمل All-on-6 غرستين إضافيتين مقارنةً بـAll-on-4، فيوزّع القوى توزيعاً أفضل، ويعطي ثباتاً أعلى على المدى الطويل، ونتائج أفضل لدى المرضى ذوي الفقد العظمي المتوسّط.',
		'Despite superior strength, hybrid zirconium is lighter than full monolithic zirconia — reducing stress on implants and providing greater comfort, especially for upper arch restorations.' => 'رغم قوّتها الفائقة، تبقى التركيبة الهجينة من الزيركون أخفّ من الزيركون أُحادي الكتلة الكامل — فيقلّ الإجهاد على الغرسات وتزيد الراحة، خصوصاً في الفك العلوي.',
		'Implant survival at 5–10 years for immediate placement in selected cases — no statistically significant difference from conventional delayed protocol outcomes in published meta-analysis.' => 'بقاء الغرسة بعد 5–10 سنوات في الزراعة الفورية للحالات المنتقاة — دون فرق ذي دلالة إحصائية عن نتائج البروتوكول المؤجَّل التقليدي، بحسب التحليلات التجميعية المنشورة.',
		'Individual zirconia teeth are the strongest ceramic material in dentistry — fracture-resistant, completely stain-proof, and capable of lasting 15–20+ years without discoloration or wear.' => 'الزيركون أقوى مادة خزفية في طب الأسنان — مقاوم للكسر، لا يتصبّغ إطلاقاً، وقادر على أن يدوم 15 إلى 20 سنة فأكثر دون تغيّر لون أو تآكل.',
		'Manual punches are typically taken slightly wider, leaving more protective tissue around the follicle — which matters for how well it survives the hours between extraction and placement.' => 'تُؤخذ الأدوات اليدوية عادةً بقطر أوسع قليلاً، فيبقى حول الجُريب نسيج واقٍ أكثر — وهذا يهمّ في مدى بقائه حياً خلال الساعات الفاصلة بين الاقتطاف والزرع.',
		'The recipient sites are opened at the angle and direction your existing hair grows. This step decides whether the result looks grown or planted, and it is the part that cannot be rushed.' => 'تُفتح مواضع الزرع بالزاوية والاتّجاه اللذين ينمو بهما شعرك الحالي. وهذه الخطوة هي التي تقرّر هل تبدو النتيجة نابتة أم مغروسة، وهي الجزء الذي لا يحتمل الاستعجال.',
		'Bite force is restored to 95–100% of natural teeth. You can eat steak, apples, nuts, and corn on the cob without restriction. No dietary limitations like with bridges or partial dentures.' => 'تعود قوة العضّ إلى 95–100٪ من قوة الأسنان الطبيعية. يمكنك أن تأكل اللحم والتفاح والمكسّرات والذرة دون قيد. ولا قيود غذائية كما هي الحال مع الجسور أو الأطقم الجزئية.',
		'The scalp is fully anaesthetised locally, so the procedure itself is not painful. The anaesthetic injections sting briefly. Discomfort afterwards is usually managed with simple analgesia.' => 'تُخدَّر فروة الرأس موضعياً بالكامل، فالعملية نفسها غير مؤلمة. أمّا حقن التخدير فتلسع لحظات قصيرة. والانزعاج بعدها يُضبط عادةً بمسكّن بسيط.',
		'Grafts are placed into the prepared sites. Single-hair units go to the front edge; three- and four-hair units go behind them where density reads rather than where it would look artificial.' => 'تُوضع الطُعوم في المواضع المهيَّأة. فالوحدات ذات الشعرة الواحدة تذهب إلى الحافة الأمامية، أمّا ذات الثلاث والأربع شعرات فتُوضع خلفها حيث تُقرأ الكثافة دون أن تبدو مصطنعة.',
		'VeaHealth coordinates comprehensive diagnostics including 3D CBCT scan, X-rays, and digital treatment planning. Your team designs the implant configuration and hybrid prosthesis virtually.' => 'تنسّق VeaHealth تشخيصاً كاملاً يشمل أشعة CBCT ثلاثية الأبعاد، وأشعة عادية، وتخطيطاً رقمياً للعلاج. ويصمّم فريقك ترتيب الغرسات والتركيبة الهجينة افتراضياً.',
		'The beard line is drawn on your face and you approve it in a mirror. Where the moustache meets the lip and where the cheek line falls are decisions made now, with you, not improvised later.' => 'يُرسم خط اللحية على وجهك وتوافق عليه في المرآة. وموضع التقاء الشارب بالشفة، وموضع خط الخدّ، قراران يُتَّخذان الآن معك، لا يُرتجلان لاحقاً.',
		'Zirconia is biocompatible, non-porous, and resists chipping better than porcelain. Combined with a titanium framework, hybrid zirconium prostheses deliver exceptional long-term reliability.' => 'الزيركون متوافق حيوياً، غير مسامي، وأقلّ عرضةً للتشظّي من الخزف. ومع هيكل تيتانيوم، تعطي التركيبة الهجينة من الزيركون موثوقية استثنائية على المدى الطويل.',
		'Once CBCT confirms the graft has consolidated into mature bone, you return to Istanbul for dental implant placement. The implants engage both the graft and native bone for optimal stability.' => 'بعد أن تؤكّد أشعة CBCT أن الطُعم صار عظماً ناضجاً، تعود إلى إسطنبول لوضع الغرسات. وتتثبّت الغرسات في الطُعم وفي العظم الأصلي معاً لتحقيق أفضل ثبات.',
		'The application is non-surgical and painless, but suitability is a clinical decision. Your surgeon reviews it against your medical history, and it is not offered where it is contraindicated.' => 'التطبيق غير جراحي وبلا ألم، لكن مدى ملاءمته قرار سريري. فيراجعه جرّاحك في ضوء تاريخك الطبي، ولا يُقدَّم حيث يكون ممنوعاً.',
		'You remain in Istanbul for 5–7 days for daily check-ups. Swelling peaks at 48–72 hours. Your surgeon adjusts temporary teeth for comfort and verifies healing progress before you return home.' => 'تبقى في إسطنبول من 5 إلى 7 أيام لفحوصات يومية. ويبلغ التورّم ذروته بين 48 و72 ساعة. ويضبط جرّاحك الأسنان المؤقتة لراحتك ويتحقّق من تقدّم الالتئام قبل عودتك.',
		'You return to Istanbul for 4–5 days. Digital impressions are taken. Your custom hybrid prosthesis (porcelain teeth + acrylic gum + titanium framework) is fabricated and permanently attached.' => 'تعود إلى إسطنبول لمدّة 4 إلى 5 أيام، وتُؤخذ طبعات رقمية. ثم تُصنَع تركيبتك الهجينة حسب المقاس — أسنان خزفية، ولثة أكريلية، وهيكل تيتانيوم — وتُثبَّت بشكل دائم.',
		'Your crown is milled from a single block of premium zirconia using CAD/CAM technology. A master ceramist applies custom layering, staining, and glazing to match your natural teeth perfectly.' => 'تُخرَّط تلبيستك من كتلة واحدة من الزيركون عالي الجودة بتقنية CAD/CAM. ثم يضيف فنّي خزف ماهر الطبقات والصباغة والتزجيج حسب المقاس لتطابق أسنانك تماماً.',
		'Donor density is measured across the safe zone, including the areas most likely to be affected by diffuse loss. The hairline is designed to your face and, if you have one, to old photographs.' => 'تُقاس كثافة المنطقة المانحة على امتداد المنطقة الآمنة، بما فيها المواضع الأكثر عرضةً للتساقط المنتشر. ويُصمَّم خط الشعر الأمامي على ملامح وجهك، وعلى صورك القديمة إن كانت لديك.',
		'Replacing 10–14 teeth individually would cost £15,000–25,000 in the UK. Full arch restoration with 4–6 implants costs £4,500–6,500 in Istanbul — a 70% saving with identical clinical outcomes.' => 'تعويض 10 إلى 14 سنّاً واحدةً واحدة يكلّف 15,000–25,000 £ في بريطانيا. أمّا تعويض الفك الكامل بـ4 إلى 6 غرسات فيكلّف 4,500–6,500 £ في إسطنبول — أي توفير 70٪ بنتيجة سريرية مطابقة.',
		'Under IV sedation or general anesthesia, 4–6 implants are placed per arch. Any failing teeth are extracted. Temporary acrylic teeth are attached the same day — you walk out with a full smile.' => 'تحت تركين وريدي أو تخدير عام، تُوضع 4 إلى 6 غرسات في كل فك، وتُخلع الأسنان الميؤوس منها. ثم تُثبَّت أسنان أكريلية مؤقتة في اليوم نفسه — فتخرج بابتسامة كاملة.',
		'Unlike dentures, full arch implants are screwed directly into your jawbone. They never come out, never slip, and require no special cleaning routines. Brush and floss just like natural teeth.' => 'بخلاف الطقم المتحرّك، يُثبَّت تعويض الفك الكامل بالبراغي مباشرةً في عظم فكّك. فلا يُنزع ولا ينزلق، ولا يحتاج إلى بروتوكولات تنظيف خاصة. تفريش وخيط أسنان، تماماً كالأسنان الطبيعية.',
		'Walk out with temporary teeth the same day as surgery. You can eat soft foods immediately and resume normal chewing within 2–3 weeks. Final zirconia bridge placed after 3–6 months of healing.' => 'تخرج بأسنان مؤقتة في يوم الجراحة نفسه. ويمكنك تناول الأطعمة الطرية فوراً، والعودة إلى المضغ المعتاد خلال أسبوعين إلى ثلاثة. أمّا جسر الزيركون النهائي فيُركَّب بعد 3 إلى 6 أشهر من الالتئام.',
		'The lab uses your digital impressions to mill a precision night guard from medical-grade acrylic. CAD/CAM technology ensures perfect fit. The guard is polished, sanitized, and quality-checked.' => 'يستعمل المختبر طبعاتك الرقمية لخرط واقٍ ليلي دقيق من أكريل طبي. وتضمن تقنية CAD/CAM انطباقاً مثالياً. ثم يُلمَّع الواقي ويُعقَّم وتُراجَع جودته.',
		'Using an intraoral scanner, your dentist takes precise 3D impressions of your upper and lower teeth. No messy putty — just a quick digital scan. Bite registration ensures proper jaw alignment.' => 'بماسح داخل الفم، يأخذ طبيبك طبعات ثلاثية الأبعاد دقيقة لأسنانك العلوية والسفلية. بلا عجينة مزعجة — مجرّد مسح رقمي سريع. ويضمن تسجيل الإطباق وضعاً صحيحاً للفكّين.',
		'VeaHealth’s partner labs use CAD/CAM milling for micron-level accuracy. Intraoral scanners eliminate messy impressions. Same-day adjustments ensure perfect occlusion before you leave Istanbul.' => 'تعمل مختبرات VeaHealth الشريكة بتقنية CAD/CAM بدقّة تصل إلى الميكرون. وتُغني الماسحات داخل الفم عن الطبعات التقليدية المزعجة. وتُجرى التعديلات في اليوم نفسه لضمان إطباق مثالي قبل مغادرتك إسطنبول.',
		'Decay is removed and the cavity is prepared with precise margins. A digital 3D scan captures the exact shape and size of the prepared cavity. A temporary filling protects the tooth for one week.' => 'يُزال التسوّس ويُحضَّر التجويف بحدود دقيقة. ويلتقط مسح رقمي ثلاثي الأبعاد شكل التجويف المحضَّر وحجمه بالضبط. ثم تحمي حشوة مؤقتة السن لمدّة أسبوع.',
		'Dental implants stimulate bone just like natural tooth roots, preventing the bone loss and facial collapse that occurs with dentures. Your facial structure remains youthful and stable long-term.' => 'تحفّز الغرسات العظم تماماً كما تفعل جذور الأسنان الطبيعية، فتمنع فقدان العظم وانهيار ملامح الوجه الذي يسبّبه الطقم المتحرّك. وتبقى ملامح وجهك شابّة وثابتة على المدى الطويل.',
		'Patient satisfaction with aesthetics of E-max veneers in long-term follow-up studies. The superior translucency and natural light reflection create results indistinguishable from natural enamel.' => 'رضا المرضى عن جماليات قشور E-max في دراسات المتابعة طويلة الأمد. فشفافيتها المتفوّقة وانعكاسها الطبيعي للضوء يعطيان نتيجة لا تُميَّز عن المينا الطبيعية.',
		'Tightly curled follicles curve under the skin. That curve is where motorised punches most often cut the graft in half, and it is the case for manual extraction most often made in the literature.' => 'الجُريبات شديدة التجعّد تنحني تحت الجلد. وعند ذلك الانحناء تقطع المثاقب الآلية الطُعم نصفين في أغلب الأحيان، وهي الحجّة الأكثر ورودًا في الأدبيات لصالح الاقتطاف اليدوي.',
		'You remain in Istanbul for 5–7 days for daily check-ups. Swelling peaks at 48 hours. Your surgeon adjusts the temporary teeth for comfort and verifies healing is on track before you return home.' => 'تبقى في إسطنبول من 5 إلى 7 أيام لفحوصات يومية. ويبلغ التورّم ذروته بعد 48 ساعة. ويضبط جرّاحك الأسنان المؤقتة لراحتك ويتأكّد من أن الالتئام يسير كما ينبغي قبل عودتك.',
		'Because iron deficiency, thyroid disorders and hormonal changes are common, treatable causes of female hair loss. Operating without addressing them means the underlying loss continues afterwards.' => 'لأن نقص الحديد واضطرابات الغدة الدرقية والتغيّرات الهرمونية أسباب شائعة وقابلة للعلاج لتساقط الشعر عند النساء. والعملية دون معالجتها تعني أن التساقط الأساسي سيستمرّ بعدها.',
		'Zirconia is completely metal-free — no risk of galvanic reactions, metal allergies, or gum discoloration. Tissue-friendly surface promotes healthy gingival attachment and reduces plaque retention.' => 'الزيركون خالٍ تماماً من المعادن — فلا خطر تفاعلات كهركيميائية، ولا حساسية معدنية، ولا تلوّن للثة. وسطحه اللطيف على الأنسجة يشجّع التصاق اللثة السليم ويقلّل تراكم البلاك.',
		'After 4–6 months, a new CBCT scan confirms graft incorporation. Once healed, you’re ready for implant placement — the original reason for grafting. Your implant can now succeed in the rebuilt bone.' => 'بعد 4 إلى 6 أشهر تؤكّد أشعة CBCT جديدة اندماج الطُعم. وبعد الالتئام تصبح جاهزاً لوضع الغرسة — وهو الغرض الأصلي من الترقيع. وبإمكان الغرسة أن تنجح الآن في العظم المعاد بناؤه.',
		'After tooth loss, the maxillary sinus floor often descends, leaving only 4–6mm of bone — too little for a standard 10mm implant. Sinus lift adds 8–12mm of height, enabling proper implant placement.' => 'بعد فقدان السن، يهبط قاع الجيب الفكّي غالباً فلا يبقى سوى 4 إلى 6 مم من العظم — وهو أقل من أن يكفي غرسة عادية بطول 10 مم. ويضيف رفع الجيب من 8 إلى 12 مم من الارتفاع، فيصبح وضع الغرسة ممكناً.',
		'Modern zirconia allows light translucency that mimics natural enamel. Multi-layered shading and surface staining create lifelike color gradients. No dark metal margin visible at the gumline — ever.' => 'يسمح الزيركون الحديث بنفاذ الضوء تماماً كما تفعل مينا الأسنان الطبيعية. ويعطي التلوين متعدّد الطبقات والصباغة السطحية تدرّجات لونية شبيهة بالحقيقية. ولا يظهر أي حدّ معدني داكن عند خط اللثة — أبداً.',
		'The graft material slowly integrates with your natural bone over 4–6 months. You maintain the site with gentle oral hygiene. VeaHealth monitors your healing remotely via photos and video check-ins.' => 'تندمج مادة الترقيع ببطء مع عظمك الطبيعي خلال 4 إلى 6 أشهر. وتعتني بالموضع بنظافة فم لطيفة. وتتابع VeaHealth التئامك عن بُعد بالصور ومكالمات الفيديو.',
		'A motor turns at a set rate whatever it meets. A hand punch tells the surgeon what the tissue is doing — where the follicle splays, where it curves — and the punch follows it rather than through it.' => 'المِثقب الآلي يدور بسرعة ثابتة مهما لاقى. أمّا الأداة اليدوية فتخبر الجرّاح بما يفعله النسيج — أين يتفرّع الجُريب وأين ينحني — فيتبعه بدل أن يخترقه.',
		'VeaHealth coordinates comprehensive diagnostics including 3D CBCT scan, X-rays, and digital treatment planning. Your team designs the implant configuration and hybrid zirconium prosthesis virtually.' => 'تنسّق VeaHealth تشخيصاً كاملاً يشمل أشعة CBCT ثلاثية الأبعاد، وأشعة عادية، وتخطيطاً رقمياً للعلاج. ويصمّم فريقك ترتيب الغرسات والتركيبة الهجينة من الزيركون افتراضياً.',
		'CBCT cone beam imaging maps sinus anatomy in 3D before surgery, allowing the surgeon to plan the optimal window position, avoid Schneiderian membrane perforation, and achieve ideal bone graft volume.' => 'ترسم أشعة CBCT تشريح الجيب ثلاثي الأبعاد قبل الجراحة، فيستطيع الجرّاح تحديد أفضل موضع للنافذة، وتفادي ثقب غشاء شنايدر، وبلوغ حجم الترقيع المثالي.',
		'Sapphire’s smooth, sharp edge creates cleaner incisions with less tissue damage. This preserves graft viability during implantation, achieving survival rates 10–15% higher than traditional steel FUE.' => 'حدّ الياقوت الأملس الحادّ يعطي شقوقاً أنظف وأقلّ إضراراً بالنسيج. وهذا يحفظ حيوية الطُعم أثناء الزراعة، ويحقّق معدّلات بقاء أعلى بنسبة 10 إلى 15٪ من تقنية FUE الفولاذية التقليدية.',
		'You return to Istanbul for 4–5 days. Digital impressions are taken. Your custom hybrid zirconium prosthesis (zirconia teeth + acrylic gum + titanium framework) is fabricated and permanently attached.' => 'تعود إلى إسطنبول لمدّة 4 إلى 5 أيام، وتُؤخذ طبعات رقمية. ثم تُصنَع تركيبتك الهجينة حسب المقاس — أسنان زيركون، ولثة أكريلية، وهيكل تيتانيوم — وتُثبَّت بشكل دائم.',
		'Implants fuse with your jawbone over 3–6 months. You wear temporary teeth during this period and follow a gradual diet progression. VeaHealth monitors your healing remotely via photos and video calls.' => 'تلتحم الغرسات بعظم فكّك خلال 3 إلى 6 أشهر. وترتدي الأسنان المؤقتة في هذه الفترة وتعود إلى الأكل المعتاد تدريجياً. وتتابع VeaHealth التئامك عن بُعد بالصور ومكالمات الفيديو.',
		'Implants fuse with your jawbone over 4–6 months. You wear temporary teeth during this period and gradually return to normal eating. VeaHealth monitors your healing remotely via photos and video calls.' => 'تلتحم الغرسات بعظم فكّك خلال 4 إلى 6 أشهر. وترتدي الأسنان المؤقتة في هذه الفترة وتعود تدريجياً إلى الأكل المعتاد. وتتابع VeaHealth التئامك عن بُعد بالصور ومكالمات الفيديو.',
		'Often, yes, though survival in scar tissue is lower than in healthy skin because blood supply is poorer. Your surgeon will tell you what to expect for your specific scar and may plan a second session.' => 'غالباً نعم، وإن كان بقاء الطُعوم في النسيج الندبي أقل منه في الجلد السليم لضعف التروية الدموية. وسيقول لك جرّاحك ما الذي تتوقّعه بالنسبة لندبتك أنت، وقد يخطّط لجلسة ثانية.',
		'The acrylic gum base is custom-shaded to match your natural tissue color and can be contoured to recreate realistic gum architecture. Pink acrylic looks more natural than pink porcelain in most cases.' => 'تُلوَّن قاعدة اللثة الأكريلية حسب المقاس لتطابق لون أنسجتك، ويمكن نحتها لإعادة تشكيل لثة واقعية. وفي معظم الحالات يبدو الأكريل الوردي أقرب إلى الطبيعة من الخزف الوردي.',
		'Usually a few hundred per brow, depending on how much native hair remains and the shape being rebuilt. The count is quoted after your photographs are reviewed — it is far lower than a scalp procedure.' => 'عادةً بضع مئات لكل حاجب، حسب ما تبقّى من الشعر الأصلي والشكل المراد بناؤه. ويُحدَّد العدد بعد مراجعة صورك — وهو أقل بكثير ممّا تحتاجه زراعة فروة الرأس.',
		'Grinding generates up to 250 pounds of force — enough to crack enamel, wear down teeth, and break fillings and crowns. A night guard absorbs this force, preventing thousands in future restorative work.' => 'يولّد صرير الأسنان قوةً تصل إلى 110 كيلوغرامات — تكفي لتشقيق المينا، وتآكل الأسنان، وكسر الحشوات والتلبيسات. ويمتصّ الواقي الليلي هذه القوة، فيوفّر آلافاً من تكاليف الترميم لاحقاً.',
		'Immediate placement interrupts the rapid alveolar resorption that begins within weeks of extraction — protecting the bone volume and gum contour that define long-term aesthetic and functional outcomes.' => 'توقف الزراعة الفورية الامتصاص السريع للعظم السنخي الذي يبدأ خلال أسابيع من الخلع — فتحمي حجم العظم وشكل اللثة، وهما ما يحدّد النتيجة الجمالية والوظيفية على المدى الطويل.',
		'The temporary crown is removed and the zirconium crown is test-fitted. Your dentist checks fit, bite, and aesthetics. Once perfect, the crown is permanently cemented using biocompatible resin adhesive.' => 'تُنزع التلبيسة المؤقتة وتُجرَّب تلبيسة الزيركون. ويتحقّق طبيبك من الانطباق والإطباق والمظهر. وبعد أن يصير كل شيء مضبوطاً، تُثبَّت التلبيسة نهائياً بلاصق راتنجي متوافق حيوياً.',
		'Your dentist performs a comprehensive exam with digital X-rays and intraoral photos. Existing restoration (if any) is evaluated. Treatment plan is confirmed with shade selection under natural lighting.' => 'يُجري طبيبك فحصاً كاملاً مع أشعة رقمية وصور داخل الفم. ويُقيَّم التعويض الموجود إن وُجد. ثم تُعتمَد خطة العلاج ويُختار اللون في ضوء طبيعي.',
		'15–20 year average lifespan with proper hygiene. Studies show 95%+ survival at 10 years. Maintenance is minimal — standard brushing, flossing, and biannual cleanings. No special care protocols required.' => 'عمر متوسّط من 15 إلى 20 سنة مع نظافة سليمة. وتُظهر الدراسات بقاءً يفوق 95٪ بعد 10 سنوات. والعناية بسيطة: تفريش وخيط أسنان وتنظيف احترافي مرتين في السنة. ولا حاجة إلى بروتوكولات خاصة.',
		'Brush and floss normally — no special cleaning protocols, no removal, no adhesives. Biannual professional cleanings and annual X-rays are the only maintenance required. Simpler than caring for a bridge.' => 'تفريش وخيط أسنان كالمعتاد — لا بروتوكولات تنظيف خاصة، ولا نزع، ولا لواصق. ويكفي تنظيف احترافي مرتين في السنة وأشعة سنوية. وهي أسهل عنايةً من الجسر السنّي.',
		'Sapphire’s precision allows 50–60 grafts per cm² placement — matching natural hair density. Traditional FUE achieves only 35–40 grafts/cm². This creates a fuller, more authentic appearance from day one.' => 'تتيح دقّة الياقوت وضع 50 إلى 60 طُعماً في السنتيمتر المربّع — أي كثافة الشعر الطبيعي. أمّا تقنية FUE التقليدية فلا تتجاوز 35 إلى 40 طُعماً. وهذا يعطي مظهراً أغزر وأصدق منذ اليوم الأول.',
		'After tooth loss, jawbone resorbs at 25% per year. Bone grafts halt this process and rebuild lost volume, creating the height and width needed for stable implant placement and long-term osseointegration.' => 'بعد فقدان السن يُمتصّ عظم الفك بمعدّل 25٪ في السنة. ويوقف الترقيع هذه العملية ويعيد بناء ما فُقد، فيوفّر الارتفاع والعرض اللازمين لوضع غرسة ثابتة ولاندماج عظمي يدوم.',
		'Final prostheses are crafted from layered zirconia — mimicking natural tooth translucency, color, and texture. Gum-colored acrylic recreates natural tissue. Results are indistinguishable from real teeth.' => 'تُصنع التعويضات النهائية من زيركون متعدّد الطبقات يحاكي شفافية السن الطبيعية ولونها وملمسها. ويعيد الأكريل بلون اللثة تشكيل النسيج اللثوي. والنتيجة لا تُميَّز عن الأسنان الحقيقية.',
		'Hybrid prostheses are significantly lighter than full zirconia bridges, reducing stress on implants and providing greater comfort — especially for upper arch restorations where weight is more noticeable.' => 'التركيبات الهجينة أخفّ بوضوح من جسور الزيركون الكاملة، فيقلّ الإجهاد على الغرسات وتزيد الراحة — خصوصاً في الفك العلوي حيث يكون الوزن أوضح إحساساً.',
		'Individual porcelain teeth are crafted to match your natural shade, translucency, and contours. Unlike acrylic, porcelain doesn’t stain or discolor over time, maintaining a pristine appearance for years.' => 'تُصنَع كل سنّ خزفية لتطابق لون أسنانك وشفافيتها وشكلها. وبخلاف الأكريل، لا يتصبّغ الخزف ولا يبهت مع الوقت، فيبقى المظهر نقياً سنوات طويلة.',
		'Transplanted hair sheds after 2–4 weeks (normal). New growth begins at month 3. Full density achieved by month 12. VeaHealth monitors your progress remotely via monthly photo updates and video check-ins.' => 'يتساقط الشعر المزروع بعد أسبوعين إلى أربعة، وهذا أمر طبيعي. ويبدأ النمو الجديد في الشهر الثالث، وتكتمل الكثافة في الشهر الثاني عشر. وتتابع VeaHealth تقدّمك عن بُعد بصور شهرية ومكالمات فيديو.',
		'Grinding disrupts REM sleep for both you and your partner. A properly fitted guard reduces grinding frequency and intensity, leading to deeper sleep, less morning fatigue, and improved cognitive function.' => 'يعكّر صرير الأسنان نوم حركة العين السريعة، لك ولمن ينام إلى جانبك. ويقلّل الواقي المضبوط تواتر الصرير وشدّته، فيتحسّن عمق النوم، ويقلّ تعب الصباح، وتتحسّن القدرة على التركيز.',
		'The temporary filling is removed. Your custom inlay/onlay is tried in to verify fit and bite. Once confirmed, it’s permanently bonded using dental adhesive. Final polishing ensures a smooth, natural feel.' => 'تُنزع الحشوة المؤقتة. وتُجرَّب حشوتك للتأكّد من الانطباق والإطباق. وبعد التأكّد، تُلصَق بشكل دائم بلاصق سنّي. ويضمن التلميع النهائي سطحاً ناعماً بإحساس طبيعي.',
		'Yes. Grafts taken from the permanent zone at the back of the scalp keep the characteristics of their origin, so they continue to grow and will need trimming — sometimes faster than the rest of your beard.' => 'نعم. فالطُعوم المأخوذة من المنطقة الدائمة في مؤخّرة الرأس تحتفظ بخصائص أصلها، فتستمرّ في النمو وتحتاج إلى تقصير — أحياناً أسرع من بقية لحيتك.',
		'Before you travel, VeaHealth coordinates a comprehensive 3D CBCT scan to measure bone volume precisely. Your surgeon calculates the exact amount of graft material needed and confirms the surgical approach.' => 'قبل سفرك، تنسّق VeaHealth أشعة CBCT ثلاثية الأبعاد كاملة لقياس حجم العظم بدقّة. ويحسب جرّاحك الكمية المطلوبة بالضبط من مادة الترقيع ويحدّد أسلوب الجراحة.',
		'Sapphire FUE uses precision-cut sapphire blades instead of steel, creating smaller micro-channels for follicle implantation. This results in faster healing, higher graft survival, and more natural density.' => 'تستبدل تقنية سفير الفولاذَ بشفرات ياقوت مصقولة بدقّة، تفتح قنوات أصغر لاستقبال الطُعوم. ومن هنا التئام أسرع، وبقاء أعلى للطُعوم، وكثافة أقرب إلى الطبيعة.',
		'Sapphire blades create channels 30% smaller than steel blades — reducing trauma, minimizing scarring, and allowing tighter graft placement for maximum natural density. Channels match follicle size exactly.' => 'تفتح شفرات الياقوت قنوات أصغر بنسبة 30٪ من شفرات الفولاذ — فيقلّ الرضّ، وتقلّ الندوب، ويمكن وضع الطُعوم أقرب إلى بعضها لبلوغ أقصى كثافة طبيعية. وتُطابق القناة حجم الطُعم تماماً.',
		'Smaller incisions mean less tissue disruption and faster recovery. Most patients see complete healing within 7–10 days compared to 14–21 days with steel FUE. Scabbing resolves faster with minimal scarring.' => 'الشقوق الأصغر تعني اضطراباً أقل في النسيج وتعافياً أسرع. ويلتئم معظم المرضى تماماً خلال 7 إلى 10 أيام، مقابل 14 إلى 21 يوماً في تقنية FUE الفولاذية. وتتساقط القشور أسرع وتبقى الندوب ضئيلة.',
		'This page describes standard technique for the procedure. Your own plan — graft numbers, session length and what is realistic for your donor area — is written after a surgeon has reviewed your photographs.' => 'تصف هذه الصفحة التقنية المعتادة للإجراء. أمّا خطتك أنت — عدد الطُعوم، ومدّة الجلسة، وما هو واقعي بالنسبة لمنطقتك المانحة — فتُكتب بعد أن يراجع جرّاح صورك.',
		'VeaHealth coordinates a comprehensive CBCT cone beam scan to measure bone height, sinus anatomy, and membrane thickness. Your surgeon designs the optimal lateral window position and graft volume virtually.' => 'تنسّق VeaHealth أشعة CBCT كاملة لقياس ارتفاع العظم وتشريح الجيب وسُمك الغشاء. ويحدّد جرّاحك افتراضياً الموضع الأمثل للنافذة الجانبية وحجم الترقيع.',
		'By preventing clenching, night guards reduce stress on the temporomandibular joint (TMJ). Patients report significant reduction in jaw pain, headaches, and facial tension within 2–3 weeks of consistent use.' => 'بمنع إطباق الفكّين بقوة، يقلّل الواقي الليلي الإجهاد على المفصل الصدغي الفكّي. ويصف المرضى انخفاضاً واضحاً في آلام الفك والصداع وتوتّر الوجه خلال أسبوعين إلى ثلاثة من الاستعمال المنتظم.',
		'Zygomatic implant recovery requires closer monitoring than conventional implants due to sinus proximity. Most patients resume normal activities within 10–14 days and achieve full function within 5–6 months.' => 'يتطلّب التعافي بعد الغرسات الوجنية مراقبة ألصق منها في الغرسات التقليدية بسبب قرب الجيوب الأنفية. ويعود معظم المرضى إلى نشاطهم المعتاد خلال 10 إلى 14 يوماً، وإلى الوظيفة الكاملة خلال 5 إلى 6 أشهر.',
		'Bone loss causes facial collapse and premature aging. Grafting preserves jawbone architecture, maintaining proper facial proportions and preventing the sunken appearance associated with long-term tooth loss.' => 'يؤدّي فقدان العظم إلى انهيار ملامح الوجه وشيخوخة مبكّرة. ويحافظ الترقيع على بنية عظم الفك، فتبقى نِسب الوجه سليمة ويُتفادى المظهر الغائر الذي يرافق فقدان الأسنان لسنوات.',
		'DHI (Direct Hair Implantation) uses the Choi Implanter Pen to extract and implant follicles in one motion without pre-opening channels. This results in maximum control, minimal bleeding, and faster recovery.' => 'تستعمل تقنية DHI (الزراعة المباشرة للشعر) قلم تشوي لاقتطاف الطُعوم وزرعها في حركة واحدة دون فتح القنوات مسبقاً. ومن هنا يأتي التحكّم الأقصى، والنزف الضئيل، والتعافي الأسرع.',
		'No. Both visits are performed under local anesthesia. You’ll feel pressure during preparation but no pain. Some sensitivity is normal for a few days after bonding as the tooth adjusts to the new restoration.' => 'لا. تُجرى الزيارتان تحت تخدير موضعي. فتشعر بالضغط أثناء التحضير دون ألم. وبعض الحساسية لأيام قليلة بعد اللصق أمر طبيعي، ريثما تتأقلم السن مع التعويض الجديد.',
		'Your surgeon performs in-person scalp examination, confirms graft count, and draws your new hairline with a surgical marker. You approve the design before proceeding. Blood tests and pre-op photos are taken.' => 'يفحص جرّاحك فروة رأسك مباشرةً، ويؤكّد عدد الطُعوم، ويرسم خط شعرك الجديد بقلم جراحي. وتوافق أنت على التصميم قبل المضيّ قدماً. ثم تُجرى تحاليل الدم وتُلتقط صور ما قبل العملية.',
		'Medical-grade acrylic resists bacteria, staining, and odors. With proper cleaning (daily rinse, weekly soak), your guard remains hygienic and functional for 2–3 years — far longer than drugstore alternatives.' => 'الأكريل الطبي يقاوم البكتيريا والتصبّغ والروائح. ومع تنظيف سليم (شطف يومي ونقع أسبوعي) يبقى واقيك نظيفاً وعاملاً من سنتين إلى ثلاث — أطول بكثير من بدائل الصيدلية.',
		'Unlike over-the-counter guards, custom guards are fabricated from precise digital impressions of your teeth. This ensures perfect retention, comfort, and effectiveness — no gagging, slipping, or jaw soreness.' => 'بخلاف الوقايات الجاهزة التي تُباع في الصيدليات، يُصنَع الواقي المفصَّل انطلاقاً من طبعات رقمية دقيقة لأسنانك. وهذا يضمن تثبيتاً وراحةً وفعالية تامة — بلا غثيان ولا انزلاق ولا وجع في الفك.',
		'A £120 night guard prevents £3,000–8,000 in future dental work (crowns, root canals, implants). Insurance actuaries calculate that every £1 spent on prevention saves £25 in restorative treatment over 10 years.' => 'واقٍ ليلي بـ120 £ يمنع أعمالاً سنّية مقبلة بقيمة 3,000–8,000 £ (تلبيسات وسحب أعصاب وغرسات). ويحسب خبراء التأمين أن كل جنيه يُنفَق على الوقاية يوفّر 25 جنيهاً في العلاج الترميمي على مدى عشر سنوات.',
		'All-on-4/6 implants have 95%+ survival rates at 10 years. With proper hygiene and regular check-ups, your implants can last a lifetime. The prosthetic bridge may need replacement after 15–20 years due to wear.' => 'تحقّق غرسات All-on-4/6 معدّلات بقاء تفوق 95٪ بعد 10 سنوات. ومع نظافة سليمة وفحوصات منتظمة قد تدوم غرساتك مدى الحياة. أمّا الجسر التعويضي فقد يحتاج إلى تبديل بعد 15–20 سنة بسبب التآكل.',
		'Hybrid prostheses combine the natural aesthetics of porcelain teeth with the durability and repairability of an acrylic gum base — offering an ideal middle ground between full zirconia and traditional acrylic.' => 'تجمع التركيبات الهجينة بين المظهر الطبيعي لأسنان الخزف، وبين متانة قاعدة اللثة الأكريلية وسهولة إصلاحها — فتقدّم حلاًّ وسطاً مثالياً بين الزيركون الكامل والأكريل التقليدي.',
		'Yes. You can fly the day after surgery (day 2). Most patients stay 2–3 nights in Istanbul total — day 1 for procedure, day 2 for post-op care and first wash, then fly home. VeaHealth coordinates all logistics.' => 'نعم. يمكنك السفر جواً في اليوم التالي للعملية (اليوم الثاني). ويقيم معظم المرضى ليلتين إلى ثلاث في إسطنبول إجمالاً — اليوم الأول للعملية، والثاني للعناية بعدها وأول غسل، ثم العودة. وتتولّى VeaHealth كل الترتيبات.',
		'Under general anesthesia, 2–4 zygomatic implants are placed per arch using 3D-guided navigation. The extra-long implants traverse the sinus and anchor in the cheekbone. Temporary teeth are attached immediately.' => 'تحت تخدير عام، تُوضع 2 إلى 4 غرسات وجنية في كل فك بملاحة موجَّهة ثلاثية الأبعاد. وتعبر هذه الغرسات الفائقة الطول الجيب الفكّي وتُثبَّت في عظم الوجنة. ثم تُركَّب الأسنان المؤقتة فوراً.',
		'Before you travel, VeaHealth coordinates a full diagnostic workup — panoramic X-rays, 3D CBCT scan, and digital treatment planning. Your surgeon designs implant placement virtually to ensure optimal positioning.' => 'قبل سفرك، تنسّق VeaHealth تشخيصاً كاملاً — أشعة بانورامية، وأشعة CBCT ثلاثية الأبعاد، وتخطيطاً رقمياً للعلاج. ويصمّم جرّاحك مواضع الغرسات افتراضياً لضمان الوضع الأمثل.',
		'You return to Istanbul for 3–5 days. The temporary bridge is removed and digital impressions are taken. Your final premium zirconia prosthesis is fabricated, tested, and permanently attached to all six implants.' => 'تعود إلى إسطنبول لمدّة 3 إلى 5 أيام. يُنزع الجسر المؤقت وتُؤخذ طبعات رقمية. ثم يُصنَع تعويض الزيركون النهائي من الفئة الأولى ويُجرَّب ويُثبَّت بشكل دائم على الغرسات الست.',
		'Zygomatic implants are designed for patients with <5mm of residual bone — cases where conventional implants and even sinus lifts are impossible. They\'re the last-resort solution that works when nothing else can.' => 'صُمّمت الغرسات الوجنية لمن بقي لديهم أقل من 5 مم من العظم — وهي حالات تستحيل فيها الغرسات التقليدية بل وحتى رفع الجيب الفكّي. إنها الحلّ الأخير الذي ينجح حين لا ينجح غيره.',
		'Insufficient bone is the leading cause of implant failure. Grafting ensures adequate bone density and volume around the implant fixture, dramatically improving success rates from 60% to 95%+ in compromised sites.' => 'قلّة العظم هي السبب الأول لفشل الغرسات. ويضمن الترقيع كثافةً وحجماً كافيين حول الغرسة، فيرفع نِسب النجاح في المواضع الضعيفة من 60٪ إلى أكثر من 95٪.',
		'Under IV sedation or general anesthesia, six implants are placed per arch using 3D-guided surgery. Any failing teeth are extracted. Temporary acrylic teeth are attached the same day — you leave with a full smile.' => 'تحت تركين وريدي أو تخدير عام، تُوضع ست غرسات في كل فك بجراحة موجَّهة ثلاثية الأبعاد، وتُخلع الأسنان الميؤوس منها. ثم تُثبَّت أسنان أكريلية مؤقتة في اليوم نفسه — فتخرج بابتسامة كاملة.',
		'Follicles transplanted from the permanent “donor zone” (back of head) are genetically resistant to DHT. They retain this resistance after transplantation, growing naturally for life with zero maintenance required.' => 'الطُعوم المأخوذة من المنطقة المانحة الدائمة في مؤخّرة الرأس مقاومة وراثياً لهرمون DHT. وتحتفظ بهذه المقاومة بعد الزراعة، فتنمو نمواً طبيعياً مدى الحياة دون أي صيانة.',
		'Grafting unlocks treatment options for patients previously deemed “not candidates” for implants. Sinus lifts, ridge augmentation, and socket preservation turn hopeless cases into successful full arch restorations.' => 'يفتح الترقيع خيارات علاجية أمام مرضى اعتُبروا سابقاً «غير مؤهَّلين» للزراعة. فرفع الجيب الفكّي، وتوسيع الحافة السنخية، والحفاظ على السِنخ تحوّل حالات ميؤوساً منها إلى تعويضات فك كامل ناجحة.',
		'If a tooth chips or breaks, the acrylic base allows for simple chair-side repairs without removing the entire prosthesis. This is a major advantage over monolithic zirconia, which requires lab work for any damage.' => 'إذا تشظّت سنّ أو انكسرت، تسمح القاعدة الأكريلية بإصلاح بسيط على كرسي العيادة دون نزع التركيبة كلّها. وهذه ميزة واضحة على الزيركون أُحادي الكتلة الذي يتطلّب عملاً في المختبر لأي ضرر.',
		'Male donor hair is usually resistant to the hormone driving the loss. In diffuse female loss the back of the head can be thinning as well — if it is, transplanting from it moves the problem rather than solving it.' => 'شعر المنطقة المانحة عند الرجل مقاوم عادةً للهرمون المسبّب للتساقط. أمّا في التساقط المنتشر عند النساء فقد تكون مؤخّرة الرأس خافّة هي الأخرى — وإن كانت كذلك، فالزراعة منها تنقل المشكلة بدل أن تحلّها.',
		'The graft consolidates over 4–9 months. Xenograft particles act as a scaffold for your natural bone to grow into. VeaHealth monitors healing remotely with CBCT scans at 3 and 6 months to confirm graft integration.' => 'يتماسك الطُعم على مدى 4 إلى 9 أشهر. وتعمل حُبيبات الطُعم الحيواني كسقالة ينمو فيها عظمك الطبيعي. وتتابع VeaHealth الالتئام عن بُعد بأشعة CBCT في الشهر الثالث والسادس للتأكّد من الاندماج.',
		'When bone height is insufficient in the posterior upper jaw, a sinus lift creates the vertical space needed for stable implant placement. It’s the gold standard for restoring back teeth in patients with bone loss.' => 'حين لا يكفي ارتفاع العظم في المنطقة الخلفية من الفك العلوي، يوفّر رفع الجيب المساحة العمودية اللازمة لوضع غرسة ثابتة. وهو المعيار الذهبي لتعويض الأسنان الخلفية لدى من فقدوا عظماً.',
		'You return to Istanbul for 3–5 days. The temporary bridge is removed and digital impressions are taken. Your final premium zirconia prosthesis is fabricated, tested for fit and occlusion, and permanently attached.' => 'تعود إلى إسطنبول لمدّة 3 إلى 5 أيام. يُنزع الجسر المؤقت وتُؤخذ طبعات رقمية. ثم يُصنَع تعويض الزيركون النهائي من الفئة الأولى ويُختبر انطباقه وإطباقه ويُثبَّت بشكل دائم.',
		'Zirconia’s flexural strength (900–1200 MPa) exceeds porcelain-fused-to-metal crowns, making it ideal for posterior teeth subjected to high bite forces. Fracture resistance is clinically proven in 10+ year studies.' => 'تتجاوز مقاومة الزيركون للانحناء (900–1200 ميغاباسكال) مقاومة التلبيسات الخزفية المدعّمة بالمعدن، وهو ما يجعله مثالياً للأسنان الخلفية التي تتحمّل قوى عضّ عالية. ومقاومته للكسر مُثبَتة سريرياً في دراسات تتجاوز 10 سنوات.',
		'Before you travel, VeaHealth coordinates a comprehensive evaluation — panoramic X-rays, CBCT scan, and treatment planning. Your surgeon confirms implant placement feasibility and identifies any bone grafting needs.' => 'قبل سفرك، تنسّق VeaHealth تقييماً كاملاً — أشعة بانورامية، وأشعة CBCT، وتخطيطاً للعلاج. ويؤكّد جرّاحك إمكانية وضع الغرسة ويحدّد أي حاجة إلى ترقيع عظمي.',
		'Two extra implants provide significantly more retention and stability than All-on-4. Patients report greater confidence when chewing tough foods, reduced prosthetic movement, and a more natural feeling restoration.' => 'تمنح الغرستان الإضافيتان تثبيتاً وثباتاً أعلى بكثير من All-on-4. ويصف المرضى ثقة أكبر عند مضغ الأطعمة الصلبة، وحركة أقل للتعويض، وإحساساً أقرب إلى الطبيعي.',
		'With proper care, hybrid prostheses last 10–15 years before needing replacement. The acrylic may require professional polishing every 2–3 years to maintain optimal shine, but this is a quick, inexpensive procedure.' => 'مع عناية سليمة، تدوم التركيبة الهجينة 10 إلى 15 سنة قبل أن تحتاج إلى تبديل. وقد يحتاج الأكريل تلميعاً احترافياً كل 2 إلى 3 سنوات للحفاظ على لمعانه، وهو إجراء سريع وقليل التكلفة.',
		'Zirconia crowns require less tooth reduction than metal-ceramic crowns — preserving more of your natural structure. Conservative margins mean healthier long-term outcomes and easier future revisions if ever needed.' => 'تتطلّب تلبيسة الزيركون برد قدر أقل من السن مقارنةً بالتلبيسة الخزفية المعدنية — فيبقى من بنيتك الطبيعية أكثر. والحدود المتحفّظة تعني نتائج أفضل على المدى الطويل، وتسهّل أي تعديل لاحق إن لزم.',
		'The tooth is prepared under local anesthesia — removing decay (if present) and shaping the surface to create space for the crown. A temporary crown is placed immediately to protect the tooth and maintain aesthetics.' => 'يُحضَّر السن تحت تخدير موضعي: يُزال التسوّس إن وُجد، ويُعاد تشكيل السطح لإفساح المجال للتلبيسة. ثم تُركَّب تلبيسة مؤقتة فوراً لحماية السن والحفاظ على المظهر.',
		'You return to Istanbul for 2–3 days. The healing cap is removed, digital impressions are taken, and your final zirconia crown is fabricated. Once shade and bite are perfect, it’s permanently attached to the implant.' => 'تعود إلى إسطنبول لمدّة 2–3 أيام. تُنزع قبعة الالتئام، وتُؤخذ طبعات رقمية، وتُصنَع تلبيسة الزيركون النهائية. وبعد ضبط اللون والإطباق، تُثبَّت على الغرسة بشكل دائم.',
		'Autogenous (your own bone), xenograft (bovine), allograft (human donor), or alloplastic (synthetic) — VeaHealth surgeons select the optimal material based on your specific defect size, location, and healing capacity.' => 'من عظمك أنت، أو من مصدر بقري، أو من متبرّع بشري، أو مادة صناعية — ويختار جرّاحو VeaHealth المادة الأنسب حسب حجم العيب وموضعه وقدرتك على الالتئام.',
		'Before you travel, VeaHealth coordinates comprehensive diagnostics — 3D CBCT scan, panoramic X-rays, and digital treatment planning. Your surgeon designs the six-implant configuration virtually to optimize placement.' => 'قبل سفرك، تنسّق VeaHealth تشخيصاً كاملاً — أشعة CBCT ثلاثية الأبعاد، وأشعة بانورامية، وتخطيطاً رقمياً للعلاج. ويصمّم جرّاحك ترتيب الغرسات الست افتراضياً لضبط مواضعها على الوجه الأمثل.',
		'Scalp hair is often slightly finer than beard hair, so new growth can differ in texture at first. It thickens over the first year. Direction and angle matter more than texture for whether the result reads as natural.' => 'شعر الرأس غالباً أرقّ قليلاً من شعر اللحية، فقد يختلف ملمس النمو الجديد في البداية. ويزداد سماكةً خلال السنة الأولى. أمّا في أن تبدو النتيجة طبيعية فالاتّجاه والزاوية أهمّ من الملمس.',
		'Under local anesthesia, the titanium implant is placed into your jawbone. If the tooth is still present, it’s extracted first. A healing abutment or temporary crown is placed immediately to protect the surgical site.' => 'تحت تخدير موضعي تُوضع غرسة التيتانيوم في عظم فكّك. وإذا كانت السنّ ما زالت موجودة، تُخلع أولاً. ثم تُركَّب دعامة التئام أو تلبيسة مؤقتة فوراً لحماية موضع الجراحة.',
		'Six implants allow for more flexible positioning to work around anatomical limitations like sinuses or nerves. Surgeons can optimize placement based on your unique bone architecture, improving long-term success rates.' => 'تتيح ست غرسات مرونة أكبر في المواضع لتفادي القيود التشريحية كالجيوب الأنفية أو الأعصاب. فيستطيع الجرّاح ضبط المواضع حسب بنية عظمك أنت، وهو ما يرفع نِسب النجاح على المدى الطويل.',
		'The implant fuses with your jawbone over 3–6 months. You return home during this phase and maintain the site with normal brushing and flossing. VeaHealth monitors your healing remotely with photos and video check-ins.' => 'تلتحم الغرسة بعظم فكّك خلال 3 إلى 6 أشهر. وتعود إلى بيتك في هذه المرحلة وتعتني بالموضع بالتفريش والخيط المعتادين. وتتابع VeaHealth التئامك عن بُعد بالصور ومكالمات الفيديو.',
		'Your veneers are milled from a single block of E-max lithium disilicate ceramic using CAD/CAM technology. A master ceramist applies custom layering, characterization, and glazing to match your natural teeth perfectly.' => 'تُخرَّط قشورك من كتلة واحدة من خزف E-max بتقنية CAD/CAM. ثم يضيف فنّي خزف ماهر الطبقات والتلوين والتزجيج حسب المقاس لتطابق أسنانك تماماً.',
		'Before you travel, VeaHealth coordinates a comprehensive scalp analysis via photos and video consultation. Your surgeon assesses donor area density, calculates available grafts, and designs your new hairline digitally.' => 'قبل سفرك، تنسّق VeaHealth تحليلاً كاملاً لفروة رأسك بالصور واستشارة بالفيديو. ويقيّم جرّاحك كثافة المنطقة المانحة، ويحسب عدد الطُعوم المتاحة، ويرسم خط شعرك الأمامي الجديد رقمياً.',
		'Implants fuse with zygomatic bone over 4–6 months. You wear temporary teeth during this period and gradually resume normal eating. VeaHealth monitors your healing remotely via photos, video calls, and symptom tracking.' => 'تلتحم الغرسات بعظم الوجنة خلال 4 إلى 6 أشهر. وترتدي الأسنان المؤقتة في هذه الفترة وتعود تدريجياً إلى الأكل المعتاد. وتتابع VeaHealth التئامك عن بُعد بالصور ومكالمات الفيديو ورصد الأعراض.',
		'Osseointegrated implants stimulate the jawbone through mechanical load transfer, halting the bone resorption that naturally follows tooth loss. This maintains facial structure and long-term prosthetic fit over decades.' => 'تحفّز الغرسات المندمجة عظمياً عظم الفك عبر نقل الأحمال الميكانيكية، فتوقف امتصاص العظم الذي يعقب فقدان الأسنان بطبيعته. وهذا يحافظ على بنية الوجه وعلى انطباق التعويض عقوداً طويلة.',
		'Under local anesthesia or IV sedation, the graft material is placed at the defect site. A collagen membrane is used to protect the graft. PRF (platelet-rich fibrin) from your own blood is applied to accelerate healing.' => 'تحت تخدير موضعي أو تركين وريدي، تُوضع مادة الترقيع في موضع العيب، ويُغطّى الطُعم بغشاء كولاجيني يحميه. ويُوضع فوقه PRF — فيبرين غني بالصفائح من دمك أنت — لتسريع الالتئام.',
		'Under local anesthesia, follicles are extracted one by one from the donor area using micro-punch tools. Sapphire blades create recipient channels. Grafts are implanted immediately. The entire procedure takes 6–8 hours.' => 'تحت تخدير موضعي، تُقتطف الطُعوم واحداً واحداً من المنطقة المانحة بأدوات اقتطاف دقيقة. وتفتح شفرات الياقوت القنوات في المنطقة المستقبِلة. وتُزرع الطُعوم فوراً. وتستغرق العملية كلّها 6 إلى 8 ساعات.',
		'Unlike dental bridges, implants require no grinding down of neighboring healthy teeth. Your natural teeth remain untouched and structurally intact — preventing future complications and preserving long-term oral health.' => 'بخلاف الجسور السنّية، لا تتطلّب الغرسة برد الأسنان السليمة المجاورة. فتبقى أسنانك الطبيعية كما هي، سليمة في بنيتها — وهذا يمنع مضاعفات لاحقة ويحافظ على صحة الفم على المدى الطويل.',
		'Clinical studies show 97%+ implant survival at 10 years for All-on-6 — slightly higher than All-on-4. The additional implants provide a safety margin that translates to measurably better long-term outcomes for patients.' => 'تُظهر الدراسات السريرية بقاءً للغرسات يفوق 97٪ بعد 10 سنوات في All-on-6 — أعلى قليلاً من All-on-4. فالغرسات الإضافية تمنح هامش أمان يُترجَم إلى نتائج أفضل قابلة للقياس على المدى الطويل.',
		'Hybrid zirconia prostheses combine the exceptional strength and stain-resistance of zirconia teeth with the natural appearance and comfort of an acrylic gum base — offering superior performance over traditional acrylic.' => 'تجمع التركيبات الهجينة من الزيركون بين القوة الاستثنائية لأسنان الزيركون ومقاومتها للتصبّغ، وبين المظهر الطبيعي والراحة في قاعدة اللثة الأكريلية — بأداء يفوق الأكريل التقليدي.',
		'It depends entirely on the area being covered and the density you want. Filling thin corners takes far fewer grafts than building a full beard from sparse growth. The number is quoted after your photographs are reviewed.' => 'يتوقّف ذلك كلّياً على المساحة المراد تغطيتها وعلى الكثافة التي تريدها. فملء زوايا خفيفة يحتاج طُعوماً أقل بكثير من بناء لحية كاملة انطلاقاً من نبات متفرّق. ويُحدَّد العدد بعد مراجعة صورك.',
		'No. Sapphire FUE creates micro-channels (0.6–0.8mm) that heal completely within 7–10 days, leaving no visible scarring. The donor area can be worn short (even buzzed) with no detection. Unlike FUT, there is no linear scar.' => 'لا. فتقنية سفير تفتح قنوات دقيقة (0.6–0.8 مم) تلتئم تماماً خلال 7 إلى 10 أيام ولا تترك ندوباً ظاهرة. ويمكنك أن تحلق المنطقة المانحة قصيرة جداً دون أن يُلاحَظ شيء. وبخلاف تقنية FUT، لا توجد ندبة خطّية.',
		'Custom zirconia crowns are shade-matched to your natural teeth and emerge naturally from the gumline — no visible metal margins, no artificial-looking bulk. Indistinguishable from your real teeth in photos and conversation.' => 'تُصنَع تلبيسات الزيركون حسب المقاس ويُطابَق لونها مع أسنانك الطبيعية، وتخرج من خط اللثة بشكل طبيعي — بلا حافة معدنية ظاهرة ولا حجم اصطناعي. لا يميّزها أحد عن أسنانك الحقيقية في الصور ولا في الحديث.',
		'Two visits: the first for surgery and temporary teeth (7 days), and a second visit 4–6 months later for the final prosthesis (3–5 days). The healing phase in between is managed remotely by VeaHealth with no travel required.' => 'زيارتان: الأولى للجراحة والأسنان المؤقتة (7 أيام)، والثانية بعد 4 إلى 6 أشهر للتعويض النهائي (3–5 أيام). أمّا مرحلة الالتئام بينهما فتديرها VeaHealth عن بُعد دون أي سفر.',
		'Two visits: the first for surgery and temporary teeth (7 days), and a second visit 5–6 months later for the final prosthesis (3–5 days). The healing phase in between is managed remotely by VeaHealth with no travel required.' => 'زيارتان: الأولى للجراحة والأسنان المؤقتة (7 أيام)، والثانية بعد 5 إلى 6 أشهر للتعويض النهائي (3–5 أيام). أمّا مرحلة الالتئام بينهما فتديرها VeaHealth عن بُعد دون أي سفر.',
		'Modern grafting techniques achieve 85–95% graft incorporation rates. With proper surgical technique, membrane protection, and healing time (4–6 months), grafted bone becomes indistinguishable from natural bone on CBCT scans.' => 'تحقّق تقنيات الترقيع الحديثة معدّلات اندماج بين 85 و95٪. ومع تقنية جراحية سليمة، وحماية بغشاء، ووقت التئام كافٍ (4 إلى 6 أشهر)، يصبح العظم المرقَّع لا يُميَّز عن العظم الطبيعي في أشعة CBCT.',
		'Patients with moderate to severe bone loss often benefit from All-on-6 over All-on-4. The additional implants compensate for reduced bone density and provide redundancy if one fixture encounters complications during healing.' => 'غالباً ما يستفيد المرضى ذوو الفقد العظمي المتوسّط إلى الشديد من All-on-6 أكثر من All-on-4. فالغرسات الإضافية تعوّض قلّة كثافة العظم وتوفّر هامش أمان إن واجهت إحداها مشكلة أثناء الالتئام.',
		'Temporary veneers are removed and your E-max Lumineers are test-fitted. Your dentist checks fit, bite, and aesthetics. Once perfect, each veneer is bonded permanently using advanced resin adhesive under controlled isolation.' => 'تُنزع القشور المؤقتة وتُجرَّب قشور E-max. ويتحقّق طبيبك من الانطباق والإطباق والمظهر. وبعد أن يصير كل شيء مضبوطاً، تُلصَق كل قشرة بشكل دائم بلاصق راتنجي متقدّم تحت عزل محكم.',
		'Custom zirconia bridges restore natural smile line, lip support, and facial volume — preventing the “sunken face” appearance that accompanies long-term denture use. Every prosthesis is shade-matched and individually designed.' => 'تُعيد جسور الزيركون المصنوعة حسب المقاس خط الابتسامة الطبيعي، ودعم الشفتين، وحجم الوجه — فتمنع مظهر «الوجه الغائر» الذي يرافق استعمال الطقم لسنوات. وكل تعويض يُطابَق لونه ويُصمَّم لصاحبه وحده.',
		'That depends almost entirely on angle, direction and restraint in density. A brow grafted at the wrong angle looks wrong no matter how many hairs it has. Ask to see the surgeon\'s own eyebrow cases, not general clinic results.' => 'يتوقّف ذلك كلّه تقريباً على الزاوية والاتّجاه وضبط النفس في الكثافة. فالحاجب المزروع بزاوية خاطئة يبدو خاطئاً مهما بلغ عدد شعراته. واطلب أن ترى حالات الحواجب التي أجراها الجرّاح نفسه، لا نتائج العيادة عموماً.',
		'Transplanted hair sheds after 2–4 weeks (normal). New growth begins at month 3. You’ll see 50% density by month 6, 90% by month 9, and full final result by month 12. Results are permanent and continue improving for 18 months.' => 'يتساقط الشعر المزروع بعد أسبوعين إلى أربعة، وهذا طبيعي ومؤقّت. ويبدأ النمو الجديد في الشهر الثالث. وسترى 50٪ من الكثافة في الشهر السادس، و90٪ في التاسع، والنتيجة النهائية كاملةً في الشهر الثاني عشر. والنتيجة دائمة وتستمرّ في التحسّن حتى 18 شهراً.',
		'E-max ceramic is non-porous and highly resistant to staining from coffee, wine, tea, and tobacco. The glazed surface remains smooth and bright indefinitely — no special maintenance required beyond normal brushing and flossing.' => 'خزف E-max غير مسامي وشديد المقاومة لتصبّغات القهوة والنبيذ والشاي والتبغ. ويبقى سطحه المزجَّج ناعماً لامعاً بلا حدّ زمني — ولا يحتاج عناية خاصة أبعد من التفريش والخيط المعتادين.',
		'Six implants distribute chewing forces more evenly across the arch, reducing stress on individual fixtures. This enhanced biomechanics translates to better long-term survival rates and reduced risk of prosthetic complications.' => 'توزّع الغرسات الست قوى المضغ على الفك بشكل أكثر تساوياً، فيقلّ الإجهاد على كل غرسة. وهذه الميكانيكا الحيوية الأفضل تُترجَم إلى معدّلات بقاء أعلى على المدى الطويل ومضاعفات تعويضية أقل.',
		'The additional posterior implants minimize cantilever extension (unsupported bridge length), which is the primary cause of prosthetic fracture in full arch restorations. This means fewer repairs and longer prosthesis lifespan.' => 'تقلّل الغرسات الخلفية الإضافية طول الامتداد الحرّ من الجسر (الجزء غير المسنود)، وهو السبب الأول لكسر التعويض في الفك الكامل. أي إصلاحات أقل وعمر أطول للتعويض.',
		'The titanium post integrates with your jawbone through osseointegration — stimulating natural bone maintenance just like a tooth root. This prevents the bone resorption and facial collapse that occurs with bridges or dentures.' => 'يندمج عمود التيتانيوم مع عظم الفك عبر الاندماج العظمي — فيحفّز العظم على تجديد نفسه تماماً كما يفعل جذر السن. وهذا يمنع امتصاص العظم وانهيار ملامح الوجه الذي يحدث مع الجسور أو الأطقم.',
		'Digital design and CAD/CAM fabrication allow same-visit try-ins. Most patients complete their E-max Lumineers in 3–5 days in Istanbul — consultation, preparation, fabrication, and bonding all in one trip with immediate results.' => 'يتيح التصميم الرقمي والتصنيع بتقنية CAD/CAM التجربة في الزيارة نفسها. ويُنهي معظم المرضى قشور E-max خلال 3 إلى 5 أيام في إسطنبول — استشارة وتحضير وتصنيع ولصق في رحلة واحدة، بنتيجة فورية.',
		'You receive a fixed provisional bridge the same day, so you are never without teeth. A soft diet is maintained for 6–8 weeks. Once osseointegration is confirmed and the final bridge placed, you resume a full, unrestricted diet.' => 'تحصل على جسر مؤقت ثابت في اليوم نفسه، فلا تبقى بلا أسنان. ويستمرّ النظام الغذائي الطري من 6 إلى 8 أسابيع. وبعد تأكّد الاندماج العظمي وتركيب الجسر النهائي، تعود إلى الأكل الكامل بلا قيود.',
		'Sapphire’s antibacterial properties and smooth surface reduce infection risk and inflammation. Less trauma to recipient area means less shock loss of existing hair — preserving your natural hair alongside transplanted follicles.' => 'خصائص الياقوت المضادة للبكتيريا وسطحه الأملس يقلّلان خطر الالتهاب والتورّم. وقلّة الرضّ في المنطقة المستقبِلة تعني تساقطاً صدمياً أقل للشعر الموجود — فيبقى شعرك الطبيعي إلى جانب الطُعوم المزروعة.',
		'No — but that’s not the goal. You may still grind, but the guard absorbs the force, preventing damage to your teeth. Most patients report 60–80% reduction in grinding intensity within 3–4 weeks as the jaw muscles adapt and relax.' => 'لا — وليس هذا هو الغرض منه. فقد تستمرّ في الصرير، لكن الواقي يمتصّ القوة ويحمي أسنانك من التلف. ويصف معظم المرضى انخفاضاً بنسبة 60 إلى 80٪ في شدّة الصرير خلال 3 إلى 4 أسابيع مع تأقلم عضلات الفك واسترخائها.',
		'Protect your teeth from grinding (bruxism) and jaw disorders (TMJ) with a professionally fitted custom night guard. Premium materials, precise fit, long-lasting protection. VeaHealth coordinates your complete dental care journey.' => 'احمِ أسنانك من صرير الأسنان ومن اضطرابات مفصل الفك بواقٍ ليلي مفصَّل يضبطه مختصّ. مواد من الفئة الأولى، وانطباق دقيق، وحماية تدوم. وتنسّق VeaHealth رحلة علاجك السنّي كاملةً.',
		'Before you travel, VeaHealth coordinates advanced diagnostics — high-resolution CBCT scan showing zygomatic anatomy, sinus positioning, and nerve pathways. A specialized zygomatic surgeon designs your implant trajectory virtually.' => 'قبل سفرك، تنسّق VeaHealth تشخيصاً متقدّماً — أشعة CBCT عالية الدقّة تُظهر تشريح عظم الوجنة، وموضع الجيوب، ومسارات الأعصاب. ويرسم جرّاح متخصّص في الغرسات الوجنية مسار غرساتك افتراضياً.',
		'E-max is 100% biocompatible with no allergic potential. The smooth ceramic surface promotes healthy gum tissue and prevents bacterial adhesion better than composite veneers. Long-term gingival health is excellent in clinical studies.' => 'E-max متوافق حيوياً 100٪ وبلا قدرة على إثارة الحساسية. وسطحه الخزفي الناعم يشجّع لثةً سليمة ويمنع التصاق البكتيريا أفضل من القشور المركّبة. وصحة اللثة على المدى الطويل ممتازة في الدراسات السريرية.',
		'Maxillary sinus augmentation creates space for dental implants in the posterior upper jaw. Premium bone graft materials, 3D-guided precision, and expert oral surgeons. VeaHealth coordinates your complete sinus lift journey in Turkey.' => 'يوفّر تعزيز الجيب الفكّي العلوي المساحة اللازمة لغرسات الأسنان في المنطقة الخلفية من الفك العلوي. مواد ترقيع من الفئة الأولى، ودقّة موجَّهة ثلاثية الأبعاد، وجرّاحو فم ذوو خبرة. وتنسّق VeaHealth رحلتك كاملةً في تركيا.',
		'Thyroid disorder, iron deficiency, post-partum shedding, traction from tight styling and several autoimmune conditions all thin hair, and all are treated without surgery. Bloods and an examination come before any surgical discussion.' => 'اضطراب الغدة الدرقية، ونقص الحديد، وتساقط ما بعد الولادة، والشدّ الناتج عن تسريحات مشدودة، وعدّة أمراض مناعية ذاتية — كلّها تُخفّف الشعر، وكلّها تُعالَج دون جراحة. لذا تأتي تحاليل الدم والفحص قبل أي حديث عن عملية.',
		'Zygomatic implants bypass the atrophied upper jaw entirely by anchoring into the cheekbone — which never resorbs. This eliminates 6–12 months of bone graft healing and multiple surgeries, saving time and avoiding graft complications.' => 'تتجاوز الغرسات الوجنية الفك العلوي الضامر تماماً بتثبيتها في عظم الوجنة الذي لا يُمتصّ أبداً. وهذا يُلغي 6 إلى 12 شهراً من التئام الطُعم العظمي وعدّة عمليات، فيوفّر الوقت ويتفادى مضاعفات الترقيع.',
		'With proper oral hygiene, zirconia crowns last 15–20+ years on average. Studies confirm 95%+ survival at 10 years. Longevity depends on oral hygiene, avoiding hard foods (ice, nuts), and managing grinding with a night guard if needed.' => 'مع نظافة فم سليمة، تدوم تلبيسة الزيركون 15 إلى 20 سنة فأكثر في المتوسط. وتؤكّد الدراسات بقاءً يفوق 95٪ بعد 10 سنوات. ويتوقّف طول عمرها على النظافة، وتجنّب الأطعمة الصلبة (الثلج والمكسّرات)، وضبط صرير الأسنان بواقٍ ليلي عند الحاجة.',
		'Yes. VeaHealth’s 2-year warranty covers manufacturing defects and premature wear — valid worldwide. If issues arise after you return home, VeaHealth coordinates a replacement remotely or via a local affiliated dentist in your country.' => 'نعم. يغطّي ضمان VeaHealth لمدّة سنتين عيوب التصنيع والتآكل المبكر — وهو ساري المفعول في كل أنحاء العالم. وإذا ظهرت مشكلة بعد عودتك، تنسّق VeaHealth الاستبدال عن بُعد أو عبر طبيب أسنان شريك في بلدك.',
		'Four implants deliver a full restoration at a fraction of the cost of individual implants for each missing tooth. VeaHealth’s Istanbul pricing is 60–70% below UK and US rates — with no compromise on brand quality or clinical standards.' => 'تكفي أربع غرسات لتعويض فكّ كامل بجزء يسير من تكلفة غرسة لكل سنّ مفقودة. وأسعار VeaHealth في إسطنبول أقل بنسبة 60–70٪ من أسعار بريطانيا وأمريكا — دون أي تنازل عن ماركة الغرسات ولا عن المعايير السريرية.',
		'Two visits: the first for surgery and temporary teeth (7–10 days due to more intensive monitoring), and a second visit 5–6 months later for the final prosthesis (3–5 days). The healing phase in between is managed remotely by VeaHealth.' => 'زيارتان: الأولى للجراحة والأسنان المؤقتة (7–10 أيام بسبب المراقبة الأكثف)، والثانية بعد 5 إلى 6 أشهر للتعويض النهائي (3–5 أيام). أمّا مرحلة الالتئام بينهما فتديرها VeaHealth عن بُعد.',
		'Zygomatic implants are specialized titanium fixtures anchored in the dense cheekbone (zygoma) rather than the jaw. They’re the gold standard for patients with severe upper jaw bone loss who would otherwise need extensive bone grafting.' => 'الغرسات الوجنية غرسات تيتانيوم مخصَّصة تُثبَّت في عظم الوجنة الكثيف بدل عظم الفك. وهي المعيار الذهبي لمن فقدوا عظماً كثيراً في الفك العلوي وكانوا سيحتاجون إلى ترقيع عظمي واسع.',
		'Clinical studies confirm 95–97% survival rates at 10+ years. The technique was pioneered in the 1990s and has decades of documented outcomes. Zygomatic implants are no longer experimental — they’re mainstream for severe bone loss cases.' => 'تؤكّد الدراسات السريرية معدّلات بقاء بين 95 و97٪ بعد أكثر من 10 سنوات. وقد ظهرت التقنية في التسعينيات ولها عقود من النتائج الموثَّقة. فالغرسات الوجنية لم تعد تجريبية — بل صارت الحلّ المعتمَد في حالات الفقد العظمي الشديد.',
		'Typically two visits: the first (2–4 days) for the implant placement, and a return visit (1–2 days) after osseointegration for the final crown. The healing phase in between is fully managed remotely by VeaHealth with no travel required.' => 'عادةً زيارتان: الأولى (2–4 أيام) لوضع الغرسة، وزيارة العودة (1–2 يوم) بعد الاندماج العظمي لتركيب التلبيسة النهائية. أمّا مرحلة الالتئام بينهما فتديرها VeaHealth عن بُعد بالكامل دون أي سفر.',
		'While zygomatic implants cost more than conventional ones, they’re far cheaper than the alternative: multiple sinus lifts + bone grafts + conventional implants. Total treatment time is also 6–9 months shorter, reducing overall expenses.' => 'الغرسة الوجنية أغلى من الغرسة التقليدية، لكنها أرخص بكثير من البديل: عدّة عمليات رفع للجيب الفكّي، وترقيع عظمي، ثم غرسات تقليدية. كما أن مدّة العلاج الكلية أقصر بـ6 إلى 9 أشهر، وهو ما يخفّض النفقات الإجمالية.',
		'You remain in Istanbul for 7–10 days for close monitoring. Swelling peaks at 72 hours. Your surgeon verifies implant stability and adjusts temporary teeth. Post-op care is more intensive than conventional implants due to sinus proximity.' => 'تبقى في إسطنبول من 7 إلى 10 أيام تحت مراقبة لصيقة. ويبلغ التورّم ذروته بعد 72 ساعة. ويتحقّق جرّاحك من ثبات الغرسات ويضبط الأسنان المؤقتة. والعناية بعد الجراحة أكثف منها في الغرسات التقليدية بسبب قرب الجيوب الأنفية.',
		'2–3 years with proper care for most patients. Heavy grinders may need replacement sooner (12–18 months). Signs of wear include visible thinning, cracks, or loss of fit. Regular cleaning and storage in the provided case maximizes lifespan.' => 'من سنتين إلى ثلاث مع عناية سليمة لدى معظم المرضى. أمّا من يصرّون بشدّة فقد يحتاجون تبديله أبكر (12 إلى 18 شهراً). ومن علامات التآكل: ترقّق ظاهر، أو شقوق، أو فقدان الانطباق. والتنظيف المنتظم والحفظ في العلبة المرفقة يطيلان عمره.',
		'Clinical studies confirm 95–98% survival rates at 10 years. With proper hygiene and regular check-ups, single implants routinely last 20–30+ years. The titanium fixture can last a lifetime — only the crown may eventually need replacement.' => 'تؤكّد الدراسات السريرية معدّلات بقاء بين 95 و98٪ بعد 10 سنوات. ومع نظافة سليمة وفحوصات منتظمة، تدوم الغرسة الواحدة عادةً 20 إلى 30 سنة وأكثر. أمّا جزء التيتانيوم فقد يدوم مدى الحياة — والتلبيسة وحدها هي التي قد تحتاج إلى تبديل يوماً ما.',
		'Full graft incorporation takes 4–6 months depending on the material and defect size. Autogenous grafts heal fastest (3–4 months), while xenografts typically need 5–6 months. A follow-up CBCT scan confirms healing before implant placement.' => 'يستغرق اندماج الطُعم الكامل من 4 إلى 6 أشهر حسب المادة وحجم العيب. والطُعم المأخوذ من عظم المريض يلتئم أسرع (3 إلى 4 أشهر)، أمّا الطُعم من مصدر حيواني فيحتاج عادةً 5 إلى 6 أشهر. وتؤكّد أشعة CBCT للمتابعة الالتئام قبل وضع الغرسة.',
		'The procedure is performed under local anesthesia — no pain during surgery, only mild pressure. Post-op discomfort (soreness, swelling) peaks at 48 hours and typically resolves within a week with prescribed medication and cold compresses.' => 'يُجرى العمل تحت تخدير موضعي — بلا ألم أثناء الجراحة، بل إحساس بالضغط فقط. أمّا الانزعاج بعدها (وجع وتورّم) فيبلغ ذروته بعد 48 ساعة ويزول عادةً خلال أسبوع بالأدوية الموصوفة والكمّادات الباردة.',
		'Two visits: the first for implant surgery and temporary teeth (7 days), and a second visit 5–6 months later for the final hybrid prosthesis (4–5 days). The healing phase in between is managed remotely by VeaHealth with no travel required.' => 'زيارتان: الأولى لجراحة الغرسات والأسنان المؤقتة (7 أيام)، والثانية بعد 5 إلى 6 أشهر للتركيبة الهجينة النهائية (4–5 أيام). أمّا مرحلة الالتئام بينهما فتديرها VeaHealth عن بُعد دون أي سفر.',
		'Yes. VeaHealth’s lifetime graft warranty covers transplanted follicles that fail to grow (< 2% incidence). Valid worldwide with full documentation. If a warranty claim arises, VeaHealth coordinates resolution remotely or via re-treatment.' => 'نعم. يغطّي ضمان VeaHealth مدى الحياة على الطُعوم تلك التي لا تنمو (أقل من 2٪ من الحالات). وهو ساري المفعول عالمياً مع وثائق كاملة. وإذا نشأت مطالبة بالضمان، تنسّق VeaHealth الحلّ عن بُعد أو بإعادة العلاج.',
		'Your surgeon removes bandages, performs the first hair wash, and provides PRP treatment to accelerate healing. You receive detailed aftercare instructions, medications (antibiotics, painkillers), and special shampoo before returning home.' => 'يزيل جرّاحك الضمادات، ويُجري أول غسل للشعر، ويحقن البلازما PRP لتسريع الالتئام. وتتسلّم تعليمات مفصّلة للعناية، والأدوية (مضادات حيوية ومسكّنات)، وشامبو خاصاً قبل عودتك.',
		'Despite being ultra-thin, E-max has a flexural strength of 400–500 MPa — 4× stronger than traditional porcelain veneers. This allows thinner veneers that resist chipping and fracture while maintaining structural integrity for 15–20+ years.' => 'رغم رقّتها البالغة، تبلغ مقاومة E-max للانحناء 400–500 ميغاباسكال — أي أربعة أضعاف مقاومة القشور الخزفية التقليدية. وهذا يتيح قشوراً أرقّ تقاوم التشظّي والكسر وتحافظ على تماسكها 15 إلى 20 سنة فأكثر.',
		'Premium porcelain or zirconia indirect restorations. Precision-fit lab-crafted fillings that preserve maximum tooth structure while delivering natural aesthetics and superior strength. VeaHealth coordinates your complete treatment journey.' => 'تعويضات غير مباشرة من الفئة الأولى، من الخزف أو الزيركون. تُصنَع في المختبر بانطباق دقيق يحفظ أكبر قدر من بنية السن، ويعطي مظهراً طبيعياً وقوةً متفوّقة. وتنسّق VeaHealth رحلة علاجك كاملةً.',
		'Temporary teeth are attached the same day as surgery — you walk out with a full smile. The dense zygomatic bone provides immediate primary stability, allowing for functional loading within 24–48 hours unlike traditional grafting protocols.' => 'تُثبَّت الأسنان المؤقتة في يوم الجراحة نفسه — فتخرج بابتسامة كاملة. وكثافة عظم الوجنة تمنح ثباتاً ابتدائياً فورياً يسمح بالتحميل الوظيفي خلال 24 إلى 48 ساعة، بخلاف بروتوكولات الترقيع التقليدية.',
		'With proper care, porcelain and zirconia inlays/onlays last 10–15+ years on average — significantly longer than composite fillings (5–7 years). Longevity depends on oral hygiene, bite forces, and avoiding habits like grinding or chewing ice.' => 'مع عناية سليمة، تدوم حشوات الإنلاي والأونلاي من الخزف والزيركون 10 إلى 15 سنة فأكثر في المتوسط — أطول بكثير من الحشوات المركّبة (5 إلى 7 سنوات). ويتوقّف عمرها على نظافة الفم، وقوى الإطباق، وتجنّب عادات كصرير الأسنان أو مضغ الثلج.',
		'The titanium post can last a lifetime with proper care. Studies confirm >95% survival at 10 years. The zirconia crown may need replacement after 15–20 years depending on wear. Regular 6-month check-ups are the primary maintenance requirement.' => 'قد يدوم عمود التيتانيوم مدى الحياة مع عناية سليمة. وتؤكّد الدراسات بقاءً يفوق 95٪ بعد 10 سنوات. أمّا تلبيسة الزيركون فقد تحتاج إلى تبديل بعد 15–20 سنة حسب التآكل. والفحص كل ستة أشهر هو أهمّ ما تتطلّبه العناية.',
		'Yes, with precautions. Night guards and reinforced prosthetic materials are used to protect against excessive wear from grinding. VeaHealth evaluates bite forces during planning and designs the restoration to manage bruxism loads effectively.' => 'نعم، مع احتياطات. إذ يُستعمل واقٍ ليلي ومواد تعويضية مقوّاة للحماية من التآكل الزائد الناتج عن الجَز. وتقيس VeaHealth قوى الإطباق أثناء التخطيط وتصمّم التعويض ليتحمّل أحمال صرير الأسنان.',
		'Lifetime. Follicles transplanted from the permanent donor zone (back of head) are genetically resistant to DHT hormone and retain this resistance after transplantation. They grow naturally for life with zero maintenance or medications required.' => 'مدى الحياة. فالطُعوم المأخوذة من المنطقة المانحة الدائمة في مؤخّرة الرأس مقاومة وراثياً لهرمون DHT، وتحتفظ بهذه المقاومة بعد الزراعة. فتنمو نمواً طبيعياً مدى الحياة دون أي صيانة أو أدوية.',
		'No movement, no adhesives. Chewing efficiency approaches that of natural teeth — allowing a full diet. Implant-supported full-arch prostheses outperform removable dentures significantly in clinical chewing assessments (Pjetursson et al., 2005).' => 'لا حركة ولا لواصق. وتقترب كفاءة المضغ من كفاءة الأسنان الطبيعية — فتسمح بنظام غذائي كامل. وفي تقييمات المضغ السريرية تتفوّق تعويضات الفك المحمولة على غرسات تفوّقاً واضحاً على الأطقم المتحرّكة (Pjetursson وزملاؤه، 2005).',
		'No protocol reliably accelerates the biological growth cycle. Transplanted follicles shed and regrow on their own timeline — visible growth from around month three, assessment at twelve months. Any clinic promising faster growth is overselling.' => 'لا يوجد بروتوكول يُسرِّع دورة النمو البيولوجية بشكل موثوق. فالطُعوم المزروعة تتساقط ثم تنمو وفق جدولها هي — نمو مرئي من نحو الشهر الثالث، وتقييم عند الشهر الثاني عشر. وأي عيادة تعدك بنمو أسرع فهي تبالغ في وعدها.',
		'Yes. VeaHealth’s lifetime warranty on implants and 3-year warranty on prosthetics are valid worldwide. If a warranty issue arises after you return home, VeaHealth coordinates resolution remotely or via a local affiliated clinic in your country.' => 'نعم. ضمان VeaHealth مدى الحياة على الغرسات وضمان 3 سنوات على التعويض ساريان في كل أنحاء العالم. وإذا ظهرت مشكلة مشمولة بالضمان بعد عودتك، تتولّى VeaHealth حلّها عن بُعد أو عبر عيادة شريكة في بلدك.',
		'The procedure is performed under local anesthesia — no pain during surgery, only mild pressure. Post-op discomfort is minimal (mild soreness) and managed with over-the-counter painkillers. Most patients describe it as less painful than expected.' => 'تُجرى العملية تحت تخدير موضعي — بلا ألم أثناء الجراحة، بل إحساس خفيف بالضغط فقط. أمّا الانزعاج بعدها فضئيل (وجع خفيف) ويُضبط بمسكّنات عادية. ويصفه معظم المرضى بأنه أقل ألماً ممّا توقّعوا.',
		'Under local anesthesia (if needed), your teeth receive minimal surface preparation — typically just cleaning and light etching. For many patients, zero enamel removal is required. Temporary veneers are placed to protect teeth during fabrication.' => 'تحت تخدير موضعي عند الحاجة، تخضع أسنانك لتحضير سطحي أدنى — عادةً مجرّد تنظيف وتخشين خفيف. ولا يُزال أي مينا لدى كثير من المرضى. وتُركَّب قشور مؤقتة لحماية الأسنان أثناء التصنيع.',
		'Full clinical consultation, panoramic X-rays, and CBCT 3D scan to assess bone density and volume. Anatomical landmarks (sinuses, nerves) are mapped, and systemic health conditions are reviewed. Your VeaHealth coordinator accompanies you throughout.' => 'استشارة سريرية كاملة، وأشعة بانورامية، وأشعة CBCT ثلاثية الأبعاد لتقييم كثافة العظم وحجمه. وتُرسم المعالم التشريحية (الجيوب والأعصاب)، وتُراجَع حالتك الصحية العامة. ويرافقك منسّق VeaHealth طوال الوقت.',
		'Two visits: the first for implant surgery and temporary teeth (7 days), and a second visit 5–6 months later for the final hybrid zirconium prosthesis (4–5 days). The healing phase in between is managed remotely by VeaHealth with no travel required.' => 'زيارتان: الأولى لجراحة الغرسات والأسنان المؤقتة (7 أيام)، والثانية بعد 5 إلى 6 أشهر للتركيبة الهجينة النهائية من الزيركون (4–5 أيام). أمّا مرحلة الالتئام بينهما فتديرها VeaHealth عن بُعد دون أي سفر.',
		'Yes. VeaHealth’s 3–5 year warranty covers manufacturing defects, premature fracture, and decementation — valid worldwide. If a warranty claim arises, VeaHealth coordinates replacement remotely or via a local affiliated dentist in your home country.' => 'نعم. يغطّي ضمان VeaHealth لمدّة 3–5 سنوات عيوب التصنيع، والكسر المبكر، وانفكاك التثبيت — وهو ساري المفعول في كل أنحاء العالم. وإذا نشأت مطالبة بالضمان، تنسّق VeaHealth الاستبدال عن بُعد أو عبر طبيب أسنان شريك في بلدك.',
		'Yes. After the initial healing period (3–6 months), you can eat all foods without restriction — including steak, nuts, apples, and corn on the cob. Chewing power is restored to 90–95% of natural teeth. No more dietary limitations like with dentures.' => 'نعم. بعد فترة الالتئام الأولى (3–6 أشهر) يمكنك أن تأكل كل شيء بلا قيد — اللحم والمكسّرات والتفاح والذرة. وتعود قوة المضغ إلى 90–95٪ من قوة الأسنان الطبيعية. ولا قيود غذائية بعد اليوم كما مع الطقم.',
		'Not necessarily. The no-shave technique trims donor hair only in narrow strips hidden beneath surrounding hair, so nothing is visible with your hair down. It takes longer and harvests fewer grafts per session, so suitability is decided at assessment.' => 'ليس بالضرورة. فتقنية «بلا حلاقة» تقصّ الشعر المانح في شرائط ضيّقة فقط، مخفيّة تحت الشعر المحيط، فلا يظهر شيء وأنت مرسِلة شعرك. لكنها تستغرق وقتاً أطول وتعطي طُعوماً أقل في الجلسة، ولذلك تُحسم ملاءمتها في التقييم.',
		'Possibly not. Diffuse thinning can include the donor area, and transplanting unstable donor hair gives a result that fades. Trichoscopy establishes donor stability. If it is not stable, you will be told so — medical treatment may be the better route.' => 'ربما لا. فالخفوف المنتشر قد يشمل المنطقة المانحة، وزراعة شعر مانح غير مستقرّ تعطي نتيجة تتلاشى. ويُثبت تنظير الشعر مدى استقرار المنطقة المانحة. فإن لم تكن مستقرّة، سيُقال لك ذلك — وقد يكون العلاج الدوائي هو الطريق الأفضل.',
		'Ultra-thin design (0.2–0.5mm) requires little to no enamel removal — preserving your natural tooth structure. Many patients need zero preparation, making the procedure reversible in some cases and significantly less invasive than traditional veneers.' => 'رقّتها البالغة (0.2–0.5 مم) لا تكاد تتطلّب إزالة أي مينا — فتبقى بنية سنّك الطبيعية على حالها. ولا يحتاج كثير من المرضى إلى أي تحضير، وهو ما يجعل الإجراء قابلاً للتراجع عنه في بعض الحالات، وأقل توغّلاً بكثير من القشور التقليدية.',
		'Ultra-thin, no-prep porcelain veneers in Istanbul. Made from advanced lithium disilicate ceramic for unmatched translucency and strength. Minimal tooth preparation. Natural-looking results. VeaHealth coordinates your complete cosmetic transformation.' => 'قشور خزفية فائقة الرقّة بلا برد في إسطنبول. مصنوعة من ثنائي سيليكات الليثيوم لشفافية ومتانة لا نظير لهما. تحضير أدنى للسن. ونتيجة طبيعية المظهر. وتنسّق VeaHealth تحوّلك التجميلي كاملاً.',
		'Fewer than with a motorised punch, because each unit is harvested by hand. The number depends on your donor density and scalp laxity and is quoted after the assessment. Large cases are sometimes planned across two sittings rather than forced into one.' => 'أقل ممّا يُقتطف بالمِثقب الآلي، لأن كل وحدة تُؤخذ باليد. ويتوقّف العدد على كثافة منطقتك المانحة وعلى مرونة فروة رأسك، ويُحدَّد بعد التقييم. والحالات الكبيرة تُخطَّط أحياناً على جلستين بدل حشرها في جلسة واحدة.',
		'Yes, but smoking increases the risk of gum disease around the crown margins and can stain the cement over time. VeaHealth strongly recommends reducing or stopping smoking before and after treatment to ensure optimal healing and long-term crown health.' => 'نعم، لكن التدخين يرفع خطر أمراض اللثة عند حواف التلبيسة وقد يُصبّغ اللاصق مع الوقت. وتنصح VeaHealth بشدّة بتقليل التدخين أو تركه قبل العلاج وبعده، لضمان التئام أفضل وسلامة التلبيسة على المدى الطويل.',
		'Absolutely. Zirconia is ideal for anterior (front) teeth due to its metal-free composition, light translucency, and natural appearance. VeaHealth’s ceramists specialize in creating highly aesthetic anterior crowns that blend seamlessly with your smile.' => 'بالتأكيد. الزيركون مثالي للأسنان الأمامية لأنه خالٍ من المعادن، شفّاف للضوء، وطبيعي المظهر. ويتخصّص فنّيو الخزف لدى VeaHealth في صنع تلبيسات أمامية عالية الجماليات تنسجم مع ابتسامتك انسجاماً تاماً.',
		'Typically one 3–5 day visit. Day 1: consultation and minimal prep. Days 2–4: lab fabrication. Day 5: final bonding. The entire transformation happens in a single trip with immediate results. No return visits required unless you need adjustments (rare).' => 'عادةً زيارة واحدة من 3 إلى 5 أيام. اليوم 1: الاستشارة والتحضير الأدنى. الأيام 2–4: التصنيع في المختبر. اليوم 5: اللصق النهائي. فيتمّ التحوّل كلّه في رحلة واحدة بنتيجة فورية. ولا تلزم زيارة ثانية إلا إن احتجت تعديلات، وهو نادر.',
		'Metal-free dental crowns crafted from high-strength zirconia ceramic. Natural translucency, biocompatible, and built to last 15–20+ years. VeaHealth coordinates your entire journey with verified clinics, expert ceramists, and complete aftercare support.' => 'تلبيسات أسنان بلا معدن، مصنوعة من خزف الزيركون العالي القوة. شفافية طبيعية، وتوافق حيوي، وعمر متوقَّع من 15 إلى 20 سنة فأكثر. وتنسّق VeaHealth رحلتك كاملةً مع عيادات موثَّقة وفنّيي خزف مهرة ومتابعة تامة.',
		'The zygomatic bone is 3–4 times denser than maxillary bone. This exceptional density provides rock-solid implant stability and reduces risk of early failure. Zygomatic implants routinely achieve higher insertion torque values than conventional implants.' => 'عظم الوجنة أكثف من عظم الفك العلوي بثلاث إلى أربع مرات. وهذه الكثافة الاستثنائية تمنح الغرسة ثباتاً شديداً وتقلّل خطر الفشل المبكر. وتحقّق الغرسات الوجنية عادةً قيم عزم إدخال أعلى من الغرسات التقليدية.',
		'Under local anesthesia or IV sedation, the lateral window is created using piezoelectric instruments. The Schneiderian membrane is gently elevated. Bone graft material fills the space beneath the membrane. A resorbable collagen membrane seals the window.' => 'تحت تخدير موضعي أو تركين وريدي، تُفتح النافذة الجانبية بأدوات كهرضغطية. ثم يُرفع غشاء شنايدر برفق، وتُملأ المساحة تحته بمادة الترقيع العظمي. ويُغلق فتحُ النافذة بغشاء كولاجيني قابل للامتصاص.',
		'Yes. VeaHealth’s lifetime warranty on implants and 3-year warranty on the hybrid prosthesis are valid worldwide. If a warranty issue arises after you return home, VeaHealth coordinates resolution remotely or via a local affiliated clinic in your country.' => 'نعم. ضمان VeaHealth مدى الحياة على الغرسات وضمان 3 سنوات على التركيبة الهجينة ساريان في كل أنحاء العالم. وإذا ظهرت مشكلة مشمولة بالضمان بعد عودتك، تتولّى VeaHealth حلّها عن بُعد أو عبر عيادة شريكة في بلدك.',
		'Permanent tooth replacement in Istanbul with premium titanium implants and natural zirconia crowns. Straumann & Nobel Biocare brands. 95%+ success rate. VeaHealth coordinates your complete dental tourism journey with verified clinics and expert aftercare.' => 'تعويض دائم للسن في إسطنبول بغرسات تيتانيوم من الفئة الأولى وتلبيسات زيركون طبيعية المظهر. ماركتا Straumann وNobel Biocare. نسبة نجاح تتجاوز 95٪. وتنسّق VeaHealth رحلتك العلاجية كاملةً مع عيادات موثَّقة ومتابعة على يد مختصّين.',
		'Common signs include: waking with jaw pain or headaches, worn/flat teeth surfaces, tooth sensitivity, clicking or popping jaw, partner hearing grinding at night, or visible cracks in teeth. Your dentist can definitively diagnose bruxism during examination.' => 'من العلامات الشائعة: الاستيقاظ بألم في الفك أو بصداع، وأسطح أسنان متآكلة ومسطّحة، وحساسية في الأسنان، وطقطقة في الفك، وسماع من ينام إلى جانبك صوت الصرير ليلاً، أو شقوق ظاهرة في الأسنان. ويستطيع طبيبك تشخيص صرير الأسنان بشكل قاطع أثناء الفحص.',
		'One visit for the bone graft surgery (5–7 days), then you return home to heal for 4–6 months. After healing is confirmed via CBCT scan, a second visit is needed for implant placement. The entire timeline from graft to final crown is typically 10–12 months.' => 'زيارة واحدة لجراحة الترقيع (5–7 أيام)، ثم تعود إلى بيتك لتلتئم خلال 4 إلى 6 أشهر. وبعد تأكيد الالتئام بأشعة CBCT، تلزم زيارة ثانية لوضع الغرسة. أمّا المدّة الكلية من الترقيع إلى التلبيسة النهائية فهي عادةً 10 إلى 12 شهراً.',
		'Premium porcelain-acrylic hybrid restoration on dental implants. Combines natural porcelain teeth with durable acrylic gum base for optimal aesthetics and repairability. Implant-supported, fixed solution. VeaHealth coordinates your complete transformation.' => 'تعويض هجين من الخزف والأكريل من الفئة الأولى على غرسات الأسنان. يجمع بين أسنان خزفية طبيعية المظهر وقاعدة لثة أكريلية متينة، فيعطي أفضل مظهر وسهولةً في الإصلاح. حلّ ثابت محمول على الغرسات. وتنسّق VeaHealth تحوّلك كاملاً.',
		'Upper arch guards are most common as they’re less intrusive and easier to wear. Lower guards are recommended for patients with gag reflexes or specific bite issues. Your dentist will recommend the optimal position based on your anatomy and grinding pattern.' => 'الوقايات العلوية هي الأكثر شيوعاً لأنها أقل إزعاجاً وأسهل لبساً. أمّا الوقايات السفلية فيُنصح بها لمن لديهم منعكس تقيّؤ أو مشاكل إطباق خاصة. ويحدّد لك طبيبك الوضع الأنسب حسب تشريحك ونمط الصرير لديك.',
		'Yes. Modern zirconia offers excellent translucency and can be custom-shaded to match your natural teeth precisely. Multi-layered characterization replicates the subtle color gradients found in real enamel. No dark metal margin will ever show at the gumline.' => 'نعم. يمنح الزيركون الحديث شفافية ممتازة، ويمكن ضبط لونه حسب المقاس ليطابق أسنانك بدقّة. ويعيد التلوين متعدّد الطبقات إنتاج التدرّجات اللونية الدقيقة الموجودة في المينا الطبيعية. ولن يظهر أي حدّ معدني داكن عند خط اللثة أبداً.',
		'Depends on your Norwood classification and coverage goals. Typical ranges: hairline restoration (1500–2500 grafts), crown filling (2000–3000 grafts), full coverage (4000–5000 grafts). VeaHealth’s surgeons provide exact counts during pre-treatment assessment.' => 'يتوقّف ذلك على تصنيفك على مقياس نوروود وعلى المساحة المراد تغطيتها. وهذه أرقام تقريبية: استعادة خط الشعر الأمامي (1500–2500 طُعم)، وتكثيف التاج (2000–3000 طُعم)، والتغطية الكاملة (4000–5000 طُعم). ويعطيك جرّاحو VeaHealth العدد الدقيق أثناء التقييم قبل العلاج.',
		'VeaHealth uses premium materials like Bio-Oss (xenograft) or Cerabone depending on your specific case. The material is confirmed in your treatment plan. Autogenous grafts (your own bone) are also available if preferred, harvested from the chin or ramus area.' => 'تستعمل VeaHealth مواد من الفئة الأولى مثل Bio-Oss (من مصدر حيواني) أو Cerabone حسب حالتك. وتُذكر المادة المعتمَدة في خطة علاجك. كما يتوفّر الترقيع من عظمك أنت إن فضّلته، ويُؤخذ من منطقة الذقن أو الفرع الصاعد للفك.',
		'VeaHealth’s partner labs use premium brands like Ivoclar Vivadent, 3M Lava, or Prettau — all FDA-approved and CE-certified. The specific brand and batch number are documented in your treatment file and provided at completion. This is a contractual guarantee.' => 'تستعمل مختبرات VeaHealth الشريكة ماركات من الفئة الأولى مثل Ivoclar Vivadent وM3 Lava وPrettau — وكلّها معتمَدة من FDA وحاصلة على شهادة CE. وتُدوَّن الماركة ورقم التشغيلة في ملفّ علاجك وتُسلَّم لك عند انتهائه. وهذا التزام تعاقدي.',
		'E-max lithium disilicate ceramic mimics natural enamel’s light-transmitting properties perfectly. Unlike opaque traditional veneers, E-max reflects light naturally — creating depth, vitality, and a lifelike appearance that’s indistinguishable from real teeth.' => 'يحاكي خزف E-max من ثنائي سيليكات الليثيوم نفاذ الضوء عبر المينا الطبيعية محاكاةً تامة. وبخلاف القشور التقليدية المعتمة، يعكس E-max الضوء بشكل طبيعي — فيمنح عمقاً وحيويةً ومظهراً لا يُميَّز عن الأسنان الحقيقية.',
		'Enhanced full arch restoration with 6 strategically placed implants per jaw. Superior stability and load distribution compared to All-on-4. Straumann & Nobel Biocare brands. Same-day temporary teeth. VeaHealth coordinates your complete transformation journey.' => 'تعويض فكّ كامل مُعزَّز بـ6 غرسات موضوعة في المواضع الأهم. ثبات وتوزيع للقوى أفضل من All-on-4. ماركتا Straumann وNobel Biocare. أسنان مؤقتة في اليوم نفسه. وتنسّق VeaHealth رحلة تحوّلك كاملةً.',
		'Yes. Transplanted hairs keep the growth cycle of their donor site, so they grow to scalp length rather than brow length. Trimming every two to four weeks becomes part of your routine, permanently. Anyone who tells you otherwise is not being straight with you.' => 'نعم. فالشعر المزروع يحتفظ بدورة نمو موضعه الأصلي، فينمو إلى طول شعر الرأس لا إلى طول شعر الحاجب. ويصبح التقصير كل أسبوعين إلى أربعة جزءاً من روتينك، بشكل دائم. ومن يقول لك غير ذلك فهو لا يصدقك القول.',
		'Advanced Sapphire FUE technique using precision sapphire blades for micro-channel creation. Natural hairline design, maximum graft survival (95%+), minimal scarring. 4000–5000 grafts in one session. VeaHealth coordinates your complete hair restoration journey.' => 'تقنية سفير المتقدّمة تستعمل شفرات الياقوت الدقيقة لفتح القنوات الدقيقة. خط شعر أمامي مرسوم لملامحك، وأقصى معدّل بقاء للطُعوم (يفوق 95٪)، وندوب ضئيلة. من 4000 إلى 5000 طُعم في جلسة واحدة. وتنسّق VeaHealth رحلة استعادة شعرك كاملةً.',
		'Rinse with cold water after each use. Brush gently with soft toothbrush and non-abrasive soap daily. Soak weekly in denture cleaner or diluted white vinegar (1:1) for 30 minutes. Never use hot water or abrasive toothpaste — this can warp or scratch the acrylic.' => 'اشطفه بماء بارد بعد كل استعمال. ونظّفه يومياً بفرشاة ناعمة وصابون غير كاشط. وانقعه أسبوعياً 30 دقيقة في منظّف أطقم الأسنان أو خلّ أبيض مخفَّف (بنسبة 1:1). ولا تستعمل أبداً ماءً ساخناً ولا معجون أسنان كاشطاً — فذلك يشوّه الأكريل أو يخدشه.',
		'Smokers are not excluded but tobacco significantly increases failure risk — nicotine reduces gingival blood flow and slows osseointegration. VeaHealth strongly advises reducing or stopping smoking at least 4–6 weeks before and after surgery to protect outcomes.' => 'المدخّنون غير مستبعَدين، لكن التبغ يرفع خطر الفشل ارتفاعاً واضحاً — إذ يقلّل النيكوتين تدفّق الدم في اللثة ويبطّئ الاندماج العظمي. وتنصح VeaHealth بشدّة بتقليل التدخين أو تركه 4 إلى 6 أسابيع على الأقل قبل الجراحة وبعدها، حمايةً للنتيجة.',
		'Yes — dramatically. Custom guards are precisely molded to your teeth, so they stay in place without bulk or gagging. Patients report forgetting they’re wearing them within 2–3 nights. OTC guards are often bulky, slip during sleep, and cause gagging or drooling.' => 'نعم — والفرق كبير. فالواقي المفصَّل مصبوب على أسنانك بدقّة، فيبقى في مكانه بلا ضخامة ولا غثيان. ويقول المرضى إنهم ينسون وجوده بعد ليلتين أو ثلاث. أمّا الوقايات الجاهزة فغالباً ما تكون ضخمة، وتنزلق أثناء النوم، وتسبّب الغثيان أو سيلان اللعاب.',
		'Your dentist performs a comprehensive smile assessment with digital photography and intraoral scans. Together you design your ideal smile — selecting shade, shape, and length. Digital smile design software shows you the final result before any tooth preparation.' => 'يُجري طبيبك تقييماً كاملاً لابتسامتك بالتصوير الرقمي والمسح داخل الفم. وتصمّمان معاً ابتسامتك المثالية — اللون والشكل والطول. ويعرض لك برنامج التصميم الرقمي للابتسامة النتيجة النهائية قبل أي تحضير للسن.',
		'The procedure is performed under local anesthesia or IV sedation — no pain during surgery. Post-op discomfort (soreness, swelling) peaks at 48 hours and is managed with prescribed pain medication. Most patients describe it as less painful than a tooth extraction.' => 'يُجرى العمل تحت تخدير موضعي أو تركين وريدي — بلا ألم أثناء الجراحة. أمّا الانزعاج بعدها (وجع وتورّم) فيبلغ ذروته بعد 48 ساعة ويُضبط بالمسكّنات الموصوفة. ويصفه معظم المرضى بأنه أقل ألماً من خلع سنّ.',
		'The procedure is performed under local anesthesia or sedation — no pain during surgery. Post-op discomfort (mild swelling, pressure) is managed with prescribed medication and typically resolves within a week. Most patients report less discomfort than anticipated.' => 'يُجرى العمل تحت تخدير موضعي أو تركين — بلا ألم أثناء الجراحة. أمّا الانزعاج بعدها (تورّم خفيف وإحساس بالضغط) فيُضبط بالأدوية الموصوفة ويزول عادةً خلال أسبوع. ويصفه معظم المرضى بأنه أقل ممّا توقّعوا.',
		'Yes. After full healing (4–6 months), you can eat all foods without restriction — including steak, nuts, and apples. Chewing power is restored to 90–95% of natural teeth. Avoid extremely hard objects like ice or hard candy to prevent chipping the porcelain teeth.' => 'نعم. بعد اكتمال الالتئام (4–6 أشهر) يمكنك أن تأكل كل شيء بلا قيد — اللحم والمكسّرات والتفاح. وتعود قوة المضغ إلى 90–95٪ من قوة الأسنان الطبيعية. وتجنّب فقط الأشياء القاسية جداً كالثلج أو الحلوى الصلبة كي لا تتشظّى الأسنان الخزفية.',
		'Yes. After the temporary filling (first visit), stick to soft foods on the opposite side. Once the permanent inlay/onlay is bonded (second visit), you can resume normal eating within 24 hours. Avoid extremely hard foods like ice or hard candy to prevent chipping.' => 'نعم. بعد الحشوة المؤقتة (الزيارة الأولى) اقتصر على الأطعمة الطرية من الجهة الأخرى. وبعد لصق الحشوة الدائمة (الزيارة الثانية) يمكنك العودة إلى الأكل المعتاد خلال 24 ساعة. وتجنّب الأطعمة القاسية جداً كالثلج أو الحلوى الصلبة تفادياً للتشظّي.',
		'Complete smile restoration with All-on-4 or All-on-6 implant techniques. Replace an entire arch with just 4–6 strategically placed implants. Straumann & Nobel Biocare brands. Fixed, functional teeth in one visit. VeaHealth coordinates your complete transformation.' => 'تعويض كامل للابتسامة بتقنيتَي All-on-4 أو All-on-6. فكّ كامل يُعوَّض بـ4 إلى 6 غرسات موضوعة في المواضع الأهم. ماركتا Straumann وNobel Biocare. أسنان ثابتة وعاملة في زيارة واحدة. وتنسّق VeaHealth تحوّلك كاملاً.',
		'Rebuild jawbone volume with advanced bone grafting techniques. 1cc premium graft material — autogenous, xenograft, or alloplastic options. Essential preparation for successful dental implant placement. VeaHealth coordinates your complete bone regeneration journey.' => 'إعادة بناء حجم عظم الفك بتقنيات ترقيع متقدّمة. 1 سم³ من مادة ترقيع من الفئة الأولى — من عظمك أنت، أو من مصدر حيواني، أو صناعية. وهو التحضير اللازم لنجاح زراعة الأسنان. وتنسّق VeaHealth رحلة تجديد العظم كاملةً.',
		'Yes. VeaHealth’s lifetime warranty on implants and 5-year warranty on the hybrid zirconium prosthesis are valid worldwide. If a warranty issue arises after you return home, VeaHealth coordinates resolution remotely or via a local affiliated clinic in your country.' => 'نعم. ضمان VeaHealth مدى الحياة على الغرسات وضمان 5 سنوات على التركيبة الهجينة من الزيركون ساريان في كل أنحاء العالم. وإذا ظهرت مشكلة مشمولة بالضمان بعد عودتك، تتولّى VeaHealth حلّها عن بُعد أو عبر عيادة شريكة في بلدك.',
		'A fixed temporary bridge is attached on the same day — or within 24 hours — of implant placement. You leave the clinic with functional, aesthetic teeth. This immediate loading protocol restores confidence instantly while osseointegration begins beneath the surface.' => 'يُثبَّت جسر مؤقت ثابت في اليوم نفسه — أو خلال 24 ساعة — من وضع الغرسات. فتغادر العيادة بأسنان عاملة وجميلة. وهذا البروتوكول ذو التحميل الفوري يعيد الثقة على الفور، بينما يبدأ الاندماج العظمي تحت السطح.',
		'VeaHealth exclusively uses Straumann and Nobel Biocare implants — the two most researched and validated brands globally. The specific brand, model, and serial numbers are documented in your treatment file and provided at completion. This is a contractual guarantee.' => 'لا تستعمل VeaHealth سوى غرسات Straumann وNobel Biocare — وهما أكثر ماركتين بحثاً وتوثيقاً في العالم. وتُدوَّن الماركة والطراز والأرقام التسلسلية في ملفّ علاجك وتُسلَّم لك عند انتهائه. وهذا التزام تعاقدي.',
		'VeaHealth exclusively uses Straumann and Nobel Biocare zygomatic implants — the two brands with the most clinical validation for this advanced technique. The specific brand, model, and serial numbers are documented in your treatment file and provided at completion.' => 'لا تستعمل VeaHealth سوى غرسات Straumann وNobel Biocare الوجنية — وهما الماركتان الأكثر دعماً بالأدلّة السريرية في هذه التقنية المتقدّمة. وتُدوَّن الماركة والطراز والأرقام التسلسلية في ملفّ علاجك وتُسلَّم لك عند انتهائه.',
		'Yes. VeaHealth’s 5-year warranty on inlays and onlays is valid worldwide. If a restoration fails due to defect or bonding failure, VeaHealth coordinates repair or replacement — either remotely via a partner clinic in your country or with a return visit to Istanbul.' => 'نعم. ضمان VeaHealth لمدّة 5 سنوات على حشوات الإنلاي والأونلاي ساري المفعول في كل أنحاء العالم. وإذا فشل التعويض بسبب عيب أو انفكاك اللصق، تنسّق VeaHealth الإصلاح أو الاستبدال — إمّا عن بُعد عبر عيادة شريكة في بلدك، أو بزيارة عودة إلى إسطنبول.',
		'Yes. VeaHealth’s lifetime warranty on zygomatic implants and 3-year warranty on prosthetics are valid worldwide. If a warranty issue arises after you return home, VeaHealth coordinates resolution remotely or via a local affiliated specialist clinic in your country.' => 'نعم. ضمان VeaHealth مدى الحياة على الغرسات الوجنية وضمان 3 سنوات على التعويض ساريان في كل أنحاء العالم. وإذا ظهرت مشكلة مشمولة بالضمان بعد عودتك، تتولّى VeaHealth حلّها عن بُعد أو عبر عيادة متخصّصة شريكة في بلدك.',
		'Direct Hair Implantation using the Choi Implanter Pen — extract and implant in single motion. No channel pre-opening, maximum control over angle & depth. Minimal bleeding, faster healing. 3500–4500 grafts per session. VeaHealth coordinates your complete DHI journey.' => 'الزراعة المباشرة للشعر بقلم تشوي: اقتطاف وزرع في حركة واحدة. لا فتح مسبق للقنوات، وتحكّم كامل في الزاوية والعمق. نزف ضئيل والتئام أسرع. من 3500 إلى 4500 طُعم في الجلسة. وتنسّق VeaHealth رحلتك كاملةً.',
		'Yes. VeaHealth’s graft warranty covers surgical complications and graft failure within 6 months of placement. Full documentation is provided. If a warranty issue arises after you return home, VeaHealth coordinates resolution remotely or via a local affiliated clinic.' => 'نعم. يغطّي ضمان VeaHealth للترقيع المضاعفات الجراحية وفشل الطُعم خلال 6 أشهر من وضعه. وتُسلَّم لك الوثائق كاملةً. وإذا ظهرت مشكلة مشمولة بالضمان بعد عودتك، تتولّى VeaHealth حلّها عن بُعد أو عبر عيادة شريكة قريبة منك.',
		'Advanced solution for severe upper jaw bone loss. Specialized long implants anchored in the cheekbone (zygoma) eliminate the need for bone grafting. Same-day temporary teeth. Straumann & Nobel Biocare brands. VeaHealth coordinates your complete advanced implant journey.' => 'حلّ متقدّم لحالات الفقد العظمي الشديد في الفك العلوي. غرسات طويلة مخصَّصة تُثبَّت في عظم الوجنة (الزيجوما) فتُغني عن الترقيع العظمي. أسنان مؤقتة في اليوم نفسه. ماركتا Straumann وNobel Biocare. وتنسّق VeaHealth رحلة الزراعة المتقدّمة كاملةً.',
		'CAD/CAM software is used to virtually position all 4 implants, simulating the ideal angulation and depth. The titanium bar and prosthetic arch are designed digitally. Bite function, aesthetics, and bone engagement are all optimized before a single drill touches the jaw.' => 'يُستعمل برنامج CAD/CAM لتحديد مواضع الغرسات الأربع افتراضياً، بمحاكاة الميل والعمق المثاليين. ويُصمَّم قضيب التيتانيوم والقوس التعويضي رقمياً. ويُضبط الإطباق والمظهر والتثبيت في العظم قبل أن يلمس أي مِثقب الفك.',
		'The procedure is performed under local anesthesia — you’ll feel pressure but no pain during tooth preparation. Post-procedure, mild sensitivity to hot/cold is normal for 24–72 hours and resolves with over-the-counter pain relief. Most patients report minimal discomfort.' => 'يُجرى العمل تحت تخدير موضعي — فتشعر بالضغط دون ألم أثناء تحضير السن. وبعد ذلك، الحساسية الخفيفة للبارد والساخن أمر طبيعي لمدّة 24 إلى 72 ساعة وتزول بمسكّن عادي. ويصف معظم المرضى الانزعاج بأنه ضئيل.',
		'The titanium implants can last a lifetime with proper care — studies confirm 97%+ survival at 10 years. The zirconia prosthesis may need replacement after 15–20 years due to wear. Biannual professional cleanings and good oral hygiene are essential for long-term success.' => 'قد تدوم غرسات التيتانيوم مدى الحياة مع عناية سليمة — إذ تؤكّد الدراسات بقاءً يفوق 97٪ بعد 10 سنوات. أمّا تعويض الزيركون فقد يحتاج إلى تبديل بعد 15–20 سنة بسبب التآكل. والتنظيف الاحترافي مرتين سنوياً ونظافة الفم الجيدة أساسيان لنجاح طويل الأمد.',
		'Bone graft maturation takes 4–9 months depending on graft material and volume. Lateral window sinus lifts typically require 6–9 months before implant placement. Crestal sinus lifts heal faster (4–6 months) because implants are placed simultaneously with less graft volume.' => 'يستغرق نضج الطُعم من 4 إلى 9 أشهر حسب المادة والحجم. ويتطلّب الرفع عبر النافذة الجانبية عادةً 6 إلى 9 أشهر قبل وضع الغرسات. أمّا الرفع من قمة الحافة فيلتئم أسرع (4 إلى 6 أشهر) لأن الغرسات تُوضع في الوقت نفسه وبكمية ترقيع أقل.',
		'Single-hair grafts placed one at a time to rebuild eyebrows lost to over-plucking, scarring, alopecia or age. It is the most exacting work in hair restoration: a few hundred grafts, every one placed individually, at angles so shallow the hair lies almost against the skin.' => 'طُعوم بشعرة واحدة تُوضع واحدةً واحدة لإعادة بناء حواجب فُقدت بالنتف الزائد أو بالندوب أو الثعلبة أو التقدّم في السنّ. وهو أدقّ عمل في استعادة الشعر: بضع مئات من الطُعوم، كل واحد يُوضع على حدة، بزوايا شديدة الانخفاض حتى تكاد الشعرة تستلقي على الجلد.',
		'Yes. After full healing (4–6 months), you can eat all foods without restriction — including steak, nuts, apples, and corn on the cob. Chewing power is restored to 95–98% of natural teeth. The two extra implants provide even greater stability than All-on-4 for tough foods.' => 'نعم. بعد اكتمال الالتئام (4–6 أشهر) يمكنك أن تأكل كل شيء بلا قيد — اللحم والمكسّرات والتفاح والذرة. وتعود قوة المضغ إلى 95–98٪ من قوة الأسنان الطبيعية. والغرستان الإضافيتان تمنحان ثباتاً أعلى من All-on-4 أمام الأطعمة الصلبة.',
		'Yes. VeaHealth’s warranties cover implant fixtures and prosthetic components and are honored internationally. Documentation is provided at treatment completion, and the warranty remains valid even after you return to your home country — with remote coordination available.' => 'نعم. تغطّي ضمانات VeaHealth الغرسات والأجزاء التعويضية، وهي معتمَدة دولياً. وتُسلَّم لك الوثائق عند انتهاء العلاج، ويبقى الضمان سارياً بعد عودتك إلى بلدك — مع تنسيق عن بُعد متاح لك.',
		'The titanium fixtures can last a lifetime with proper care — studies confirm 95%+ survival at 10 years and documented cases exceeding 20 years. The zirconia prosthesis may need replacement after 15–20 years due to wear. Biannual check-ups are essential for long-term success.' => 'قد تدوم غرسات التيتانيوم مدى الحياة مع عناية سليمة — إذ تؤكّد الدراسات بقاءً يفوق 95٪ بعد 10 سنوات، وهناك حالات موثَّقة تجاوزت 20 سنة. أمّا تعويض الزيركون فقد يحتاج إلى تبديل بعد 15–20 سنة بسبب التآكل. والفحوصات نصف السنوية أساسية لنجاح طويل الأمد.',
		'VeaHealth uses exclusively Straumann and Nobel Biocare implants — the two most clinically validated brands globally. The brand, model, and batch number are confirmed in your treatment plan and documented at placement. This is a contractual guarantee, not a marketing promise.' => 'لا تستعمل VeaHealth سوى غرسات Straumann وNobel Biocare — وهما أكثر ماركتين مدعومتين بالأدلّة السريرية في العالم. وتُذكر الماركة والطراز ورقم التشغيلة في خطة علاجك وتُوثَّق عند وضع الغرسة. وهذا التزام تعاقدي، لا وعد تسويقي.',
		'Porcelain offers superior aesthetics and is ideal for visible teeth (premolars, upper molars). Zirconia is stronger and better for back molars that endure heavy chewing forces. VeaHealth’s dentists will recommend the optimal material based on the tooth location and your bite.' => 'يمنح الخزف مظهراً أجمل وهو الأنسب للأسنان الظاهرة (الضواحك والأرحاء العلوية). أمّا الزيركون فأقوى وأفضل للأرحاء الخلفية التي تتحمّل قوى مضغ عالية. ويوصي أطباء VeaHealth بالمادة الأنسب حسب موضع السن وإطباقك.',
		'Premium zirconia-acrylic hybrid restoration on dental implants. Combines superior strength of zirconia teeth with comfortable acrylic gum base for maximum durability and natural aesthetics. Implant-supported, fixed solution. VeaHealth coordinates your complete transformation.' => 'تعويض هجين من الزيركون والأكريل من الفئة الأولى على غرسات الأسنان. يجمع بين متانة أسنان الزيركون الفائقة وراحة قاعدة اللثة الأكريلية، فيعطي أقصى دوام ومظهراً طبيعياً. حلّ ثابت محمول على الغرسات. وتنسّق VeaHealth تحوّلك كاملاً.',
		'Yes, but timing matters. If you currently have braces, wait until they’re removed — your bite is changing too frequently. With implants, crowns, or bridges, a custom guard is essential to protect your investment. VeaHealth’s dentists design guards around existing restorations.' => 'نعم، لكن التوقيت مهم. فإن كنت تضع تقويماً حالياً، فانتظر إلى أن يُنزع — لأن إطباقك يتغيّر باستمرار. أمّا مع الغرسات أو التلبيسات أو الجسور، فالواقي المفصَّل ضروري لحماية ما أنفقته. ويصمّم أطباء VeaHealth الواقي حول التعويضات الموجودة.',
		'Lower operating costs (lab fees, rent, staff salaries) in Turkey allow VeaHealth to offer the same premium materials and techniques at 60–70% less than UK/US prices. The quality is identical — same porcelain and zirconia brands, same CAD/CAM technology, same clinical standards.' => 'انخفاض تكاليف التشغيل في تركيا — أتعاب المختبرات والإيجار والأجور — يتيح لـVeaHealth تقديم المواد والتقنيات نفسها من الفئة الأولى بأقل من أسعار بريطانيا وأمريكا بنسبة 60–70٪. والجودة مطابقة: نفس ماركات الخزف والزيركون، ونفس تقنية CAD/CAM، ونفس المعايير السريرية.',
		'The titanium implants themselves typically last 15–20+ years with proper care. The zirconia prosthesis is highly durable and may last the same timeframe, while acrylic bridges may require replacement after 10–12 years. Clinical studies confirm >93% implant survival at 18 years.' => 'تدوم غرسات التيتانيوم نفسها عادةً 15 إلى 20 سنة فأكثر مع عناية سليمة. وتعويض الزيركون شديد المتانة وقد يدوم المدّة نفسها، أمّا الجسور الأكريلية فقد تحتاج إلى تبديل بعد 10 إلى 12 سنة. وتؤكّد الدراسات السريرية بقاء الغرسات بنسبة تفوق 93٪ بعد 18 سنة.',
		'Four titanium implants are surgically placed under local anesthesia or IV sedation. The 2 anterior fixtures are vertical; the 2 posterior ones are tilted at 45° to maximize engagement with available bone volume — avoiding sinus anatomy entirely. Surgery takes 2–4 hours per arch.' => 'تُوضع أربع غرسات تيتانيوم تحت تخدير موضعي أو تركين وريدي. الغرستان الأماميتان عموديتان، والخلفيتان مائلتان بزاوية 45° لاستغلال حجم العظم المتاح إلى أقصى حد — مع تفادي الجيوب الأنفية تماماً. وتستغرق الجراحة 2 إلى 4 ساعات لكل فك.',
		'True graft rejection is extremely rare (< 2%) with modern materials. Most "failures" are due to infection, smoking, or inadequate blood supply — not immune rejection. Bio-Oss and other xenografts are processed to remove all antigenic proteins, making rejection nearly impossible.' => 'الرفض الحقيقي للطُعم نادر جداً (أقل من 2٪) مع المواد الحديثة. فمعظم «حالات الفشل» سببها التهاب أو تدخين أو ضعف في التروية الدموية — لا رفض مناعي. ومواد مثل Bio-Oss وغيرها من الطُعوم الحيوانية تُعالَج لإزالة كل البروتينات المولِّدة للمناعة، فيصبح الرفض شبه مستحيل.',
		'In some cases, yes — if the defect is small (< 2mm) and the implant achieves good primary stability. However, larger defects require staged treatment: graft first, wait 4–6 months for healing, then place the implant. VeaHealth\'s surgeons assess this during pre-treatment planning.' => 'في بعض الحالات نعم — إذا كان العيب صغيراً (أقل من 2 مم) وحقّقت الغرسة ثباتاً ابتدائياً جيداً. أمّا العيوب الأكبر فتستدعي علاجاً على مرحلتين: الترقيع أولاً، ثم انتظار 4 إلى 6 أشهر للالتئام، ثم وضع الغرسة. ويحسم جرّاحو VeaHealth هذا الأمر أثناء التخطيط قبل العلاج.',
		'Yes — immediate implant placement is possible when the extraction socket has sufficient bone volume and no active infection. This reduces overall treatment time and preserves the natural socket architecture. VeaHealth’s surgeons assess eligibility during the 3D scan consultation.' => 'نعم — الزراعة الفورية ممكنة عندما يكون في سِنخ الخلع حجم عظم كافٍ ولا يوجد التهاب نشط. وهذا يقصّر مدّة العلاج ويحافظ على بنية السِنخ الطبيعية. ويقيّم جرّاحو VeaHealth الأهلية أثناء استشارة الأشعة ثلاثية الأبعاد.',
		'Yes — this is one of the major advantages. If a porcelain tooth chips or fractures, it can often be repaired chair-side without removing the entire prosthesis. The acrylic base allows for easy bonding and modification. Full zirconia, by contrast, requires lab work for any repair.' => 'نعم — بل هذه من أبرز مزاياها. فإذا تشظّت سنّ خزفية أو انكسرت، يمكن إصلاحها غالباً على كرسي العيادة دون نزع التركيبة كلّها. فالقاعدة الأكريلية تقبل اللصق والتعديل بسهولة. أمّا الزيركون الكامل فيتطلّب عملاً في المختبر لأي إصلاح.',
		'Yes. Zirconia implants are available as a metal-free alternative for patients with confirmed titanium hypersensitivity. Zirconia offers excellent biocompatibility and strength while eliminating metal contact entirely. VeaHealth assesses allergy status during initial consultation.' => 'نعم. تتوفّر غرسات الزيركون كبديل خالٍ من المعادن للمرضى الذين ثبتت لديهم حساسية من التيتانيوم. والزيركون ممتاز في توافقه الحيوي ومتين، ويلغي أي تماس مع المعدن. وتقيّم VeaHealth حالة الحساسية في الاستشارة الأولى.',
		'The titanium implants can last a lifetime with proper care — studies confirm 95%+ survival at 10 years and 20+ year longevity is common. The zirconia prosthesis may need replacement after 15–20 years due to wear. Biannual professional cleanings are essential for long-term success.' => 'قد تدوم غرسات التيتانيوم مدى الحياة مع عناية سليمة — إذ تؤكّد الدراسات بقاءً يفوق 95٪ بعد 10 سنوات، وعمراً يتجاوز 20 سنة في حالات كثيرة. أمّا تعويض الزيركون فقد يحتاج إلى تبديل بعد 15–20 سنة بسبب التآكل. والتنظيف الاحترافي مرتين في السنة أساسي لنجاح طويل الأمد.',
		'Two visits: the first for sinus lift surgery (3–5 days in Istanbul), and a second visit 6–9 months later for implant placement (5–7 days). The entire graft healing phase is monitored remotely by VeaHealth with CBCT scans at 3 and 6 months — no travel required during consolidation.' => 'زيارتان: الأولى لجراحة رفع الجيب (3–5 أيام في إسطنبول)، والثانية بعد 6 إلى 9 أشهر لوضع الغرسات (5–7 أيام). أمّا مرحلة التئام الطُعم كاملةً فتتابعها VeaHealth عن بُعد بأشعة CBCT في الشهر الثالث والسادس — دون حاجة إلى أي سفر أثناء التماسك.',
		'An oxygen-assisted protocol offered after hair transplantation, aimed at the comfort of the first few days — swelling, crusting and the feel of the donor area. It is an adjunct to aftercare. It is not a treatment for hair loss and it does not change how many of your grafts survive.' => 'بروتوكول مدعوم بالأكسجين يُقدَّم بعد زراعة الشعر، غرضه راحة الأيام الأولى — التورّم، والقشور، وإحساس المنطقة المانحة. وهو مكمّل للعناية بعد العملية. وليس علاجاً لتساقط الشعر، ولا يغيّر عدد الطُعوم التي تبقى حيّة.',
		'Standard protocol requires 7–10 days total. First appointment for preparation and scan, then a 5–7 day wait while the lab fabricates your restoration, then the second appointment for permanent bonding. VeaHealth can arrange hotel accommodations and sightseeing tours during the wait.' => 'يتطلّب البروتوكول المعتاد 7 إلى 10 أيام إجمالاً. موعد أول للتحضير وأخذ المسح، ثم انتظار 5 إلى 7 أيام ريثما يصنع المختبر تعويضك، ثم الموعد الثاني للّصق النهائي. ويمكن لـVeaHealth ترتيب الفندق وجولات سياحية خلال فترة الانتظار.',
		'Typically one 4–5 day visit. Day 1: consultation and tooth prep. Days 2–4: lab fabrication. Day 5: final placement. If you need multiple crowns or additional treatments, the timeline extends but remains efficient. VeaHealth coordinates everything to minimize your time away from home.' => 'عادةً زيارة واحدة من 4 إلى 5 أيام. اليوم 1: الاستشارة وتحضير السن. الأيام 2–4: التصنيع في المختبر. اليوم 5: التركيب النهائي. وإذا احتجت تلبيسات متعدّدة أو علاجات إضافية، يمتدّ الجدول لكنه يبقى مضبوطاً. وتنسّق VeaHealth كل شيء لتقليل وقتك بعيداً عن بيتك.',
		'Smokers can receive grafts, but tobacco significantly reduces success rates by impairing healing and blood flow. VeaHealth strongly recommends stopping smoking at least 4 weeks before and 6 months after surgery. Compliance with smoking cessation measurably improves graft incorporation.' => 'يمكن للمدخّن أن يُرقَّع، لكن التبغ يخفّض نِسب النجاح بوضوح لأنه يضعف الالتئام وتدفّق الدم. وتنصح VeaHealth بشدّة بالتوقّف عن التدخين 4 أسابيع على الأقل قبل الجراحة و6 أشهر بعدها. والالتزام بذلك يحسّن اندماج الطُعم تحسّناً ملموساً.',
		'Smokers can receive implants, but tobacco significantly reduces success rates by impairing healing and osseointegration. VeaHealth strongly recommends stopping smoking at least 4–6 weeks before and 3–6 months after surgery. Compliance with smoking cessation measurably improves outcomes.' => 'يمكن للمدخّن أن يزرع، لكن التبغ يخفّض نِسب النجاح بوضوح لأنه يضعف الالتئام والاندماج العظمي. وتنصح VeaHealth بشدّة بالتوقّف عن التدخين 4 إلى 6 أسابيع على الأقل قبل الجراحة و3 إلى 6 أشهر بعدها. والالتزام بذلك يحسّن النتيجة تحسّناً ملموساً.',
		'Once full osseointegration is confirmed, you return to Istanbul for your definitive restoration. A custom-milled zirconia or high-grade acrylic bridge — fabricated to match your natural tooth shade, bite alignment, and facial aesthetics — is permanently secured. This is your final smile.' => 'بعد تأكّد الاندماج العظمي الكامل، تعود إلى إسطنبول للتعويض النهائي. ويُثبَّت بشكل دائم جسر زيركون مخرَّط حسب المقاس أو جسر أكريلي عالي الجودة — مصنوع ليطابق لون أسنانك الطبيعي وإطباقك وملامح وجهك. وهذه هي ابتسامتك النهائية.',
		'Minimal to none. E-max Lumineers are ultra-thin (0.2–0.5mm) and often require zero enamel removal. In cases where slight preparation is needed, it’s limited to surface etching only — preserving your natural tooth structure almost entirely. This makes the procedure reversible in many cases.' => 'قليل جداً أو معدوم. فقشور E-max فائقة الرقّة (0.2–0.5 مم) ولا تتطلّب في الغالب إزالة أي مينا. وحين يلزم تحضير طفيف، فهو مقصور على تخشين السطح — فتبقى بنية سنّك الطبيعية سليمة تقريباً. ولهذا يكون الإجراء قابلاً للتراجع عنه في حالات كثيرة.',
		'15–20+ years with proper care. E-max lithium disilicate ceramic is 4× stronger than traditional porcelain, resulting in excellent long-term survival rates. Studies confirm 95%+ survival at 10 years. With good oral hygiene and biannual cleanings, many patients keep their veneers for decades.' => '15 إلى 20 سنة فأكثر مع عناية سليمة. فخزف E-max من ثنائي سيليكات الليثيوم أقوى أربع مرات من الخزف التقليدي، ومن هنا معدّلات البقاء الممتازة. وتؤكّد الدراسات بقاءً يفوق 95٪ بعد 10 سنوات. ومع نظافة فم جيدة وتنظيف احترافي مرتين سنوياً، يحتفظ كثير من المرضى بقشورهم عقوداً.',
		'No. E-max ceramic is non-porous and highly resistant to staining from coffee, wine, tea, and tobacco. The glazed surface remains bright indefinitely with normal brushing. Unlike natural enamel or composite veneers, E-max maintains its original shade permanently without whitening treatments.' => 'لا. خزف E-max غير مسامي وشديد المقاومة لتصبّغات القهوة والنبيذ والشاي والتبغ. ويبقى سطحه المزجَّج لامعاً بلا حدّ زمني مع التفريش المعتاد. وبخلاف المينا الطبيعية أو قشور الكومبوزيت، يحتفظ E-max بلونه الأصلي دائماً دون أي تبييض.',
		'With proper care, hybrid prostheses last 10–15 years on average. The porcelain teeth are highly durable and stain-resistant. The acrylic gum base may require professional polishing every 2–3 years to maintain shine. Eventually, the entire prosthesis will need replacement due to normal wear.' => 'مع عناية سليمة، تدوم التركيبة الهجينة 10 إلى 15 سنة في المتوسط. فالأسنان الخزفية شديدة المتانة ولا تتصبّغ. وقد تحتاج قاعدة اللثة الأكريلية تلميعاً احترافياً كل 2 إلى 3 سنوات للحفاظ على لمعانها. وفي النهاية سيفرض التآكل المعتاد تبديل التركيبة كلّها.',
		'A single failure rarely destabilizes the full arch — the remaining 3 implants maintain function. The failed fixture is removed, and options include bone grafting with replacement or switching to an All-on-6 configuration for added redundancy. Early detection through regular follow-ups is key.' => 'نادراً ما يزعزع فشل غرسة واحدة الفك كلّه — فالغرسات الثلاث الباقية تحافظ على الوظيفة. وتُزال الغرسة الفاشلة، ومن الخيارات بعدها ترقيع العظم ثم استبدالها، أو الانتقال إلى ترتيب All-on-6 لهامش أمان أكبر. والأهم هو الاكتشاف المبكر عبر المتابعة المنتظمة.',
		'Female hair loss is usually diffuse rather than patterned, which changes what a transplant can do and who it suits. The first step is not surgery — it is finding out why the hair is thinning, because a good proportion of female hair loss has a cause that treatment reverses without an operation.' => 'تساقط الشعر عند النساء منتشر في الغالب لا نمطي، وهذا يغيّر ما تستطيعه الزراعة ولمن تصلح. والخطوة الأولى ليست الجراحة، بل معرفة لماذا يخفّ الشعر، لأن جزءاً كبيراً من تساقط الشعر عند النساء له سبب يعكسه العلاج دون عملية.',
		'The titanium implants gradually fuse with the jawbone. VeaHealth provides a structured remote aftercare protocol: digital check-ins, photo assessments, and direct access to your treatment coordinator from your home country. Any concerns are addressed promptly without requiring immediate travel.' => 'تلتحم غرسات التيتانيوم بعظم الفك تدريجياً. وتوفّر VeaHealth بروتوكول متابعة منظَّماً عن بُعد: مراجعات رقمية، وتقييماً بالصور، وتواصلاً مباشراً مع منسّق علاجك من بلدك. وتُعالَج أي مخاوف بسرعة دون الحاجة إلى سفر فوري.',
		'Yes. Zygomatic implants have been used since 1998 with well-documented safety profiles. The procedure is more complex than conventional implants and requires a specialized surgeon, but serious complications are rare (<2%). Mild, self-limiting sinusitis is the most common issue (10.5% of cases).' => 'نعم. تُستعمل الغرسات الوجنية منذ سنة 1998 وسجلّ أمانها موثَّق جيداً. والعملية أعقد من الزراعة التقليدية وتحتاج جرّاحاً متخصّصاً، لكن المضاعفات الخطيرة نادرة (أقل من 2٪). وأكثر ما يحدث هو التهاب جيوب خفيف يزول وحده (في 10.5٪ من الحالات).',
		'Mild, temporary sinusitis occurs in ~10% of patients and resolves with antibiotics and decongestants within 2–4 weeks. The implants traverse the sinus but don’t cause chronic sinus issues. Serious complications like sinus perforation or chronic infection are rare (<2%) with experienced surgeons.' => 'يحدث التهاب جيوب خفيف وعابر لدى نحو 10٪ من المرضى ويزول بالمضادات الحيوية ومزيلات الاحتقان خلال أسبوعين إلى أربعة. فالغرسات تعبر الجيب لكنها لا تسبّب مشاكل جيوب مزمنة. أمّا المضاعفات الخطيرة كثقب الجيب أو الالتهاب المزمن فنادرة (أقل من 2٪) مع جرّاح ذي خبرة.',
		'Yes, if ≥5mm of existing bone remains. This is called simultaneous placement. The implant is placed into the residual bone, and the sinus lift adds height around it. If <4mm bone exists, a staged approach is recommended: sinus lift first, implants 6–9 months later once the graft has consolidated.' => 'نعم، إذا بقي 5 مم من العظم على الأقل. ويُسمّى هذا الوضع المتزامن: تُثبَّت الغرسة في العظم المتبقّي، ويضيف رفع الجيب ارتفاعاً حولها. أمّا إذا قلّ العظم عن 4 مم، فيُنصح بالنهج على مرحلتين: رفع الجيب أولاً، ثم الغرسات بعد 6 إلى 9 أشهر متى تماسك الطُعم.',
		'Sinus lift surgery has a >95% success rate when performed by experienced oral surgeons. Implants placed in grafted sinus bone achieve 95–98% survival at 10 years — statistically identical to implants in native bone. The most critical factor is allowing adequate healing time before implant loading.' => 'تبلغ نسبة نجاح رفع الجيب أكثر من 95٪ حين يُجريه جرّاح فم ذو خبرة. وتحقّق الغرسات الموضوعة في عظم الجيب المرقَّع بقاءً بين 95 و98٪ بعد 10 سنوات — وهو مطابق إحصائياً للغرسات في العظم الأصلي. والعامل الأهم هو إعطاء الالتئام وقته الكافي قبل تحميل الغرسة.',
		'The All-on-4/6 technique is specifically designed for patients with bone loss. Angled posterior implants avoid areas of deficiency and maximize contact with available bone. In 90% of cases, no bone grafting is needed. If grafting is required, VeaHealth identifies this during pre-treatment planning.' => 'صُمّمت تقنية All-on-4/6 خصيصاً للمرضى الذين فقدوا عظماً. فالغرسات الخلفية المائلة تتجنّب المناطق الضعيفة وتستفيد إلى أقصى حدّ من العظم المتاح. وفي 90٪ من الحالات لا يلزم ترقيع عظمي. وإذا لزم، تحدّده VeaHealth أثناء التخطيط قبل العلاج.',
		'Follicular units moved from the back of the scalp into the beard, moustache or the gaps left by scarring. The technique is FUE; what makes it beard work rather than scalp work is the angle — facial hair leaves the skin almost flat, and grafts placed at scalp angles look wrong however well they grow.' => 'وحدات جُريبية تُنقل من مؤخّرة فروة الرأس إلى اللحية أو الشارب أو الفراغات التي تركتها الندوب. والتقنية هي FUE؛ أمّا ما يجعله عمل لحية لا عمل فروة رأس فهو الزاوية — إذ يخرج شعر الوجه من الجلد شبه مسطَّح، والطُعوم الموضوعة بزوايا فروة الرأس تبدو خاطئة مهما نمت جيداً.',
		'The procedure is performed under IV sedation or general anesthesia — you feel nothing during surgery. Post-op discomfort (swelling, soreness) peaks at 48 hours and is managed with prescribed pain medication and cold compresses. Most patients describe it as less painful than a single tooth extraction.' => 'يُجرى العمل تحت تركين وريدي أو تخدير عام — فلا تشعر بشيء أثناء الجراحة. أمّا الانزعاج بعدها (تورّم ووجع) فيبلغ ذروته بعد 48 ساعة ويُضبط بالمسكّنات الموصوفة والكمّادات الباردة. ويصفه معظم المرضى بأنه أقل ألماً من خلع سنّ واحدة.',
		'Follicular units taken one at a time with a hand-held punch rather than a motorised drill. It is slower than motorised FUE and takes fewer grafts in a session — which is the trade being made, because the surgeon feels the resistance of every follicle and follows its angle instead of cutting across it.' => 'تُؤخذ الوحدات الجُريبية واحدةً واحدة بأداة تُمسك باليد لا بمِثقب آلي. وهذا أبطأ من تقنية FUE الآلية ويعطي طُعوماً أقل في الجلسة — وهذه هي المقايضة، لأن الجرّاح يحسّ مقاومة كل جُريب فيتبع زاويته بدل أن يقطعه عرضاً.',
		'The procedure is performed under general anesthesia — you feel nothing during surgery. Post-op discomfort (swelling, nasal congestion, soreness) is more significant than conventional implants and peaks at 72 hours. Pain is managed with prescription medications and typically resolves within 10–14 days.' => 'يُجرى العمل تحت تخدير عام — فلا تشعر بشيء أثناء الجراحة. أمّا الانزعاج بعدها (تورّم واحتقان أنفي ووجع) فأشدّ منه في الغرسات التقليدية ويبلغ ذروته بعد 72 ساعة. ويُضبط الألم بالأدوية الموصوفة ويزول عادةً خلال 10 إلى 14 يوماً.',
		'Most men and women with pattern hair loss are candidates. Requirements: sufficient donor area density, realistic expectations, good general health. Not suitable for: diffuse unpatterned alopecia, alopecia areata, active scalp infections. VeaHealth provides free eligibility assessment via photo analysis.' => 'معظم الرجال والنساء المصابين بالصلع النمطي مرشَّحون. والشروط: كثافة كافية في المنطقة المانحة، وتوقّعات واقعية، وصحة عامة جيدة. أمّا غير المناسبين فهم: أصحاب الثعلبة المنتشرة غير النمطية، والثعلبة البقعية، والتهابات فروة الرأس النشطة. وتقدّم VeaHealth تقييماً مجانياً للأهلية عبر تحليل الصور.',
		'A sinus lift (maxillary sinus augmentation) is a surgical procedure that adds bone to the upper jaw beneath the sinus cavity. It’s needed when there is insufficient bone height to place dental implants in the posterior upper jaw — typically after tooth loss causes bone resorption and sinus floor descent.' => 'رفع الجيب الفكّي (تعزيز الجيب الفكّي العلوي) عملية جراحية تضيف عظماً إلى الفك العلوي تحت تجويف الجيب. وتلزم حين لا يكفي ارتفاع العظم لوضع غرسات في المنطقة الخلفية من الفك العلوي — وذلك غالباً بعد أن يؤدّي فقدان الأسنان إلى امتصاص العظم وهبوط قاع الجيب.',
		'Most patients choose 6–10 veneers for the upper front teeth (the “smile zone”). Lower teeth may also be treated if desired. The exact number depends on your smile design goals, tooth proportions, and how many teeth show when you smile. VeaHealth helps you determine the optimal number during consultation.' => 'يختار معظم المرضى من 6 إلى 10 قشور للأسنان الأمامية العلوية (منطقة الابتسامة). ويمكن علاج الأسنان السفلية أيضاً إن رغبت. ويتوقّف العدد الدقيق على ما تريد بلوغه، وعلى نِسب أسنانك، وعلى عدد الأسنان الظاهرة حين تبتسم. وتساعدك VeaHealth على تحديد العدد الأمثل في الاستشارة.',
		'Smokers can receive implants, but tobacco significantly reduces success rates by impairing blood flow and healing. VeaHealth strongly recommends stopping smoking at least 4–6 weeks before and after surgery. Partial or full cessation during the healing period measurably improves osseointegration outcomes.' => 'يمكن للمدخّن أن يزرع، لكن التبغ يخفّض نِسب النجاح بوضوح لأنه يضعف تدفّق الدم والالتئام. وتنصح VeaHealth بشدّة بالتوقّف عن التدخين 4 إلى 6 أسابيع على الأقل قبل الجراحة وبعدها. والإقلاع الجزئي أو الكامل خلال فترة الالتئام يحسّن نتائج الاندماج العظمي تحسّناً ملموساً.',
		'VeaHealth uses premium xenograft (bovine-derived bone particles), allograft (processed human donor bone), or synthetic bone substitutes — all FDA/CE-approved and proven for maxillary sinus augmentation. Your surgeon selects the optimal material based on graft volume needed and healing timeline preferences.' => 'تستعمل VeaHealth طُعوماً من الفئة الأولى: حُبيبات عظم من مصدر بقري، أو عظم متبرّع بشري معالَج، أو بدائل عظم صناعية — وكلّها معتمَدة من FDA/CE ومُثبَتة في تعزيز الجيب الفكّي. ويختار جرّاحك المادة الأنسب حسب حجم الترقيع المطلوب والمدّة الزمنية المفضَّلة للالتئام.',
		'Zygomatic implants are designed for patients with severe upper jaw bone loss — typically <5mm of residual bone where conventional implants and sinus lifts are impossible. VeaHealth\'s surgeons assess eligibility during the 3D CBCT scan consultation. Not all severe bone loss cases require zygomatic implants.' => 'الغرسات الوجنية موجَّهة لمن فقدوا عظماً كثيراً في الفك العلوي — عادةً أقل من 5 مم من العظم المتبقّي، حيث تستحيل الغرسات التقليدية ورفع الجيب الفكّي. ويقيّم جرّاحو VeaHealth الأهلية أثناء استشارة أشعة CBCT ثلاثية الأبعاد. وليست كل حالات الفقد العظمي الشديد تستدعي غرسات وجنية.',
		'The procedure is performed under IV sedation or general anesthesia — you feel nothing during surgery. Post-op discomfort (swelling, soreness) peaks at 48–72 hours and is managed with prescribed pain medication. Most patients describe it as less painful than expected, comparable to multiple tooth extractions.' => 'يُجرى العمل تحت تركين وريدي أو تخدير عام — فلا تشعر بشيء أثناء الجراحة. أمّا الانزعاج بعدها (تورّم ووجع) فيبلغ ذروته بين 48 و72 ساعة ويُضبط بالمسكّنات الموصوفة. ويصفه معظم المرضى بأنه أقل ألماً ممّا توقّعوا، أشبه بخلع عدّة أسنان.',
		'An inlay fits within the tooth’s cusps (the raised points) and is used when the cusps are still structurally sound. An onlay extends over one or more cusps to provide additional protection and strength when the cusps are weakened. Your dentist will determine which is appropriate based on the extent of damage.' => 'تستقرّ حشوة الإنلاي بين حدبات السن، وتُستعمل حين تكون تلك الحدبات ما زالت متينة. أمّا الأونلاي فتمتدّ فوق حدبة أو أكثر لتحميها وتقوّيها حين تكون قد ضعفت. ويحدّد طبيبك المناسب منهما بحسب مدى الضرر.',
		'What this does not do: it does not increase graft survival, it does not make hair grow faster, and it does not substitute for the washing routine and medication you are sent home with. Anyone telling you otherwise is selling. If you would rather not have it, say so — nothing else about your treatment changes.' => 'ما لا يفعله هذا البروتوكول: لا يرفع نسبة بقاء الطُعوم، ولا يجعل الشعر ينمو أسرع، ولا يحلّ محلّ روتين الغسل والأدوية التي تعود بها إلى بيتك. ومن يقول لك غير ذلك فهو يبيع. وإن فضّلت ألّا تأخذه فقل ذلك — ولن يتغيّر شيء آخر في علاجك.',
		'The procedure itself is performed under local anesthesia or IV sedation — you won’t feel pain during surgery. Post-operative discomfort is typically mild to moderate, managed with prescribed pain medication. Swelling peaks at 48–72 hours and resolves within a week. Most patients return to work within 3–5 days.' => 'تُجرى العملية تحت تخدير موضعي أو تركين وريدي — فلا تشعر بألم أثناء الجراحة. أمّا الانزعاج بعدها فخفيف إلى متوسّط عادةً ويُضبط بالمسكّنات الموصوفة. ويبلغ التورّم ذروته بين 48 و72 ساعة ويزول خلال أسبوع. ويعود معظم المرضى إلى العمل خلال 3 إلى 5 أيام.',
		'Yes. E-max Lumineers can close small gaps, correct minor rotations, and reshape irregularly sized or positioned teeth without orthodontics. However, severe misalignment may require orthodontic correction first. VeaHealth’s dentists assess your case during the digital consultation and recommend the best approach.' => 'نعم. تستطيع قشور E-max إغلاق الفراغات الصغيرة، وتصحيح الدوران البسيط، وإعادة تشكيل أسنان غير متناسقة الحجم أو الموضع، دون تقويم. أمّا سوء الاصطفاف الشديد فقد يحتاج تقويماً أولاً. ويقيّم أطباء VeaHealth حالتك في الاستشارة الرقمية ويقترحون الطريق الأنسب.',
		'Almost always, yes — but a limited socket-fill graft. The gap between the implant surface and the socket walls must be filled with graft material to support bone formation and prevent soft tissue ingrowth. This is performed in the same appointment. It is far less extensive than a full bone augmentation procedure.' => 'في الغالب نعم — لكنه ترقيع محدود لملء السِنخ فقط. إذ يجب ملء الفجوة بين سطح الغرسة وجدران السِنخ بمادة ترقيع تدعم تكوّن العظم وتمنع نمو الأنسجة الرخوة داخلها. ويتم ذلك في الموعد نفسه، وهو أقل بكثير من عملية تطعيم عظمي كاملة.',
		'Hybrid offers advantages in repairability, cost, and weight, while zirconia excels in long-term durability and minimal maintenance. Hybrid is ideal for patients who want excellent aesthetics at a lower cost with easier future repairs. Zirconia is best for those prioritizing maximum longevity and stain resistance.' => 'تتفوّق التركيبة الهجينة في سهولة الإصلاح والتكلفة والوزن، بينما يتفوّق الزيركون في الدوام على المدى الطويل وقلّة الصيانة. فالهجينة مثالية لمن يريد مظهراً ممتازاً بتكلفة أقل وإصلاحات أسهل مستقبلاً، والزيركون أنسب لمن يضع طول العمر ومقاومة التصبّغ في المقام الأول.',
		'Yes. VeaHealth’s implant warranty covers both the fixture and the prosthetic components and is valid internationally. Full documentation is provided at treatment completion. If any warranty-covered issue arises after your return home, VeaHealth coordinates the resolution remotely or via a local affiliated clinic.' => 'نعم. يغطّي ضمان VeaHealth الغرسة والأجزاء التعويضية معاً، وهو ساري المفعول دولياً. وتُسلَّم لك الوثائق كاملةً عند انتهاء العلاج. وإذا ظهرت أي مشكلة مشمولة بالضمان بعد عودتك، تتولّى VeaHealth حلّها عن بُعد أو عبر عيادة شريكة قريبة منك.',
		'Yes. After full healing (4–6 months), you can eat all foods without restriction — including steak, nuts, and apples. Chewing power is restored to 90–95% of natural teeth. The zirconia teeth are exceptionally strong and can handle normal biting forces. Avoid extremely hard objects like ice to prevent rare chipping.' => 'نعم. بعد اكتمال الالتئام (4–6 أشهر) يمكنك أن تأكل كل شيء بلا قيد — اللحم والمكسّرات والتفاح. وتعود قوة المضغ إلى 90–95٪ من قوة الأسنان الطبيعية. وأسنان الزيركون شديدة القوة وتتحمّل قوى العضّ المعتادة. وتجنّب فقط الأشياء القاسية جداً كالثلج تفادياً لتشظٍّ نادر.',
		'A hybrid prosthesis combines porcelain teeth with an acrylic gum base, supported by a titanium framework that screws onto dental implants. It offers the natural appearance of porcelain with the repairability and lighter weight of acrylic — an ideal middle ground between full zirconia and traditional acrylic dentures.' => 'التركيبة الهجينة تجمع أسناناً خزفية مع قاعدة لثة أكريلية، محمولةً على هيكل تيتانيوم يُبرغَى على الغرسات. فتجمع بين المظهر الطبيعي للخزف وسهولة الإصلاح وخفّة الأكريل — وهي حلّ وسط مثالي بين الزيركون الكامل والأطقم الأكريلية التقليدية.',
		'All-on-6 is specifically designed for patients with moderate bone loss. The strategic angulation of posterior implants and the addition of two mid-arch implants often eliminates the need for bone grafting. VeaHealth identifies any grafting needs during pre-treatment planning and factors it into your timeline and quote.' => 'صُمّم All-on-6 خصيصاً لمن لديهم فقد عظمي متوسّط. فإمالة الغرسات الخلفية بزوايا محسوبة وإضافة غرستين في وسط الفك يُغنيان في الغالب عن الترقيع العظمي. وتحدّد VeaHealth أي حاجة إلى ترقيع أثناء التخطيط قبل العلاج وتدرجها في جدولك وعرض سعرك.',
		'Yes. Although zirconia teeth rarely chip due to their exceptional strength, the acrylic base allows for easier repairs compared to full monolithic zirconia. If damage occurs, chair-side bonding is often possible. Full monolithic zirconia requires lab work for any repair, making hybrid zirconium more practical long-term.' => 'نعم. نادراً ما تتشظّى أسنان الزيركون لشدّة قوّتها، كما أن القاعدة الأكريلية تجعل الإصلاح أسهل ممّا هو عليه في الزيركون أُحادي الكتلة الكامل. وإذا حدث ضرر، يمكن غالباً لصقه على كرسي العيادة. أمّا الزيركون الكامل فيتطلّب عملاً في المختبر لأي إصلاح، وهو ما يجعل الهجين أعملَ على المدى الطويل.',
		'Yes. E-max has exceptional translucency that mimics natural enamel perfectly. Unlike opaque composite veneers, E-max transmits light naturally — creating depth, vitality, and a lifelike appearance. Custom shade layering ensures seamless integration with your natural teeth. Results are indistinguishable from real enamel.' => 'نعم. يتمتّع E-max بشفافية استثنائية تحاكي المينا الطبيعية محاكاةً تامة. وبخلاف قشور الكومبوزيت المعتمة، ينفذ الضوء عبره بشكل طبيعي — فيمنح عمقاً وحيويةً ومظهراً حياً. ويضمن التلوين بطبقات حسب المقاس اندماجاً غير محسوس مع أسنانك. والنتيجة لا تُميَّز عن المينا الحقيقية.',
		'Once osseointegration is confirmed, you return to Istanbul for your final zirconia or ceramic crown — CAD/CAM milled, shade-matched, and precision-fitted to your dentition. The permanent crown is placed at full occlusion. Warranty documentation is issued. VeaHealth confirms ongoing remote support for continued aftercare.' => 'بعد تأكّد الاندماج العظمي، تعود إلى إسطنبول لتركيب تلبيستك النهائية من الزيركون أو الخزف — مصنَّعة بتقنية CAD/CAM، ومطابقة للون أسنانك، ومضبوطة بدقة على أسنانك. وتُركَّب التلبيسة الدائمة في إطباق كامل، وتُسلَّم لك وثائق الضمان. وتؤكّد VeaHealth استمرار الدعم عن بُعد للمتابعة اللاحقة.',
		'High-quality acrylic is resistant to staining but not completely immune. Smoking, coffee, and red wine can cause gradual discoloration over years. Professional polishing every 2–3 years restores the original appearance. This is a minor maintenance requirement compared to the benefits of repairability and natural aesthetics.' => 'الأكريل الجيد يقاوم التصبّغ لكنه ليس محصّناً منه تماماً. فالتدخين والقهوة والنبيذ الأحمر قد تُغيّر لونه تدريجياً على مرّ السنين. ويعيد التلميع الاحترافي كل 2 إلى 3 سنوات مظهره الأصلي. وهي صيانة يسيرة مقابل ما يمنحه من سهولة إصلاح ومظهر طبيعي.',
		'VeaHealth contractually guarantees Straumann and Nobel Biocare implants — both with surface technologies specifically validated for immediate placement protocols (SLActive and TiUnite respectively). Brand, model, and batch number are confirmed in writing at placement and included in your international warranty documentation.' => 'تضمن VeaHealth تعاقدياً غرسات Straumann وNobel Biocare — وكلتاهما بتقنيات سطحية مُثبَتة خصيصاً لبروتوكولات الزراعة الفورية (SLActive وTiUnite على الترتيب). وتُثبَّت الماركة والطراز ورقم التشغيلة كتابةً عند وضع الغرسة، وتُدرَج في وثائق ضمانك الدولي.',
		'If bone volume is insufficient, a graft is performed first — either with your own bone, donor bone, or synthetic material. The graft heals for 3–6 months before the implant is placed, extending the total timeline to 8–12 months. VeaHealth identifies the need before you travel and factors it into your treatment plan and quote.' => 'إذا كان حجم العظم غير كافٍ، يُجرى الترقيع أولاً — إمّا بعظم من جسمك، أو عظم متبرَّع به، أو مادة صناعية. ويلتئم الطُعم خلال 3 إلى 6 أشهر قبل وضع الغرسة، فترتفع المدّة الكلية إلى 8–12 شهراً. وتحدّد VeaHealth هذه الحاجة قبل سفرك وتدرجها في خطة علاجك وعرض السعر.',
		'Neither is better in every case. Manual extraction gives the surgeon more control per graft and is often preferred for curly hair, scarred donor areas and hairline work. Motorised extraction is faster and suits large sessions in straight, average-calibre hair. Your assessment will say which is being proposed for you, and why.' => 'لا واحدة منهما أفضل في كل الحالات. فالاقتطاف اليدوي يمنح الجرّاح تحكّماً أكبر في كل طُعم، ويُفضَّل غالباً للشعر المجعّد، وللمناطق المانحة ذات الندوب، ولعمل خط الشعر الأمامي. أمّا الاقتطاف الآلي فأسرع ويناسب الجلسات الكبيرة في الشعر المستقيم متوسّط السماكة. وسيقول لك تقييمك أيّهما يُقترَح عليك، ولماذا.',
		'Typically two trips: the first visit (2–4 days) for the CBCT assessment, extraction, immediate implant placement, and provisional crown; the return visit (1–2 days) after osseointegration for the definitive zirconia crown. The entire healing phase — 3–6 months — is managed remotely by VeaHealth with no travel required in between.' => 'عادةً رحلتان: الزيارة الأولى (2–4 أيام) لأشعة CBCT والخلع ووضع الغرسة الفورية والتلبيسة المؤقتة؛ وزيارة العودة (1–2 يوم) بعد الاندماج العظمي لتركيب تلبيسة الزيركون النهائية. أمّا مرحلة الالتئام كاملةً — 3 إلى 6 أشهر — فتديرها VeaHealth عن بُعد دون أي سفر بينهما.',
		'With proper care, hybrid zirconium prostheses last 15–20 years on average. The zirconia teeth are extremely durable and stain-proof. The acrylic gum base may require professional polishing every 3–4 years to maintain shine. This lifespan is significantly longer than traditional acrylic (5–8 years) and comparable to full zirconia.' => 'مع عناية سليمة، تدوم التركيبة الهجينة من الزيركون 15 إلى 20 سنة في المتوسط. فأسنان الزيركون شديدة المتانة ولا تتصبّغ. أمّا قاعدة اللثة الأكريلية فقد تحتاج تلميعاً احترافياً كل 3 إلى 4 سنوات للحفاظ على لمعانها. وهذا العمر أطول بكثير من الأكريل التقليدي (5 إلى 8 سنوات)، ويقارب عمر الزيركون الكامل.',
		'E-max veneers don’t respond to whitening treatments, but they also don’t need them — they never discolor. If you’re whitening natural teeth, do it before getting veneers so your dentist can match the veneer shade to your desired whiteness level. Your natural teeth can be whitened later, but veneers will remain their original shade.' => 'لا تستجيب قشور E-max لمستحضرات التبييض، لكنها لا تحتاجها أصلاً لأنها لا تتغيّر لونها أبداً. فإن أردت تبييض أسنانك الطبيعية، فافعل ذلك قبل تركيب القشور ليضبط طبيبك لون القشور على درجة البياض التي تريدها. ويمكن تبييض أسنانك الطبيعية لاحقاً، لكن القشور ستبقى بلونها الأصلي.',
		'High-quality acrylic is resistant to staining but not immune. Smoking, coffee, and red wine can cause gradual discoloration over years. Professional polishing every 3–4 years restores the original appearance. This is a minor trade-off considering the comfort, natural aesthetics, and repairability advantages of the acrylic gum base.' => 'الأكريل الجيد يقاوم التصبّغ لكنه ليس محصّناً منه. فالتدخين والقهوة والنبيذ الأحمر قد تُغيّر لونه تدريجياً على مرّ السنين. ويعيد التلميع الاحترافي كل 3 إلى 4 سنوات مظهره الأصلي. وهذا تنازل بسيط مقابل ما تمنحه القاعدة الأكريلية من راحة ومظهر طبيعي وسهولة إصلاح.',
		'An immediate dental implant is placed directly into the socket left by the extracted tooth in the same surgical appointment — combining extraction and implant placement into a single procedure. This contrasts with conventional (delayed) placement, where the socket heals for 4–8 weeks before the implant is placed in a separate surgery.' => 'الغرسة السنّية الفورية تُوضع مباشرةً في السِنخ الذي تركه السن المخلوع، في الموعد الجراحي نفسه — أي أن الخلع والزراعة يصبحان عملية واحدة. وهذا يختلف عن الزراعة التقليدية (المؤجَّلة)، حيث يُترك السِنخ ليلتئم من 4 إلى 8 أسابيع قبل وضع الغرسة في جراحة منفصلة.',
		'Smoking significantly increases failure risk in immediate implants — more so than in conventional protocol — because nicotine impairs vascular healing in the fresh socket environment. VeaHealth strongly advises cessation for a minimum of 6 weeks before and 8 weeks after surgery. This is the single most impactful modifiable risk factor.' => 'يرفع التدخين خطر فشل الغرسات الفورية ارتفاعاً ملحوظاً — أكثر مما يفعل في البروتوكول التقليدي — لأن النيكوتين يضعف التئام الأوعية الدموية داخل السِنخ الطازج. وتنصح VeaHealth بشدّة بالإقلاع 6 أسابيع على الأقل قبل الجراحة و8 أسابيع بعدها. وهذا هو أكثر عامل خطر يمكن للمريض تغييره تأثيراً على النتيجة.',
		'The primary risk is Schneiderian membrane perforation (occurs in 10–30% of cases, usually repaired immediately without consequence). Infection risk is <2% with antibiotic prophylaxis. Sinusitis is rare if post-op instructions are followed (no nose-blowing for 4 weeks). Graft failure is uncommon (<5%) in non-smokers with good oral hygiene.' => 'أكبر خطر هو ثقب غشاء شنايدر (يحدث في 10–30٪ من الحالات، ويُرمَّم فوراً دون عواقب في الغالب). وخطر الالتهاب أقل من 2٪ مع المضاد الحيوي الوقائي. أمّا التهاب الجيوب فنادر إذا اتُّبعت تعليمات ما بعد الجراحة (ممنوع تمخيط الأنف لمدّة 4 أسابيع). وفشل الطُعم غير شائع (أقل من 5٪) لدى غير المدخّنين ذوي نظافة الفم الجيدة.',
		'Yes, zirconia is stronger, more fracture-resistant, and more stain-proof than porcelain. Hybrid zirconium offers superior longevity (15–20 years vs 10–15 years for porcelain) and requires less maintenance. The cost difference is approximately 25% higher for zirconia, making it the premium choice for patients prioritizing maximum durability.' => 'نعم؛ فالزيركون أقوى وأكثر مقاومةً للكسر وأقلّ تصبّغاً من الخزف. والتركيبة الهجينة من الزيركون تدوم أطول (15–20 سنة مقابل 10–15 سنة للخزف) وتحتاج صيانة أقل. أمّا فرق التكلفة فنحو 25٪ زيادة للزيركون، وهو ما يجعله الخيار الأرقى لمن يضع الدوام في المقام الأول.',
		'In most cases, yes. When primary stability is sufficient (ISQ ≥ 65), a provisional crown is attached the same day as the implant placement — immediate provisionalization. The provisional is designed out of occlusion to protect the healing implant. Where stability is marginal, a healing cap is used and the provisional fitted at a later visit.' => 'في معظم الحالات نعم. فعندما يكون الثبات الابتدائي كافياً (ISQ ≥ 65)، تُركَّب تلبيسة مؤقتة في اليوم نفسه الذي تُوضع فيه الغرسة — وهو التعويض المؤقت الفوري. وتُصمَّم التلبيسة خارج الإطباق لحماية الغرسة أثناء التئامها. أمّا إذا كان الثبات على الحدّ الأدنى، فتُستعمل قبعة التئام وتُركَّب التلبيسة في زيارة لاحقة.',
		'Meta-analyses confirm no statistically significant difference in implant survival between immediate and delayed protocols in properly selected cases. Immediate placement achieves 90–96% survival at 5–10 years, comparable to conventional rates of 94–98%. The key is rigorous pre-operative patient selection — which VeaHealth conducts before any patient travels.' => 'تؤكّد التحليلات التجميعية أنه لا فرق ذا دلالة إحصائية في بقاء الغرسة بين البروتوكول الفوري والمؤجَّل في الحالات المنتقاة بعناية. فالزراعة الفورية تحقّق بقاءً بنسبة 90–96٪ بعد 5–10 سنوات، وهو قريب من نسبة 94–98٪ في البروتوكول التقليدي. والعامل الحاسم هو دقّة انتقاء المريض قبل الجراحة — وهو ما تقوم به VeaHealth قبل سفر أي مريض.',
		'The tooth is removed using atraumatic techniques — periotomes, luxators, and micro-surgical instruments — designed to preserve the socket walls and minimise bone trauma. Avoiding damage to the buccal plate is critical for long-term aesthetics. No traumatic force is applied that could fracture the socket architecture required to support the immediate implant.' => 'يُخلع السن بتقنيات غير رضّية — مباضع اللثة والرافعات الدقيقة وأدوات الجراحة المجهرية — مصمَّمة للحفاظ على جدران السِنخ وتقليل رضّ العظم. وتجنّب إصابة الصفيحة العظمية الخارجية أمر حاسم للنتيجة الجمالية على المدى الطويل. ولا تُستعمل أي قوة رضّية قد تكسر بنية السِنخ التي تحتاجها الغرسة الفورية لتستند عليها.',
		'If CBCT confirms adequate bone, intact socket walls, and no acute infection, immediate placement is confirmed and the implant dimensions are selected virtually. If eligibility criteria are not met, VeaHealth’s team presents the conventional protocol with full transparency — before any surgery proceeds. No patient travels for a procedure they are not suited for.' => 'إذا أكّدت أشعة CBCT وجود عظم كافٍ وجدران سِنخ سليمة وغياب التهاب حاد، تُعتمد الزراعة الفورية وتُختار أبعاد الغرسة رقمياً. وإذا لم تتوفّر شروط الأهلية، يعرض فريق VeaHealth البروتوكول التقليدي بشفافية كاملة — قبل إجراء أي جراحة. ولا يسافر أي مريض من أجل إجراء لا يناسبه.',
		'A hybrid zirconium prosthesis combines high-strength zirconia teeth with an acrylic gum base, supported by a titanium framework that screws onto dental implants. It offers the exceptional durability and stain-resistance of zirconia with the natural appearance and comfort of acrylic — superior to traditional acrylic while more affordable than full monolithic zirconia.' => 'التركيبة الهجينة من الزيركون تجمع أسناناً من زيركون عالي القوة مع قاعدة لثة أكريلية، محمولةً على هيكل تيتانيوم يُبرغَى على الغرسات. فتجمع بين دوام الزيركون ومقاومته للتصبّغ، وبين المظهر الطبيعي والراحة في الأكريل — وهي أفضل من الأكريل التقليدي وأقل تكلفة من الزيركون أُحادي الكتلة الكامل.',
		'Eligibility requires: no acute infection at the extraction site, intact or near-intact socket walls, sufficient bone beyond the socket apex for primary stability, and confirmation of adequate primary stability (ISQ ≥ 60–65) at placement. VeaHealth evaluates eligibility from your CBCT scan before you travel — so you know whether immediate placement is viable before booking.' => 'تشترط الأهلية: غياب أي التهاب حاد في موضع الخلع، وجدران سِنخ سليمة أو شبه سليمة، وعظماً كافياً وراء قاع السِنخ لتحقيق الثبات الابتدائي، وتأكيد ثبات ابتدائي كافٍ (ISQ ≥ 60–65) عند الوضع. وتقيّم VeaHealth أهليتك من أشعة CBCT قبل سفرك — فتعرف هل الزراعة الفورية ممكنة قبل أن تحجز.',
		'Bone fuses to the implant surface over 3–6 months. VeaHealth’s remote aftercare programme provides structured digital check-ins, photo assessments, and coordinator access throughout — no travel required during this phase. Because the implant sits in a fresh socket, surrounding bone remodels around it, producing excellent long-term integration when primary stability was confirmed.' => 'يلتحم العظم بسطح الغرسة خلال 3 إلى 6 أشهر. ويوفّر برنامج المتابعة عن بُعد من VeaHealth مراجعات رقمية منتظمة، وتقييماً بالصور، وتواصلاً دائماً مع المنسّق طوال هذه المرحلة — دون حاجة إلى أي سفر. ولأن الغرسة موضوعة في سِنخ طازج، يُعيد العظم المحيط تشكّله حولها، فينتج اندماج ممتاز على المدى الطويل متى تأكّد الثبات الابتدائي.',
		'All-on-6 offers enhanced stability, better load distribution, and reduced cantilever length compared to All-on-4. It’s particularly beneficial for patients with moderate bone loss or those seeking maximum long-term stability. Studies show slightly higher success rates and fewer prosthetic complications. However, All-on-4 remains an excellent option for patients with good bone density.' => 'يمنح All-on-6 ثباتاً أعلى، وتوزيعاً أفضل للقوى، وامتداداً حرّاً أقصر مقارنةً بـAll-on-4. وهو مفيد بوجه خاص لمن لديهم فقد عظمي متوسّط أو لمن يريد أقصى ثبات على المدى الطويل. وتُظهر الدراسات نِسب نجاح أعلى قليلاً ومضاعفات تعويضية أقل. ومع ذلك يبقى All-on-4 خياراً ممتازاً لمن لديه كثافة عظم جيدة.',
		'When primary stability is confirmed (ISQ ≥ 65), a provisional crown is placed the same day — immediate provisionalization. The provisional is designed out of occlusion (no contact with opposing teeth during biting) to protect the healing implant. You leave Istanbul with a complete tooth. Where stability is marginal, a healing cap is used and the provisional fitted at a follow-up visit.' => 'عند تأكّد الثبات الابتدائي (ISQ ≥ 65)، تُركَّب تلبيسة مؤقتة في اليوم نفسه — وهو ما يُسمّى التعويض المؤقت الفوري. وتُصمَّم التلبيسة خارج الإطباق (لا تلامس الأسنان المقابلة عند العض) لحماية الغرسة أثناء التئامها. وتغادر إسطنبول بسنّ كاملة. أمّا إذا كان الثبات على الحدّ الأدنى، فتُستعمل قبعة التئام وتُركَّب التلبيسة المؤقتة في زيارة لاحقة.',
		'Full clinical examination with CBCT cone beam 3D imaging maps the extraction socket — assessing bone height, width, cortical wall integrity, and proximity to critical anatomy. The scan screens for periapical infection or bone pathology that would contraindicate immediate placement. Your VeaHealth coordinator attends throughout. This scan determines eligibility before any surgery is planned.' => 'فحص سريري كامل مع تصوير CBCT ثلاثي الأبعاد يرسم خريطة سِنخ السن المخلوع — يقيس ارتفاع العظم وعرضه، وسلامة الجدران القشرية، وقربها من التراكيب التشريحية الحسّاسة. وتكشف الأشعة أي التهاب حول ذروة الجذر أو مرض عظمي يمنع الزراعة الفورية. ويحضر منسّق VeaHealth معك طوال الوقت. هذه الأشعة هي التي تحدّد أهليتك قبل التخطيط لأي جراحة.',
		'The titanium implant — Straumann or Nobel Biocare — is placed directly into the fresh socket. It is positioned slightly palatally and apically to engage solid native bone beyond the socket tip for primary stability. The gap between the implant and socket walls is filled with bone graft material to support new bone formation and prevent soft tissue ingrowth. Primary stability is measured — it must exceed the minimum threshold (ISQ ≥ 60) before the provisional crown is placed.' => 'تُوضع الغرسة التيتانيومية — Straumann أو Nobel Biocare — مباشرةً في السِنخ الطازج، مائلةً قليلاً نحو الحنك وإلى العمق لتثبت في العظم الأصلي وراء قاع السِنخ وتحقّق الثبات الابتدائي. وتُملأ الفجوة بين الغرسة وجدران السِنخ بمادة ترقيع عظمي تدعم تكوّن عظم جديد وتمنع نمو الأنسجة الرخوة داخلها. ويُقاس الثبات الابتدائي، ويجب أن يتجاوز الحد الأدنى (ISQ ≥ 60) قبل تركيب التلبيسة المؤقتة.',
	),
);
